def get_container_width_for_icons():
    """根据当前图标大小计算一行（大10/中12/小14）所需容器宽度"""
    try:
        cfg_path = os.path.join(app_dir(), CONFIG_FILE)
        size_key = "medium"
        if os.path.exists(cfg_path):
            import json
            with open(cfg_path, 'r', encoding='utf-8') as f:
                cfg_data = json.load(f)
            size_key = cfg_data.get("icon_size", "medium")
        size = ICON_SIZES.get(size_key, ICON_SIZES["medium"])
        grid_w = size["w"] + 10
        n = PER_ROW.get(size_key, 12)
        return 8 + n * grid_w + 8
    except Exception:
        pass
    return 8 + 12 * (ICON_W + 10) + 8

def get_container_width_for_12_icons():
    """旧名兼容：等价于按当前档计算一行宽度"""
    return get_container_width_for_icons()
