def _dechunk_body(b):
    """解码 HTTP chunked 传输体"""
    out = b""
    while b:
        line, _, rest = b.partition(b"\r\n")
        try:
            n = int(line.split(b";")[0], 16)
        except Exception:
            break
        if n == 0:
            break
        out += rest[:n]
        b = rest[n+2:]
    return out

# 本机缺 _unicodedata，导致 idna 编码不可用；天气接口均为纯ASCII域名（IDNA结果即其本身），
# 让 ssl 直接用 ascii 编码 hostname，保留 SNI 与证书校验
try:
    import ssl as _ssl_mod
    _ssl_mod.SSLContext._encode_hostname = (
        lambda self, hostname: hostname.encode("ascii").decode("ascii"))
except Exception:
    pass

def _http_json(url, timeout=12):
    """手动 socket/ssl 请求并解析 JSON，绕过 urllib 对 idna 编码的依赖（本机缺 _unicodedata）"""
    import socket, ssl
    if url.startswith("https://"):
        rest, use_ssl, dport = url[8:], True, 443
    else:
        rest, use_ssl, dport = url[7:], False, 80
    if "/" in rest:
        hp, path = rest.split("/", 1); path = "/" + path
    else:
        hp, path = rest, "/"
    if ":" in hp:
        host, port = hp.split(":", 1); port = int(port)
    else:
        host, port = hp, dport
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.settimeout(timeout)
    if use_ssl:
        ctx = ssl.create_default_context()
        sock = ctx.wrap_socket(sock, server_hostname=host)
    sock.connect((host, port))  # 直接 connect，C层解析ASCII域名，绕过 socket.py 的 idna
    req = ("GET " + path + " HTTP/1.1\r\nHost: " + host + "\r\n"
           "User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120.0\r\n"
           "Accept: application/json\r\nConnection: close\r\n\r\n")
    sock.sendall(req.encode("ascii"))
    buf = b""
    while True:
        c = sock.recv(8192)
        if not c:
            break
        buf += c
    sock.close()
    head, _, body = buf.partition(b"\r\n\r\n")
    heads = head.decode("latin-1", "ignore").lower()
    if "transfer-encoding: chunked" in heads:
        body = _dechunk_body(body)
    return json.loads(body.decode("utf-8", "ignore"))

def fetch_weather_7d():
    """IP定位(ipwho.is) + BigDataCloud反查省市区 + Open-Meteo ICON 7日预报"""
    # 用 ipwho.is 获取坐标（比 ip-api 更准）
    loc = _http_json("https://ipwho.is/", 10)
    if not loc or not loc.get("success"):
        # fallback ip-api
        loc = _http_json("http://ip-api.com/json/?lang=zh-CN&fields=status,city,regionName,lat,lon", 8)
        if not loc or loc.get("status") != "success":
            raise RuntimeError("IP定位失败")
        lat, lon = loc["lat"], loc["lon"]
        region = (loc.get("regionName","") or "") + (loc.get("city","") or "")
    else:
        lat, lon = loc["latitude"], loc["longitude"]
        region = ""
    # 用 BigDataCloud 反查省/市/区
    try:
        _geo = _http_json(
            f"https://api.bigdatacloud.net/data/reverse-geocode-client?latitude={lat}&longitude={lon}&localityLanguage=zh",
            10)
        if _geo:
            _prov = (_geo.get("principalSubdivision", "") or "").strip()
            _city = (_geo.get("city", "") or "").strip()
            _dist = (_geo.get("locality", "") or "").strip().replace("區", "区")
            _parts = []
            for _p in (_prov, _city, _dist):
                if _p and (not _parts or _p != _parts[-1]):
                    _parts.append(_p)
            # 只保留省+市，不保留区/县
            if len(_parts) >= 2:
                region = _parts[0] + _parts[1]
            elif len(_parts) == 1:
                region = _parts[0]
            else:
                region = ""
    except Exception:
        pass
    # 读取配置文件里的自定义地区名（优先使用）
    _BUILTIN_CITIES = {
        "北京": (39.9075, 116.3972), "上海": (31.2304, 121.4737),
        "广州": (23.1291, 113.2644), "深圳": (22.5431, 114.0579),
        "杭州": (30.2741, 120.1551), "南京": (32.0603, 118.7969),
        "成都": (30.5728, 104.0668), "重庆": (29.5630, 106.5516),
        "武汉": (30.5928, 114.3055), "西安": (34.3416, 108.9398),
        "苏州": (31.2989, 120.5853), "天津": (39.3434, 117.3616),
        "长沙": (28.2278, 112.9388), "郑州": (34.7466, 113.6254),
        "青岛": (36.0671, 120.3826), "沈阳": (41.8057, 123.4315),
        "大连": (38.9140, 121.6147), "厦门": (24.4798, 118.0894),
        "福州": (26.0745, 119.2965), "昆明": (25.0389, 102.7183),
        "贵阳": (26.6470, 106.6302), "南宁": (22.8170, 108.3669),
        "兰州": (36.0611, 103.8343), "乌鲁木齐": (43.8256, 87.6168),
        "拉萨": (29.6520, 91.7210), "哈尔滨": (45.8038, 126.5350),
        "长春": (43.8171, 125.3235), "石家庄": (38.0428, 114.5149),
        "太原": (37.8706, 112.5489), "合肥": (31.8206, 117.2272),
        "南昌": (28.6820, 115.8579), "海口": (20.0440, 110.1999),
        "银川": (38.4872, 106.2309), "西宁": (36.6171, 101.7782),
        "呼和浩特": (40.8426, 111.7492), "宁波": (29.8683, 121.5440),
        "无锡": (31.4912, 120.3119), "佛山": (23.0215, 113.1214),
        "东莞": (23.0207, 113.7518), "珠海": (22.2710, 113.5767),
        "新都区": (30.8135, 104.1530), "武侯区": (30.6417, 104.0439),
        "青羊区": (30.6749, 104.0615), "锦江区": (30.6582, 104.0812),
        "成华区": (30.6635, 104.1136), "金牛区": (30.6918, 104.0540),
        "双流区": (30.5744, 103.9269),
    }
    try:
        _cfg_path = os.path.join(app_dir(), CONFIG_FILE)
        if os.path.exists(_cfg_path):
            with open(_cfg_path, "r", encoding="utf-8-sig") as _f:
                _cfg = json.load(_f)
            _custom = (_cfg.get("weather_region", "") or "").strip()
            if _custom:
                region = _custom
                # 用内置城市坐标表
                if _custom in _BUILTIN_CITIES:
                    lat, lon = _BUILTIN_CITIES[_custom]
                    region = "四川省成都市" + _custom if _custom.endswith("区") else _custom
    except Exception:
        pass
    wurl = (f"https://api.open-meteo.com/v1/forecast?latitude={lat}&longitude={lon}"
            "&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max"
            "&current=temperature_2m,weather_code"
            "&forecast_days=7&timezone=auto&models=icon_seamless")
    fc = _http_json(wurl, 12)
    d = fc["daily"]
    cur = fc.get("current", {})
    cur_temp = round(float(cur.get("temperature_2m", 0)), 1) if cur else None
    cur_code = int(cur.get("weather_code", 0)) if cur else None
    days = []
    for i in range(len(d["time"])):
        code = int(d["weather_code"][i])
        desc, icon = WMO_WEATHER.get(code, ("未知", "❓"))
        days.append({
            "date": d["time"][i], "code": code, "desc": desc, "icon": icon,
            "tmax": round(float(d["temperature_2m_max"][i]), 1),
            "tmin": round(float(d["temperature_2m_min"][i]), 1),
            "pop": int(d["precipitation_probability_max"][i] or 0),
        })
    return {"fetch_date": time.strftime("%Y-%m-%d"), "region": region,
            "lat": lat, "lon": lon, "days": days,
            "cur_temp": cur_temp, "cur_code": cur_code}

def load_weather_cache():
    try:
        p = os.path.join(app_dir(), WEATHER_CACHE_FILE)
        if os.path.exists(p):
            with open(p, "r", encoding="utf-8") as f:
                return json.load(f)
    except Exception:
        pass
    return None

def save_weather_cache(data):
    try:
        p = os.path.join(app_dir(), WEATHER_CACHE_FILE)
        with open(p, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=1)
    except Exception:
        pass

def weather_cache_fresh(data):
    """缓存1日内有效：获取日距今不超过1天，有cur_temp字段，且days覆盖今天"""
    try:
        from datetime import datetime as _dt, timedelta as _td
        fd = _dt.strptime(data.get("fetch_date"), "%Y-%m-%d")
        today = _dt.strptime(time.strftime("%Y-%m-%d"), "%Y-%m-%d")
        if today - fd > _td(days=1):
            return False
        # 旧缓存没有 cur_temp 字段，视为过期
        if "cur_temp" not in data:
            return False
        today_s = today.strftime("%Y-%m-%d")
        return any(x.get("date") == today_s for x in data.get("days", []))
    except Exception:
        return False

class _WeatherClickFilter(QObject):
    """天气胶囊点击过滤器：单击 -> 打开7日预报弹窗"""
    def __init__(self, cb):
        super().__init__()
        self._cb = cb
    def eventFilter(self, obj, ev):
        try:
            from PySide6.QtCore import QEvent
            if ev.type() == QEvent.MouseButtonRelease:
                self._cb()
        except Exception:
            pass
        return False


