# ============================================================
# 工具函数
# ============================================================

def app_dir():
    if getattr(sys, 'frozen', False):
        return os.path.dirname(sys.executable)
    return os.path.dirname(os.path.abspath(__file__))


def resource_path(name):
    """查找打包资源（如图标/翻译）：PyInstaller 打包后优先 _MEIPASS，其次 exe/源码目录。返回路径或 None。"""
    try:
        if getattr(sys, 'frozen', False):
            _meipass = getattr(sys, '_MEIPASS', '')
            if _meipass:
                p = os.path.join(_meipass, name)
                if os.path.exists(p):
                    return p
        p = os.path.join(app_dir(), name)
        if os.path.exists(p):
            return p
    except Exception:
        pass
    return None


def setup_chinese_context_menu(widget):
    """给 QLineEdit 设置中文右键菜单（复制/剪切/粘贴/撤销/删除/全选）"""
    try:
        from PySide6.QtWidgets import QMenu
        from PySide6.QtGui import QAction
        from PySide6.QtGui import QKeySequence
        from PySide6.QtCore import Qt
        widget.setContextMenuPolicy(Qt.CustomContextMenu)
        def _show_menu(pos):
            menu = QMenu(widget)
            act_undo = QAction("撤销", widget)
            act_undo.setShortcut(QKeySequence.Undo)
            act_undo.triggered.connect(widget.undo)
            menu.addAction(act_undo)
            menu.addSeparator()
            act_cut = QAction("剪切", widget)
            act_cut.setShortcut(QKeySequence.Cut)
            act_cut.triggered.connect(widget.cut)
            menu.addAction(act_cut)
            act_copy = QAction("复制", widget)
            act_copy.setShortcut(QKeySequence.Copy)
            act_copy.triggered.connect(widget.copy)
            menu.addAction(act_copy)
            act_paste = QAction("粘贴", widget)
            act_paste.setShortcut(QKeySequence.Paste)
            act_paste.triggered.connect(widget.paste)
            menu.addAction(act_paste)
            menu.addSeparator()
            act_del = QAction("删除", widget)
            act_del.setShortcut(QKeySequence.Delete)
            act_del.triggered.connect(lambda: widget.del_() if hasattr(widget, 'del_') else widget.insert(""))
            menu.addAction(act_del)
            act_sel = QAction("全选", widget)
            act_sel.setShortcut(QKeySequence.SelectAll)
            act_sel.triggered.connect(widget.selectAll)
            menu.addAction(act_sel)
            menu.exec(widget.mapToGlobal(pos))
        widget.customContextMenuRequested.connect(_show_menu)
    except Exception as e:
        print(f"[setup_chinese_context_menu error] {e}")


# 自定义中文右键菜单的 QLineEdit 子类（最可靠，重写 contextMenuEvent）
from PySide6.QtWidgets import QLineEdit as _QLineEdit, QMenu as _QMenu
from PySide6.QtGui import QKeySequence as _QKS, QAction as _QAction
class CnLineEdit(_QLineEdit):
    """QLineEdit 子类，右键菜单显示中文"""
    def contextMenuEvent(self, event):
        _m = _QMenu(self)
        _a1 = _QAction("撤销", self); _a1.setShortcut(_QKS.Undo); _a1.triggered.connect(self.undo); _m.addAction(_a1)
        _m.addSeparator()
        _a2 = _QAction("剪切", self); _a2.setShortcut(_QKS.Cut); _a2.triggered.connect(self.cut); _m.addAction(_a2)
        _a3 = _QAction("复制", self); _a3.setShortcut(_QKS.Copy); _a3.triggered.connect(self.copy); _m.addAction(_a3)
        _a4 = _QAction("粘贴", self); _a4.setShortcut(_QKS.Paste); _a4.triggered.connect(self.paste); _m.addAction(_a4)
        _m.addSeparator()
        _a5 = _QAction("删除", self); _a5.setShortcut(_QKS.Delete); _a5.triggered.connect(lambda: self.del_() if hasattr(self, 'del_') else self.insert("")); _m.addAction(_a5)
        _a6 = _QAction("全选", self); _a6.setShortcut(_QKS.SelectAll); _a6.triggered.connect(self.selectAll); _m.addAction(_a6)
        _m.exec(event.globalPos())


# 全局中文菜单事件过滤器（最可靠，直接拦截事件）
class _CnContextMenuFilter:
    """给任意控件安装中文右键菜单的事件过滤器"""
    def __init__(self):
        from PySide6.QtCore import QObject
        self._obj = QObject()
    def install(self, widget):
        from PySide6.QtCore import QEvent
        from PySide6.QtWidgets import QMenu
        from PySide6.QtGui import QAction
        from PySide6.QtGui import QKeySequence
        class _Filter(QObject):
            def eventFilter(self, _obj, _event):
                if _event.type() == QEvent.ContextMenu:
                    _m = QMenu(widget)
                    _a1 = QAction("撤销", widget); _a1.setShortcut(QKeySequence.Undo); _a1.triggered.connect(widget.undo); _m.addAction(_a1)
                    _m.addSeparator()
                    _a2 = QAction("剪切", widget); _a2.setShortcut(QKeySequence.Cut); _a2.triggered.connect(widget.cut); _m.addAction(_a2)
                    _a3 = QAction("复制", widget); _a3.setShortcut(QKeySequence.Copy); _a3.triggered.connect(widget.copy); _m.addAction(_a3)
                    _a4 = QAction("粘贴", widget); _a4.setShortcut(QKeySequence.Paste); _a4.triggered.connect(widget.paste); _m.addAction(_a4)
                    _m.addSeparator()
                    _a5 = QAction("删除", widget); _a5.setShortcut(QKeySequence.Delete); _a5.triggered.connect(lambda: widget.del_() if hasattr(widget, 'del_') else widget.insert("")); _m.addAction(_a5)
                    _a6 = QAction("全选", widget); _a6.setShortcut(QKeySequence.SelectAll); _a6.triggered.connect(widget.selectAll); _m.addAction(_a6)
                    _m.exec(_event.globalPos())
                    return True
                return False
        self._filter = _Filter()
        widget.installEventFilter(self._filter)
        widget._cn_filter = self._filter  # 防止垃圾回收

def format_version(ver):
    """把版本号格式化为 V7.0 显示格式（去掉末尾的.0）"""
    try:
        parts = str(ver).lstrip('vV').split('.')
        if len(parts) >= 3 and parts[2] == '0':
            return "V" + ".".join(parts[:2])
        return "V" + str(ver).lstrip('vV')
    except Exception:
        return f"V{ver}"


def compare_versions(v1, v2):
    """比较两个版本号，返回 -1(v1<v2), 0(v1=v2), 1(v1>v2)"""
    try:
        # 移除前缀 'v' 或 'V'
        v1 = v1.lstrip('vV')
        v2 = v2.lstrip('vV')
        # 分割版本号
        parts1 = [int(x) for x in v1.split('.')]
        parts2 = [int(x) for x in v2.split('.')]
        # 补齐长度
        max_len = max(len(parts1), len(parts2))
        parts1.extend([0] * (max_len - len(parts1)))
        parts2.extend([0] * (max_len - len(parts2)))
        # 逐位比较
        for p1, p2 in zip(parts1, parts2):
            if p1 < p2:
                return -1
            elif p1 > p2:
                return 1
        return 0
    except Exception as e:
        print(f"[compare_versions error] {e}")
        return 0


def parse_update_html(html_text):
    """解析HTML网页中的版本信息
    HTML格式示例:
    <!-- 雪之下倾城版本信息 -->
    <div class="version">7.2.0</div>
    <div class="download_url">https://example.com/setup.exe</div>
    <div class="release_date">2026-09-07</div>
    <div class="notice">更新公告第一行\n更新公告第二行</div>
    """
    import re
    result = {"version": "", "download_url": "", "download_url2": "", "download_password": "", "notice": "", "release_date": "", "update_content": ""}
    try:
        # 版本号: 匹配常见版本号模式 (数字.数字.数字)
        m = re.search(r'class=["\']version["\']\s*>\s*([^<]+)', html_text, re.IGNORECASE)
        if m:
            result["version"] = m.group(1).strip()
        # 下载地址: 匹配URL
        m = re.search(r'class=["\']download_url["\']\s*>\s*([^<]+)', html_text, re.IGNORECASE)
        if m:
            result["download_url"] = m.group(1).strip()
        # 备用下载地址（主地址失效时自动切换）
        m = re.search(r'class=["\']download_url2["\']\s*>\s*([^<]+)', html_text, re.IGNORECASE)
        if m:
            result["download_url2"] = m.group(1).strip()
        # 网盘访问密码（如蓝奏云带密码链接）
        m = re.search(r'class=["\']download_password["\']\s*>\s*([^<]+)', html_text, re.IGNORECASE)
        if m:
            result["download_password"] = m.group(1).strip()
        m = re.search(r'class=["\']release_date["\']\s*>\s*([^<]+)', html_text, re.IGNORECASE)
        if m:
            result["release_date"] = m.group(1).strip()
        # 公告: 可能有多行，匹配到 </div> 或注释结束（精确匹配 class="notice"，避免误匹配 notice-box）
        m = re.search(r'class=["\']notice["\']\s*>\s*(.*?)(?:</div>|<!--)', html_text, re.IGNORECASE | re.DOTALL)
        if m:
            notice_text = m.group(1).strip()
            # 移除HTML标签
            notice_text = re.sub(r'<br\s*/?>', '\n', notice_text)
            notice_text = re.sub(r'<[^>]+>', '', notice_text)
            result["notice"] = notice_text
        # 更新内容（与滚动公告分开）: class="update_content"
        m = re.search(r'class=["\']update_content[^"\']*["\']\s*>\s*(.*?)(?:</div>|<!--)', html_text, re.IGNORECASE | re.DOTALL)
        if m:
            uc_text = m.group(1).strip()
            # 列表项 <li> 转圆点
            uc_text = re.sub(r'</li>\s*<li>', '\n', uc_text)
            uc_text = re.sub(r'<li>', '• ', uc_text)
            uc_text = re.sub(r'<br\s*/?>', '\n', uc_text)
            uc_text = re.sub(r'<[^>]+>', '', uc_text)
            result["update_content"] = uc_text
    except Exception as e:
        print(f"[parse_update_html error] {e}")
    return result


# GBK解码UTF-8产生的典型乱码字符（用于检测缓存里的乱码文本）
_GARBLE_CHARS = set('娆㈣繋銆屾偍嶄娇鐢ㄥ楂樼増娓告垙鑿滃崟锛乗閰嶄欢鏂板惎鍔ㄤ慨澶?銆愭柊鐗堝彉')


def _looks_garbled(s):
    """检测文本是否为GBK乱码（含>=2个乱码特征字符判定为乱码）"""
    if not s:
        return False
    try:
        n = sum(1 for ch in str(s) if ch in _GARBLE_CHARS)
        return n >= 2
    except Exception:
        return False


def _cache_path():
    """本地缓存文件路径（运行目录，打包后为exe所在目录）"""
    try:
        base = os.path.dirname(os.path.abspath(sys.argv[0]))
    except Exception:
        base = os.getcwd()
    return os.path.join(base, "update_cache.json")


def load_update_cache():
    """读取上次成功获取的版本/公告缓存（启动时立即显示，不阻塞；乱码字段丢弃）"""
    import json
    try:
        cp = _cache_path()
        if os.path.exists(cp):
            with open(cp, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if data and isinstance(data, dict):
                for k in ("notice", "update_content", "release_date"):
                    if _looks_garbled(data.get(k, "")):
                        data[k] = ""
                return data
    except Exception:
        pass
    return None


def save_update_cache(data):
    """保存版本/公告缓存（下次启动立即显示；乱码字段不写入）"""
    import json
    try:
        if data and isinstance(data, dict):
            for k in ("notice", "update_content", "release_date"):
                if _looks_garbled(data.get(k, "")):
                    data[k] = ""
        cp = _cache_path()
        with open(cp, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
    except Exception:
        pass


def check_for_updates():
    """检查软件更新（通过HTML网页），主/备用URL并行请求，返回最快结果。
    返回 (has_update, latest_version, download_url, download_url2, download_password, notice, release_date, update_content, error)"""
    from concurrent.futures import ThreadPoolExecutor
    urls = [UPDATE_CHECK_URL, UPDATE_CHECK_URL_BACKUP]
    last_err = ""

    def fetch_one(url):
        try:
            # 完全手动解析 URL，不用 urllib，绕过 idna 编码问题
            import socket
            # 去掉 http://
            if url.startswith('http://'):
                rest = url[7:]
            else:
                rest = url
            # 分离主机和路径
            if '/' in rest:
                host_part, path_part = rest.split('/', 1)
                path = '/' + path_part
            else:
                host_part = rest
                path = '/'
            # 分离端口
            if ':' in host_part:
                host, port_str = host_part.split(':', 1)
                port = int(port_str)
            else:
                host = host_part
                port = 80
            # 直接用 socket，不用 create_connection，避免触发 idna 编码
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(15)
            sock.connect((host, port))
            request = "GET " + path + " HTTP/1.1\r\nHost: " + host + "\r\nUser-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36\r\nConnection: close\r\n\r\n"
            sock.sendall(request.encode('ascii'))
            # 接收响应
            response = b''
            while True:
                data = sock.recv(4096)
                if not data:
                    break
                response += data
            sock.close()
            # 去掉 HTTP 头，只保留内容
            text = response.decode('utf-8', errors='ignore')
            # 找到空行，分隔头和内容
            if '\r\n\r\n' in text:
                text = text.split('\r\n\r\n', 1)[1]
            return text
        except Exception as e:
            # 记录错误信息
            try:
                with open('fetch_error.log', 'a', encoding='utf-8') as f:
                    import datetime
                    line = str(datetime.datetime.now()) + ' ' + url + ' -> ' + type(e).__name__ + ': ' + str(e) + '\n'
                    f.write(line)
            except Exception:
                pass
            return None

    html_texts = []
    with ThreadPoolExecutor(max_workers=2) as ex:
        futures = [ex.submit(fetch_one, u) for u in urls]
        for f in futures:
            try:
                r = f.result()
                if r:
                    html_texts.append(r)
            except Exception as e:
                last_err = str(e)
    if not html_texts:
        return (False, "", "", "", "", "", "", "", f"所有更新检查URL均失败: {last_err}")
    try:
        info = parse_update_html(html_texts[0])
        latest_version = info["version"] or "0.0.0"
        download_url = info["download_url"]
        download_url2 = info.get("download_url2", "")
        download_password = info.get("download_password", "")
        notice = info["notice"]
        release_date = info["release_date"]
        update_content = info["update_content"]
        # 比较版本
        cmp_result = compare_versions(APP_VERSION, latest_version)
        has_update = cmp_result < 0
        return (has_update, latest_version, download_url, download_url2, download_password, notice, release_date, update_content, None)
    except Exception as e:
        print(f"[check_for_updates parse error] {e}")
        return (False, "", "", "", "", "", "", "", str(e))


def _guess_filename(url):
    """从下载地址提取文件名（支持 query 中的 filename* 参数）"""
    from urllib.parse import unquote, urlparse, parse_qs
    if not url:
        return None
    try:
        # 1. 从 query 的 response-content-disposition / filename* 提取
        qs = parse_qs(urlparse(url).query)
        cd = qs.get('response-content-disposition', [None])[0]
        if cd:
            m = re.search(r"filename\*=(?:UTF-8'')?([^;]+)", cd)
            if m:
                n = unquote(unquote(m.group(1).strip()))
                if n and '%' not in n:
                    return n
        # 2. 从 basename 提取
        raw = os.path.basename(url.split('?')[0].split('#')[0])
        n = unquote(raw)
        if n and '.' in n and '%' not in n:
            return n
    except Exception:
        pass
    return None


def _extract_cd_filename(cd):
    """从响应头 Content-Disposition 提取文件名"""
    from urllib.parse import unquote
    if not cd:
        return None
    try:
        m = re.search(r"filename\*=(?:UTF-8'')?([^;]+)", cd)
        if m:
            n = unquote(unquote(m.group(1).strip()))
            if n and '%' not in n:
                return n
        m = re.search(r'filename="?([^";]+)"?', cd)
        if m:
            n = unquote(m.group(1).strip())
            if n and '%' not in n:
                return n
    except Exception:
        pass
    return None


def url_file_ext(url):
    # 识别下载地址文件类型: 'exe' / 'zip' / None(其他格式)
    # 自动忽略链接中的 ?query 和 #fragment
    if not url:
        return None
    clean = url.split('?')[0].split('#')[0].lower()
    if clean.endswith('.exe'):
        return 'exe'
    if clean.endswith('.zip'):
        return 'zip'
    return None


def is_exe_url(url):
    """判断下载地址是否是exe文件"""
    return url_file_ext(url) == 'exe'


def download_file(url, save_path, progress_callback=None):
    """下载文件，支持进度回调。返回 (ok, error_type, real_name)
    error_type: None=成功 / 'invalid_link'=链接失效或文件损坏 / 'network'=网络错误
    real_name: 响应头 Content-Disposition 中的真实文件名（可能为None）
    """
    try:
        import urllib.request
        req = urllib.request.Request(url, headers={
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36',
            'Referer': url,
        })
        with urllib.request.urlopen(req, timeout=60) as response:
            total_size = int(response.headers.get('Content-Length', 0))
            ctype = (response.headers.get('Content-Type') or '').lower()
            # 链接失效检测：返回 JSON/HTML 错误页（正常文件应为二进制流）
            if 'json' in ctype or 'html' in ctype:
                data = response.read(500)
                if (b'code' in data or b'expired' in data or b'error' in data
                        or data[:1] == b'{' or data[:5] == b'<!DOC'):
                    return False, "invalid_link", None
            # 太小不可能是安装包 → 判定失效
            if 0 < total_size < 100000:
                return False, "invalid_link", None
            downloaded = 0
            with open(save_path, 'wb') as f:
                while True:
                    chunk = response.read(8192)
                    if not chunk:
                        break
                    f.write(chunk)
                    downloaded += len(chunk)
                    if progress_callback and total_size > 0:
                        progress = int(downloaded * 100 / total_size)
                        progress_callback(progress)
            # 校验文件头：exe 应为 MZ，zip 应为 PK
            ext = os.path.splitext(save_path)[1].lower()
            if os.path.exists(save_path) and os.path.getsize(save_path) > 0:
                with open(save_path, 'rb') as f:
                    head = f.read(2)
                if ext == '.exe' and head != b'MZ':
                    os.remove(save_path)
                    return False, "invalid_link", None
                if ext == '.zip' and head != b'PK':
                    os.remove(save_path)
                    return False, "invalid_link", None
            elif os.path.exists(save_path):
                os.remove(save_path)
                return False, "invalid_link", None
        real_name = _extract_cd_filename(response.headers.get('Content-Disposition'))
        return True, None, real_name
    except Exception as e:
        print(f"[download_file error] {e}")
        return False, "network", None


def _resolve_lnk_via_vbs(path):
    """用 win32com 解析 .lnk，返回 (目标路径, 工作目录, 参数)。
    不创建VBS脚本文件，避免杀毒误报。"""
    try:
        import win32com.client
        shell = win32com.client.Dispatch("WScript.Shell")
        sc = shell.CreateShortcut(path)
        target = sc.TargetPath or ""
        workdir = sc.WorkingDirectory or ""
        args = sc.Arguments or ""
        if target and os.path.exists(target):
            return target, workdir, args
    except Exception:
        pass
    return "", "", ""


def resolve_shortcut(path):
    """解析 .lnk 快捷方式 -> 目标 exe 路径（不依赖 pywin32）"""
    if path.lower().endswith('.lnk'):
        tgt, _wd, _args = _resolve_lnk_via_vbs(path)
        if tgt and os.path.exists(tgt):
            return tgt
    return path


def resolve_shortcut_with_workdir(path):
    """解析 .lnk 快捷方式 -> 返回 (目标路径, 工作目录)（不依赖 pywin32）"""
    if path.lower().endswith('.lnk'):
        tgt, workdir, _args = _resolve_lnk_via_vbs(path)
        if tgt and os.path.exists(tgt):
            if workdir and os.path.exists(workdir):
                return tgt, workdir
            return tgt, os.path.dirname(tgt)
    return path, os.path.dirname(path)


def is_executable(path):
    """仅允许 .exe 以及 .lnk 快捷方式 (lnk即使无法解析目标也接受, Windows可直接运行)"""
    if path.lower().endswith('.exe'):
        return True
    if path.lower().endswith('.lnk'):
        return True
    return False


def display_name(path):
    name = os.path.basename(path)
    for ext in ('.lnk', '.exe'):
        if name.lower().endswith(ext):
            name = name[:-len(ext)]
    return name


# 鼠标指针颜色映射
CURSOR_COLORS = {
    "default": None,
    "pink": (255, 51, 170),
    "purple": (170, 85, 255),
    "yellow": (255, 204, 0),
    "cyan": (0, 221, 255),
    "orange": (255, 136, 0),
    "red": (255, 51, 51),
    "blue": (51, 136, 255),
    "green": (51, 255, 102),
    "white": (255, 255, 255),
    "gold": (255, 215, 0),
}

_cursor_cache = {}

ANIME_CURSORS_B64 = {
    "anime1": "",
    "anime2": "",
    "anime3": "",
    "anime4": "",
    "anime5": "",
    "anime6": "",
    "anime7": "",
    "anime8": "",
    "anime9": "",
    "anime10": "",
    "anime11": "",
    "anime12": "",
}

_anime_cursor_cache = {}

def create_anime_cursor(color_key):
    """从内置动漫图片创建鼠标指针"""
    if color_key not in ANIME_CURSORS_B64:
        return QCursor(Qt.ArrowCursor)
    if color_key in _anime_cursor_cache:
        return _anime_cursor_cache[color_key]
    try:
        import base64 as _b
        data = _b.b64decode(ANIME_CURSORS_B64[color_key])
        pix = QPixmap()
        pix.loadFromData(data, 'PNG')
        if pix.isNull():
            return QCursor(Qt.ArrowCursor)
        cursor = QCursor(pix, 2, 2)
        _anime_cursor_cache[color_key] = cursor
        return cursor
    except Exception as e:
        print(f"[create_anime_cursor error] {e}")
        return QCursor(Qt.ArrowCursor)


def create_colored_cursor(color_key):
    """创建鼠标指针（系统默认 / 动漫图片）"""
    if color_key == "default":
        return QCursor(Qt.ArrowCursor)
    if color_key.startswith("anime"):
        return create_anime_cursor(color_key)
    if color_key not in CURSOR_COLORS:
        return QCursor(Qt.ArrowCursor)
    if color_key in _cursor_cache:
        return _cursor_cache[color_key]
    try:
        r, g, b = CURSOR_COLORS[color_key]
        # 绘制箭头光标 (32x32)
        pix = QPixmap(32, 32)
        pix.fill(Qt.transparent)
        p = QPainter(pix)
        p.setRenderHint(QPainter.Antialiasing)
        # 箭头主体
        arrow = QPolygon([
            QPoint(2, 2), QPoint(2, 22), QPoint(9, 15),
            QPoint(14, 28), QPoint(18, 26), QPoint(13, 13),
            QPoint(22, 13),
        ])
        # 黑色描边
        p.setPen(QPen(QColor(0, 0, 0, 200), 2))
        p.setBrush(QColor(r, g, b, 230))
        p.drawPolygon(arrow)
        # 内部高光
        p.setPen(QPen(QColor(255, 255, 255, 100), 1))
        p.drawLine(QPoint(5, 5), QPoint(5, 18))
        p.end()
        cursor = QCursor(pix, 2, 2)
        _cursor_cache[color_key] = cursor
        return cursor
    except Exception as e:
        print(f"[create_colored_cursor error] {e}")
        return QCursor(Qt.ArrowCursor)


def create_image_cursor(image_path):
    """从图片创建自定义鼠标指针"""
    try:
        if not image_path:
            return QCursor(Qt.ArrowCursor)
        # 支持相对路径和绝对路径
        if not os.path.isabs(image_path):
            # 相对路径，尝试相对于应用目录
            abs_path = os.path.join(app_dir(), image_path)
            if os.path.exists(abs_path):
                image_path = abs_path
            else:
                # 尝试相对于当前工作目录
                abs_path = os.path.abspath(image_path)
                if os.path.exists(abs_path):
                    image_path = abs_path
                else:
                    print(f"[create_image_cursor] 文件不存在: {image_path}")
                    return QCursor(Qt.ArrowCursor)
        if not os.path.exists(image_path):
            print(f"[create_image_cursor] 文件不存在: {image_path}")
            return QCursor(Qt.ArrowCursor)
        # 支持 .ico 格式
        ext = os.path.splitext(image_path)[1].lower()
        if ext == '.ico':
            from PySide6.QtGui import QIcon
            icon = QIcon(image_path)
            if icon.isNull():
                return QCursor(Qt.ArrowCursor)
            pix = icon.pixmap(32, 32)
        else:
            pix = QPixmap(image_path)
        if pix.isNull():
            print(f"[create_image_cursor] 图片加载失败: {image_path}")
            return QCursor(Qt.ArrowCursor)
        # 缩放到32x32，保持宽高比
        pix = pix.scaled(32, 32, Qt.KeepAspectRatio, Qt.SmoothTransformation)
        # 热点设置为左上角 (2,2)
        cursor = QCursor(pix, 2, 2)
        return cursor
    except Exception as e:
        print(f"[create_image_cursor error] {e}: {image_path}")
        return QCursor(Qt.ArrowCursor)


def _extract_hicon_ctypes(file_path, size=256):
    """用 ctypes 调 PrivateExtractIconsW 提取高清图标，返回 HICON(int) 或 None。
    不依赖 pywin32，打包后别人电脑也能用。"""
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        fn = user32.PrivateExtractIconsW
        fn.restype = ctypes.c_uint
        fn.argtypes = [
            wintypes.LPCWSTR, ctypes.c_int, ctypes.c_int, ctypes.c_int,
            ctypes.POINTER(wintypes.HICON), ctypes.POINTER(ctypes.c_uint),
            ctypes.c_uint, ctypes.c_uint
        ]
        hicon = wintypes.HICON()
        iconid = ctypes.c_uint(0)
        # 优先请求大尺寸，系统会返回最接近的可用尺寸
        n = fn(file_path, 0, size, size,
               ctypes.byref(hicon), ctypes.byref(iconid), 1, 0)
        if n and n != 0xFFFFFFFF and hicon.value:
            return hicon.value
    except Exception:
        pass
    return None


def _destroy_hicon(hicon):
    try:
        import ctypes
        ctypes.windll.user32.DestroyIcon(hicon)
    except Exception:
        pass


def _hicon_to_qpixmap(hicon):
    """用 GDI 把 HICON 转成 QPixmap（PySide6 无 fromHICON，手动读取像素）。"""
    try:
        import ctypes
        from ctypes import wintypes
        from PySide6.QtGui import QImage, QPixmap

        class ICONINFO(ctypes.Structure):
            _fields_ = [
                ("fIcon", wintypes.BOOL),
                ("xHotspot", wintypes.DWORD),
                ("yHotspot", wintypes.DWORD),
                ("hbmMask", wintypes.HBITMAP),
                ("hbmColor", wintypes.HBITMAP),
            ]

        class BITMAP(ctypes.Structure):
            _fields_ = [
                ("bmType", wintypes.LONG),
                ("bmWidth", wintypes.LONG),
                ("bmHeight", wintypes.LONG),
                ("bmWidthBytes", wintypes.LONG),
                ("bmPlanes", wintypes.WORD),
                ("bmBitsPixel", wintypes.WORD),
                ("bmBits", wintypes.LPVOID),
            ]

        class BITMAPINFOHEADER(ctypes.Structure):
            _fields_ = [
                ("biSize", wintypes.DWORD),
                ("biWidth", wintypes.LONG),
                ("biHeight", wintypes.LONG),
                ("biPlanes", wintypes.WORD),
                ("biBitCount", wintypes.WORD),
                ("biCompression", wintypes.DWORD),
                ("biSizeImage", wintypes.DWORD),
                ("biXPelsPerMeter", wintypes.LONG),
                ("biYPelsPerMeter", wintypes.LONG),
                ("biClrUsed", wintypes.DWORD),
                ("biClrImportant", wintypes.DWORD),
            ]

        user32, gdi32 = ctypes.windll.user32, ctypes.windll.gdi32
        info = ICONINFO()
        if not user32.GetIconInfo(hicon, ctypes.byref(info)):
            return None
        bm = BITMAP()
        got = 0
        if info.hbmColor:
            got = gdi32.GetObjectW(info.hbmColor, ctypes.sizeof(bm), ctypes.byref(bm))
        w, h = bm.bmWidth, bm.bmHeight
        if got == 0 or w <= 0 or h <= 0:
            if info.hbmMask:
                gdi32.DeleteObject(info.hbmMask)
            if info.hbmColor:
                gdi32.DeleteObject(info.hbmColor)
            return None
        hdc = gdi32.GetDC(0)
        memdc = gdi32.CreateCompatibleDC(hdc)
        bi = BITMAPINFOHEADER()
        bi.biSize = ctypes.sizeof(BITMAPINFOHEADER)
        bi.biWidth = w
        bi.biHeight = -h  # 自上而下
        bi.biPlanes = 1
        bi.biBitCount = 32
        bi.biCompression = 0  # BI_RGB
        buf = ctypes.create_string_buffer(w * h * 4)
        gdi32.GetDIBits(memdc, info.hbmColor, 0, h, buf, ctypes.byref(bi), 0)
        img = QImage(buf.raw, w, h, w * 4, QImage.Format_ARGB32).copy()
        gdi32.DeleteDC(memdc)
        gdi32.ReleaseDC(0, hdc)
        if info.hbmMask:
            gdi32.DeleteObject(info.hbmMask)
        if info.hbmColor:
            gdi32.DeleteObject(info.hbmColor)
        return QPixmap.fromImage(img)
    except Exception:
        return None


def _qpixmap_to_hicon(pm, size=32):
    """把 QPixmap 转成 Win32 HICON（PNG/JPG 等非 ico 图标用于托盘，保留透明通道）。"""
    try:
        from ctypes import wintypes
        from PySide6.QtGui import QImage, QPixmap, QPainter
        user32, gdi32 = ctypes.windll.user32, ctypes.windll.gdi32
        if pm is None or pm.isNull():
            return 0
        pm = pm.scaled(size, size, Qt.KeepAspectRatio, Qt.SmoothTransformation)
        canvas = QPixmap(size, size)
        canvas.fill(Qt.transparent)
        qp = QPainter(canvas)
        qp.drawPixmap((size - pm.width()) // 2, (size - pm.height()) // 2, pm)
        qp.end()
        img = canvas.toImage().convertToFormat(QImage.Format_RGBA8888)
        w = h = size
        bpl = img.bytesPerLine()
        src_bytes = bytes(img.constBits())

        class _BIH(ctypes.Structure):
            _fields_ = [("biSize", wintypes.DWORD), ("biWidth", wintypes.LONG),
                        ("biHeight", wintypes.LONG), ("biPlanes", wintypes.WORD),
                        ("biBitCount", wintypes.WORD), ("biCompression", wintypes.DWORD),
                        ("biSizeImage", wintypes.DWORD), ("biXPelsPerMeter", wintypes.LONG),
                        ("biYPelsPerMeter", wintypes.LONG), ("biClrUsed", wintypes.DWORD),
                        ("biClrImportant", wintypes.DWORD)]

        class _II(ctypes.Structure):
            _fields_ = [("fIcon", wintypes.BOOL), ("xHotspot", wintypes.DWORD),
                        ("yHotspot", wintypes.DWORD), ("hbmMask", wintypes.HBITMAP),
                        ("hbmColor", wintypes.HBITMAP)]

        bi = _BIH()
        bi.biSize = ctypes.sizeof(_BIH)
        bi.biWidth = w
        bi.biHeight = h
        bi.biPlanes = 1
        bi.biBitCount = 32
        bi.biCompression = 0
        bi.biSizeImage = w * h * 4
        hdc = user32.GetDC(0)
        ppv = ctypes.c_void_p()
        hbm_color = gdi32.CreateDIBSection(hdc, ctypes.byref(bi), 0, ctypes.byref(ppv), None, 0)
        user32.ReleaseDC(0, hdc)
        if not hbm_color or not ppv.value:
            return 0
        dst = (ctypes.c_ubyte * (w * h * 4)).from_address(ppv.value)
        for yy in range(h):
            row = src_bytes[yy * bpl: yy * bpl + w * 4]
            for xx in range(w):
                r, g, b, a = row[xx * 4], row[xx * 4 + 1], row[xx * 4 + 2], row[xx * 4 + 3]
                i = (yy * w + xx) * 4
                dst[i] = b
                dst[i + 1] = g
                dst[i + 2] = r
                dst[i + 3] = a
        hbm_mask = gdi32.CreateBitmap(w, h, 1, 1, None)
        ii = _II()
        ii.fIcon = True
        ii.hbmMask = hbm_mask
        ii.hbmColor = hbm_color
        hicon = user32.CreateIconIndirect(ctypes.byref(ii))
        gdi32.DeleteObject(hbm_color)
        gdi32.DeleteObject(hbm_mask)
        return hicon or 0
    except Exception:
        return 0


def extract_icon(file_path, size=ICON_PX):
    """从 exe / 快捷方式提取系统图标 -> QPixmap"""
    real = resolve_shortcut(file_path)
    # 路径不存在时跳过系统图标提取（QFileIconProvider 对无效路径会返回空白透明图）
    if os.path.exists(real):
        # 优先用 QFileIconProvider (Windows 系统大图标)
        try:
            from PySide6.QtWidgets import QFileIconProvider
            from PySide6.QtCore import QFileInfo
            provider = QFileIconProvider()
            icon = provider.icon(QFileInfo(real))
            pm = icon.pixmap(size, size)
            # 过滤空白透明图（全透明像素视为无图标）
            if not pm.isNull() and not _pixmap_is_blank(pm):
                return pm
        except Exception:
            pass
        # 备用: ctypes PrivateExtractIconsW + GDI 提取高清图标（不依赖 pywin32）
        try:
            hicon = _extract_hicon_ctypes(real, 256)
            if hicon:
                pm = _hicon_to_qpixmap(hicon)
                _destroy_hicon(hicon)
                if pm and not pm.isNull() and not _pixmap_is_blank(pm):
                    return pm.scaled(size, size, Qt.KeepAspectRatio, Qt.SmoothTransformation)
        except Exception:
            pass
    # 最终备用: 绘制名称首字图标（清晰不空白）
    name = os.path.basename(real or file_path)
    for ext in ('.exe', '.lnk'):
        if name.lower().endswith(ext):
            name = name[:-len(ext)]
    first = name[:1] if name else "?"
    pm = QPixmap(size, size)
    pm.fill(Qt.transparent)
    p = QPainter(pm)
    p.setRenderHint(QPainter.Antialiasing)
    p.setBrush(QColor(35, 20, 45))
    p.setPen(QColor(255, 119, 85))
    p.drawRoundedRect(3, 3, size - 6, size - 6, 8, 8)
    p.setPen(QColor(255, 170, 130))
    f = QFont("Microsoft YaHei", int(size * 0.5), QFont.Bold)
    p.setFont(f)
    p.drawText(QRect(0, 0, size, size), Qt.AlignCenter, first)
    p.end()
    return pm


def _pixmap_is_blank(pm):
    """判断 pixmap 是否全透明（空白图）"""
    try:
        img = pm.toImage()
        if img.isNull():
            return True
        w, h = img.width(), img.height()
        if w <= 0 or h <= 0:
            return True
        # 采样中心与四角像素，全透明即视为空白
        pts = [(w // 2, h // 2), (2, 2), (w - 3, 2), (2, h - 3), (w - 3, h - 3)]
        for x, y in pts:
            if 0 <= x < w and 0 <= y < h and img.pixelColor(x, y).alpha() > 0:
                return False
        return True
    except Exception:
        return False


def create_default_app_icon():
    """生成默认风格软件图标"""
    pm = QPixmap(256, 256)
    pm.fill(Qt.transparent)
    p = QPainter(pm)
    p.setRenderHint(QPainter.Antialiasing)
    p.setBrush(QColor(35, 0, 25))
    p.setPen(QColor(255, 51, 170))
    p.drawRoundedRect(8, 8, 240, 240, 30, 30)
    p.setPen(QColor(255, 51, 170))
    f = QFont("Consolas", 120, QFont.Bold)
    p.setFont(f)
    p.drawText(QRect(0, 0, 256, 256), Qt.AlignCenter, "P")
    p.end()
    return QIcon(pm)


def is_autostart_enabled():
    """检查是否已设置开机启动，优先从注册表读取（确保真实状态）"""
    # 优先从注册表读取（真实的开机启动状态）
    try:
        import winreg
        key = winreg.OpenKey(winreg.HKEY_CURRENT_USER,
                             r"Software\Microsoft\Windows\CurrentVersion\Run",
                             0, winreg.KEY_READ)
        try:
            value, _ = winreg.QueryValueEx(key, APP_TITLE)
            winreg.CloseKey(key)
            return True
        except FileNotFoundError:
            winreg.CloseKey(key)
            # 注册表没有，再检查启动文件夹快捷方式
            try:
                _lnk = os.path.join(os.environ.get('APPDATA', ''),
                                    'Microsoft', 'Windows', 'Start Menu',
                                    'Programs', 'Startup', APP_TITLE + '.lnk')
                if os.path.exists(_lnk):
                    return True
            except Exception:
                pass
            return False
    except Exception:
        pass
    # 注册表读取失败时从配置文件读取
    try:
        cfg_path = os.path.join(app_dir(), CONFIG_FILE)
        if os.path.exists(cfg_path):
            import json
            with open(cfg_path, 'r', encoding='utf-8') as f:
                cfg_data = json.load(f)
            if "autostart" in cfg_data:
                return bool(cfg_data["autostart"])
    except Exception:
        pass
    return False

def set_autostart(enable):
    """设置或取消开机启动，同时保存到配置文件"""
    try:
        import winreg
        key = winreg.OpenKey(winreg.HKEY_CURRENT_USER,
                             r"Software\Microsoft\Windows\CurrentVersion\Run",
                             0, winreg.KEY_SET_VALUE)
        if enable:
            # 获取当前exe路径或python脚本路径
            if getattr(sys, 'frozen', False):
                # 打包后使用 sys.executable，这是实际运行的exe路径（加引号防止路径含空格）
                exe_path = f'"{sys.executable}"'
            else:
                # 开发模式使用 pythonw.exe + 脚本路径，确保无控制台窗口启动
                python_dir = os.path.dirname(sys.executable)
                pythonw = os.path.join(python_dir, 'pythonw.exe')
                if os.path.exists(pythonw):
                    exe_path = f'"{pythonw}" "{os.path.abspath(sys.argv[0])}"'
                else:
                    exe_path = f'"{sys.executable}" "{os.path.abspath(sys.argv[0])}"'
            winreg.SetValueEx(key, APP_TITLE, 0, winreg.REG_SZ, exe_path)
        else:
            try:
                winreg.DeleteValue(key, APP_TITLE)
            except FileNotFoundError:
                pass
        winreg.CloseKey(key)
        # 双保险：同时在系统启动文件夹创建/删除快捷方式（防止火绒等安全软件拦截注册表启动项）
        try:
            import win32com.client
            _lnk = os.path.join(os.environ.get('APPDATA', ''),
                                'Microsoft', 'Windows', 'Start Menu',
                                'Programs', 'Startup', APP_TITLE + '.lnk')
            if enable:
                _exe = sys.executable if getattr(sys, 'frozen', False) else os.path.abspath(sys.argv[0])
                # 用 win32com 创建快捷方式，不创建VBS脚本（避免杀毒误报）
                shell = win32com.client.Dispatch("WScript.Shell")
                s = shell.CreateShortcut(_lnk)
                s.TargetPath = _exe
                s.WorkingDirectory = os.path.dirname(_exe)
                s.Save()
            else:
                if os.path.exists(_lnk):
                    try:
                        os.remove(_lnk)
                    except Exception:
                        pass
        except Exception:
            pass
        # 同时保存到配置文件（文件不存在也创建，保证状态可持久化）
        try:
            cfg_path = os.path.join(app_dir(), CONFIG_FILE)
            import json
            cfg_data = {}
            if os.path.exists(cfg_path):
                with open(cfg_path, 'r', encoding='utf-8') as f:
                    cfg_data = json.load(f)
            cfg_data["autostart"] = enable
            with open(cfg_path, 'w', encoding='utf-8') as f:
                json.dump(cfg_data, f, ensure_ascii=False, indent=2)
        except Exception:
            pass
        return True
    except Exception as e:
        print(f"[set_autostart error] {e}")
        return False

def open_file(path):
    """打开软件 - 设置正确的工作目录，防止游戏配置文件丢失"""
    try:
        # 解析快捷方式，同时获取工作目录（优先使用快捷方式的工作目录）
        real, work_dir = resolve_shortcut_with_workdir(path)
        real = os.path.normpath(real)  # 前斜杠路径统一为反斜杠
        if work_dir:
            work_dir = os.path.normpath(work_dir)
        if os.path.exists(real):
            ext = os.path.splitext(real)[1].lower()
            if ext == '.exe':
                # exe程序使用subprocess启动，设置正确的工作目录
                # 这对游戏至关重要，否则配置文件(如.ini)会在错误目录被创建/删除
                # 优先使用快捷方式的工作目录，否则使用目标exe所在目录
                if not work_dir or not os.path.exists(work_dir):
                    work_dir = os.path.dirname(real)
                # 先切换到工作目录，确保游戏在正确的目录下运行
                try:
                    os.chdir(work_dir)
                except Exception:
                    pass
                try:
                    subprocess.Popen([real], cwd=work_dir, shell=False)
                except OSError as _e:
                    # 需要管理员权限的程序(如反恐行动 requireAdministrator)用提权方式启动
                    if getattr(_e, 'winerror', None) in (740, 5):
                        ctypes.windll.shell32.ShellExecuteW(
                            None, "runas", real, None, work_dir, 1)
                    else:
                        raise
            else:
                # 其他文件用系统默认方式打开
                os.startfile(real)
            return True
    except Exception as e:
        QMessageBox.critical(None, "错误", f"无法打开:\n{path}\n\n{e}")
    return False


def open_file_as_admin(path):
    """以管理员身份启动软件（右键菜单用）：始终走 UAC 提权，设置正确工作目录，
    避免游戏配置文件丢失。游戏菜单本身保持普通权限，不影响拖放。"""
    try:
        real, work_dir = resolve_shortcut_with_workdir(path)
        real = os.path.normpath(real)
        if work_dir:
            work_dir = os.path.normpath(work_dir)
        if os.path.exists(real):
            if not work_dir or not os.path.exists(work_dir):
                work_dir = os.path.dirname(real)
            # ShellExecuteW "runas" 提权，会弹一次 UAC 确认
            ctypes.windll.shell32.ShellExecuteW(
                None, "runas", real, None, work_dir, 1)
            return True
    except Exception as e:
        QMessageBox.critical(None, "错误", f"无法以管理员身份打开:\n{path}\n\n{e}")
    return False


def open_in_folder(path):
    """在资源管理器中定位文件"""
    try:
        real = resolve_shortcut(path)
        real = os.path.normpath(real)  # 前斜杠路径转为反斜杠，explorer 才能定位
        if not os.path.exists(real):
            # 目标文件不存在：尝试打开其所在目录，否则明确提示
            d = os.path.dirname(real)
            if d and os.path.exists(d):
                os.startfile(d)
                return True
            if os.path.dirname(path) and os.path.exists(os.path.dirname(path)):
                os.startfile(os.path.dirname(path))
                return True
            QMessageBox.warning(None, "无法打开目录", f"文件不存在或已被移动:\n{real}")
            return False
        # explorer /select,路径 必须合并为一个参数，否则资源管理器忽略定位
        subprocess.Popen(['explorer', '/select,' + real], shell=False)
        return True
    except Exception as e:
        QMessageBox.critical(None, "错误", f"无法打开目录:\n{e}")
    return False


# ============================================================
# 配置管理
# ============================================================
class Config:
    def __init__(self):
        self.path = os.path.join(app_dir(), CONFIG_FILE)
        self.assets = os.path.join(app_dir(), ASSETS_DIR)
        os.makedirs(self.assets, exist_ok=True)
        self.data = self._load()
        self._restarting = False  # 重启标志位，防止保存覆盖配置

    def _load(self):
        default = {
            "background": None,
            "theme": DEFAULT_THEME,
            "first_run": True,
            "app_title": APP_TITLE,
            "app_icon": None,
            "resolution": DEFAULT_RESOLUTION,
            "resolution_locked": False,
            "category_names": {CATEGORIES[0]: CATEGORIES[0],
                               CATEGORIES[1]: CATEGORIES[1],
                               CATEGORIES[2]: CATEGORIES[2]},
            "items": {c: [] for c in CATEGORIES},
            "floating_effect": True,
            "floating_type": "glow",
            "cursor_color": "default",
            "cursor_image": None,
            "autostart": True,
            "tray_enabled": True,
            "balloon_enabled": True,
            "balloon_text": "我是灵动岛！我在这里。",
            "balloon_color": "#ff0000",
            "balloon_shape": "circle",
            "balloon_panel_shape": "capsule",
            "balloon_font_size": 15,
            "icon_size": "medium",
        }
        if os.path.exists(self.path):
            try:
                # 使用utf-8-sig编码，自动处理BOM头
                with open(self.path, 'r', encoding='utf-8-sig') as f:
                    d = json.load(f)
                # 确保所有必要字段存在
                for c in CATEGORIES:
                    d.setdefault("items", {}).setdefault(c, [])
                d.setdefault("background", None)
                d.setdefault("theme", DEFAULT_THEME)
                d.setdefault("first_run", True)
                d.setdefault("app_title", APP_TITLE)
                d.setdefault("app_icon", None)
                d.setdefault("category_names", {CATEGORIES[0]: CATEGORIES[0],
                                                  CATEGORIES[1]: CATEGORIES[1],
                                                  CATEGORIES[2]: CATEGORIES[2]})
                d.setdefault("floating_effect", True)
                d.setdefault("floating_type", "fire")
                d.setdefault("cursor_color", "default")
                d.setdefault("cursor_image", None)
                d.setdefault("autostart", True)
                d.setdefault("tray_enabled", True)
                d.setdefault("balloon_enabled", True)
                d.setdefault("balloon_text", "我在这里！看见我了吗")
                d.setdefault("balloon_color", "#ff33aa")
                d.setdefault("balloon_shape", "circle")
                d.setdefault("balloon_panel_shape", "capsule")
                d.setdefault("balloon_font_size", 15)
                d.setdefault("icon_size", "medium")
                # 校验并修复每个item的数据
                import uuid
                for c in CATEGORIES:
                    valid_items = []
                    for item in d["items"].get(c, []):
                        if not isinstance(item, dict):
                            continue
                        # 补全缺失字段
                        if "id" not in item or not item["id"]:
                            item["id"] = str(uuid.uuid4())[:8]
                        if "path" not in item or not item["path"]:
                            continue  # 没有路径的item跳过
                        if "name" not in item or not item["name"]:
                            item["name"] = display_name(item["path"])
                        if "x" not in item:
                            item["x"] = 20
                        if "y" not in item:
                            item["y"] = 20
                        valid_items.append(item)
                    d["items"][c] = valid_items
                return d
            except Exception as e:
                print(f"[配置加载失败] {e}")
        return default

    def save(self):
        # 重启时不保存，防止用旧配置覆盖新导入的配置
        if getattr(self, '_restarting', False):
            return
        with open(self.path, 'w', encoding='utf-8') as f:
            json.dump(self.data, f, ensure_ascii=False, indent=2)

    def cat_name(self, key):
        return self.data.get("category_names", {}).get(key, key)

    def set_cat_names(self, names_dict):
        self.data["category_names"].update(names_dict)
        self.save()

    def set_app_title(self, title):
        self.data["app_title"] = title
        self.save()

    def set_app_icon(self, icon_path):
        self.data["app_icon"] = icon_path
        self.save()

    def mark_first_run_done(self):
        self.data["first_run"] = False
        self.save()

    def items(self, cat):
        return self.data["items"].get(cat, [])

    def add_item(self, cat, path, x=20, y=20, name=None, icon_path=None):
        item = {
            "id": str(uuid.uuid4())[:8],
            "name": name if name else display_name(path),
            "path": path,
            "x": x,
            "y": y,
            "icon_path": icon_path,
        }
        self.data["items"][cat].append(item)
        self.save()
        return item

    def set_item_icon(self, cat, item_id, icon_path):
        for i in self.data["items"][cat]:
            if i["id"] == item_id:
                i["icon_path"] = icon_path
                self.save()
                return

    def remove_item(self, cat, item_id):
        self.data["items"][cat] = [i for i in self.data["items"][cat] if i["id"] != item_id]
        self.save()

    def move_item(self, cat, item_id, x, y):
        for i in self.data["items"][cat]:
            if i["id"] == item_id:
                i["x"], i["y"] = x, y
                self.save()
                return

    def set_item_position(self, cat, item_id, x, y):
        """设置图标位置（move_item的别名）"""
        self.move_item(cat, item_id, x, y)

    def rename_item(self, cat, item_id, new_name):
        for i in self.data["items"][cat]:
            if i["id"] == item_id:
                i["name"] = new_name
                self.save()
                return

    def transfer_item(self, from_cat, to_cat, item_id, x, y):
        for i in self.data["items"][from_cat]:
            if i["id"] == item_id:
                i["x"], i["y"] = x, y
                self.data["items"][to_cat].append(i)
                self.data["items"][from_cat].remove(i)
                self.save()
                return

    def set_background(self, bg_path):
        """复制背景图到 assets 并保存"""
        if bg_path is None:
            self.data["background"] = None
        else:
            fname = os.path.basename(bg_path)
            dst = os.path.join(self.assets, fname)
            if os.path.abspath(bg_path) != os.path.abspath(dst):
                import shutil
                shutil.copy2(bg_path, dst)
            self.data["background"] = dst
        self.save()

    def set_theme(self, theme_key):
        """保存主题选择"""
        self.data["theme"] = theme_key
        self.save()

    def set_cursor_color(self, color_key):
        """保存鼠标指针颜色"""
        self.data["cursor_color"] = color_key
        self.save()


# ============================================================
# 图标项 (可拖动 / 右键菜单)
# ============================================================
class IconItem(QFrame):
    open_app = Signal(str)
    open_folder = Signal(str)
    remove_me = Signal(str, str)  # cat, id
    rename_me = Signal(str, str)  # cat, id
    change_icon = Signal(str, str)  # cat, id
    position_changed = Signal(str, str, int, int)  # cat, id, x, y
    run_as_admin = Signal(str)  # 以管理员身份运行（传path）

    def __init__(self, item_data, category, parent=None):
        super().__init__(parent)
        self.d = item_data
        self.cat = category
        self.iid = item_data.get("id", "unknown")
        self.path = item_data.get("path", "")
        self._drag_pos = QPoint()
        self._dragging = False

        self.setFixedSize(ICON_W, ICON_H)
        self.setCursor(Qt.PointingHandCursor)
        self.setAttribute(Qt.WA_StyledBackground)

        lay = QVBoxLayout(self)
        lay.setContentsMargins(2, 4, 2, 2)
        lay.setSpacing(2)

        self.icon_lbl = QLabel()
        self.icon_lbl.setFixedSize(ICON_PX, ICON_PX)
        self.icon_lbl.setAlignment(Qt.AlignCenter)
        self.icon_lbl.setAttribute(Qt.WA_TranslucentBackground)
        self._apply_icon()

        self.name_lbl = QLabel(item_data["name"])
        self.name_lbl.setAlignment(Qt.AlignCenter)
        self.name_lbl.setWordWrap(True)
        self.name_lbl.setFixedWidth(ICON_W - 4)
        self.name_lbl.setAttribute(Qt.WA_TranslucentBackground)
        # 根据图标大小动态调整字体大小，确保文字清晰不被截断
        font_size = max(10, min(14, ICON_PX // 3 + 2))
        # 使用主题配色，不再硬编码绿色
        theme = THEMES.get(DEFAULT_THEME, THEMES[DEFAULT_THEME])
        r, g, b = theme["accent_rgb"]
        self.name_lbl.setStyleSheet(f"color:rgba({r},{g},{b},255);font-size:{font_size}px;font-weight:bold;font-family:'Microsoft YaHei','Consolas';")

        lay.addWidget(self.icon_lbl, 0, Qt.AlignCenter)
        lay.addWidget(self.name_lbl, 0, Qt.AlignCenter)

        self._apply_style(hover=False)

    def _apply_icon(self):
        """优先使用自定义图标, 否则从exe提取"""
        custom = self.d.get("icon_path")
        if custom and os.path.exists(custom):
            pm = QPixmap(custom)
            if not pm.isNull():
                pm = pm.scaled(ICON_PX, ICON_PX, Qt.KeepAspectRatio, Qt.SmoothTransformation)
                self.icon_lbl.setPixmap(pm)
                return
        pm = extract_icon(self.path, ICON_PX)
        self.icon_lbl.setPixmap(pm)

    def apply_size(self, px, w, h):
        """切换图标档位：只调整尺寸并重新缩放图标，保持当前 x,y 位置不变（不重排）"""
        self.setFixedSize(w, h)
        self.icon_lbl.setFixedSize(px, px)
        self.name_lbl.setFixedWidth(w - 4)
        self._apply_icon()
        font_size = max(10, min(14, px // 3 + 2))
        theme = THEMES.get(DEFAULT_THEME, THEMES[DEFAULT_THEME])
        r, g, b = theme["accent_rgb"]
        self.name_lbl.setStyleSheet(f"color:rgba({r},{g},{b},255);font-size:{font_size}px;font-weight:bold;font-family:'Microsoft YaHei','Consolas';")

    def _apply_style(self, hover):
        # 使用主题配色，不再硬编码黑客绿色
        theme = THEMES.get(DEFAULT_THEME, THEMES[DEFAULT_THEME])
        r, g, b = theme["accent_rgb"]
        if hover:
            self.setStyleSheet(f"""
                IconItem {{ background:rgba({r//5},{g//5},{b//5},220); border:1px solid rgb({r},{g},{b});
                           border-radius:6px; }}
            """)
        else:
            self.setStyleSheet(f"""
                IconItem {{ background:rgba({r//10},{g//10},{b//10},170); border:1px solid rgba({r},{g},{b},100);
                           border-radius:6px; }}
            """)

    def enterEvent(self, event):
        self._apply_style(True)
        super().enterEvent(event)

    def leaveEvent(self, event):
        self._apply_style(False)
        super().leaveEvent(event)

    # ---- 拖动 (在容器内自由移动位置) ----
    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton:
            self._drag_pos = event.globalPosition().toPoint()
            self._dragging = False
            self._drag_start_pos = self.pos()
            self._drag_origin = event.globalPosition().toPoint()
            # 点击时提升z-order，确保图标在最上面，不被其他图标遮挡
            self.raise_()
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if event.buttons() & Qt.LeftButton:
            global_pos = event.globalPosition().toPoint()
            delta = global_pos - self._drag_origin
            if delta.manhattanLength() > QApplication.startDragDistance():
                self._dragging = True
                self.setCursor(Qt.ClosedHandCursor)
            if self._dragging:
                # 拖动时提升z-order，确保图标在最上面，不被其他图标遮挡
                self.raise_()
                # 拖动时流畅移动，不做网格对齐
                new_x = self._drag_start_pos.x() + delta.x()
                new_y = self._drag_start_pos.y() + delta.y()
                # 网络游戏、单机游戏不能移到容器外，聊天娱乐可以自由移动
                if self.cat in ("网络游戏", "单机游戏"):
                    size_key = "medium"
                    try:
                        import os as _os
                        _cfg_path = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), "game_menu_config.json")
                        if _os.path.exists(_cfg_path):
                            import json as _json
                            with open(_cfg_path, 'r', encoding='utf-8-sig') as _f:
                                size_key = _json.load(_f).get("icon_size", "medium")
                    except Exception:
                        pass
                    per_row_map = {"large": 9, "medium": 12, "small": 10}
                    per_row = per_row_map.get(size_key, 12)
                    grid_w, _ = get_grid_size()
                    max_x = 8 + (per_row - 1) * grid_w
                    new_x = max(8, min(new_x, max_x))
                    new_y = max(8, new_y)
                self.setGeometry(new_x, new_y, self.width(), self.height())
                event.accept()
                return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.LeftButton and self._dragging:
            self._dragging = False
            self.setCursor(Qt.PointingHandCursor)
            # 释放时做网格对齐 + 碰撞检测，排列整齐不拥挤
            # 从 margin=8 开始对齐，和新添加图标的起始位置一致，确保所有图标对齐
            grid_w, grid_h = get_grid_size()
            margin = 8
            # 使用整数运算确保精确对齐，避免浮点数精度问题
            col = int(round((self.x() - margin) / grid_w))
            row = int(round((self.y() - margin) / grid_h))
            final_x = margin + col * grid_w
            final_y = margin + row * grid_h
            # 网络游戏、单机游戏限制在容器范围内，聊天娱乐可以自由移动
            if self.cat in ("网络游戏", "单机游戏"):
                size_key = "medium"
                try:
                    import os as _os
                    _cfg_path = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), "game_menu_config.json")
                    if _os.path.exists(_cfg_path):
                        import json as _json
                        with open(_cfg_path, 'r', encoding='utf-8-sig') as _f:
                            size_key = _json.load(_f).get("icon_size", "medium")
                except Exception:
                    pass
                per_row_map = {"large": 9, "medium": 12, "small": 10}
                per_row = per_row_map.get(size_key, 12)
                grid_w, grid_h = get_grid_size()
                max_x = 8 + (per_row - 1) * grid_w
                final_x = max(margin, min(final_x, max_x))
                final_y = max(margin, final_y)
            else:
                # 聊天娱乐：只限制不能太靠左上，右边可以自由移动
                final_x = max(margin, final_x)
                final_y = max(margin, final_y)
            # 先检查目标位置是否重叠，不重叠就直接使用，避免螺旋搜索导致偏移
            if not self._is_position_overlap(final_x, final_y):
                self.setGeometry(final_x, final_y, self.width(), self.height())
            else:
                # 只有真正重叠时才进行螺旋搜索
                final_x, final_y = self._find_non_overlapping_pos(final_x, final_y, grid_w, grid_h)
                self.setGeometry(final_x, final_y, self.width(), self.height())
            # 通知主窗口保存位置
            if hasattr(self, 'position_changed'):
                self.position_changed.emit(self.cat, self.iid, final_x, final_y)
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def _is_position_overlap(self, x, y):
        """检查指定位置是否与其他图标重叠"""
        parent = self.parent()
        if not parent:
            return False
        other_icons = []
        main_win = self.window()
        if hasattr(main_win, 'icon_widgets'):
            for (cat, iid), w in main_win.icon_widgets.items():
                if cat == self.cat and w is not self:
                    other_icons.append(w)
        if not other_icons:
            for child in parent.children():
                if isinstance(child, IconItem) and child is not self:
                    other_icons.append(child)
        for other in other_icons:
            if (x < other.x() + other.width() and x + self.width() > other.x() and
                y < other.y() + other.height() and y + self.height() > other.y()):
                return True
        return False

    def _find_non_overlapping_pos(self, target_x, target_y, grid_w, grid_h):
        """寻找不与其他图标重叠的位置，从目标位置开始螺旋搜索（按网格步长）"""
        parent = self.parent()
        if not parent:
            return target_x, target_y
        # 通过主窗口的icon_widgets字典获取同分类其他图标，更准确可靠
        other_icons = []
        main_win = self.window()
        if hasattr(main_win, 'icon_widgets'):
            for (cat, iid), w in main_win.icon_widgets.items():
                if cat == self.cat and w is not self:
                    other_icons.append(w)
        # 兜底：如果主窗口没有icon_widgets，使用parent.children()
        if not other_icons:
            for child in parent.children():
                if isinstance(child, IconItem) and child is not self:
                    other_icons.append(child)
        # 检查目标位置是否重叠（不留间距，确保图标可以自由移动到任何空格子）
        def is_overlap(x, y):
            for other in other_icons:
                if (x < other.x() + other.width() and x + self.width() > other.x() and
                    y < other.y() + other.height() and y + self.height() > other.y()):
                    return True
            return False
        if not is_overlap(target_x, target_y):
            return target_x, target_y
        # 螺旋搜索附近的空闲网格位置（按网格步长）
        margin = 8
        max_radius = 30
        for radius in range(1, max_radius + 1):
            for dx in range(-radius, radius + 1):
                for dy in range(-radius, radius + 1):
                    if abs(dx) != radius and abs(dy) != radius:
                        continue
                    nx = target_x + dx * grid_w
                    ny = target_y + dy * grid_h
                    # 限制在容器范围内，图标不能超过边界外，最多只能放12个
                    if parent:
                        nx = max(margin, min(nx, parent.width() - self.width() - margin))
                        ny = max(margin, min(ny, parent.height() - self.height() - margin))
                    if not is_overlap(nx, ny):
                        return nx, ny
        return target_x, target_y

    def mouseDoubleClickEvent(self, event):
        if event.button() == Qt.LeftButton:
            self.open_app.emit(self.path)

    # ---- 右键菜单 ----
    def contextMenuEvent(self, event):
        menu = QMenu(self)
        menu.setStyleSheet("""
            QMenu { background:#0a0a0a; color:#ff33aa; border:1px solid #ff33aa; padding:4px; }
            QMenu::item { padding:8px 24px; font-family:'Consolas','Microsoft YaHei'; font-size:12px; }
            QMenu::item:selected { background:rgba(255,51,170,40); }
            QMenu::separator { height:1px; background:rgba(255,51,170,80); margin:4px 8px; }
        """)
        a1 = QAction("▶ 打开软件", self)
        a1.triggered.connect(lambda: self.open_app.emit(self.path))
        menu.addAction(a1)
        a_admin = QAction("🛡 以管理员身份运行", self)
        a_admin.triggered.connect(lambda: self.run_as_admin.emit(self.path))
        menu.addAction(a_admin)
        a2 = QAction("📂 打开文件所在位置", self)
        a2.triggered.connect(lambda: self.open_folder.emit(self.path))
        menu.addAction(a2)
        menu.addSeparator()
        a_rename = QAction("✏ 重命名", self)
        a_rename.triggered.connect(self._do_rename)
        menu.addAction(a_rename)
        menu.addSeparator()
        a3 = QAction("✕ 从菜单移除", self)
        a3.triggered.connect(lambda: self.remove_me.emit(self.cat, self.iid))
        menu.addAction(a3)
        menu.exec(event.globalPos())

    def _do_rename(self):
        """右键重命名图标显示名称"""
        from PySide6.QtWidgets import QDialog, QVBoxLayout, QHBoxLayout, QLabel, QLineEdit, QPushButton
        from PySide6.QtCore import Qt
        dlg = QDialog(self)
        dlg.setWindowTitle("重命名")
        dlg.setMinimumWidth(320)
        lay = QVBoxLayout(dlg)
        lbl = QLabel("请输入新的显示名称:")
        lay.addWidget(lbl)
        edit = CnLineEdit(self.d.get("name", ""))
        edit.selectAll()
        lay.addWidget(edit)
        btn_lay = QHBoxLayout()
        btn_lay.addStretch()
        btn_ok = QPushButton("确定")
        btn_ok.setFixedWidth(80)
        btn_ok.clicked.connect(dlg.accept)
        btn_lay.addWidget(btn_ok)
        btn_cancel = QPushButton("取消")
        btn_cancel.setFixedWidth(80)
        btn_cancel.clicked.connect(dlg.reject)
        btn_lay.addWidget(btn_cancel)
        lay.addLayout(btn_lay)
        edit.returnPressed.connect(dlg.accept)
        if dlg.exec() == QDialog.Accepted:
            new_name = edit.text().strip()
            if new_name:
                # 查重：同分类下不允许同名图标
                _main_win = self.window()
                _dup = False
                if hasattr(_main_win, 'icon_widgets'):
                    for (_c, _iid), _other in _main_win.icon_widgets.items():
                        if _c == self.cat and _iid != self.iid:
                            if _other.d.get("name", "").strip() == new_name:
                                _dup = True
                                break
                if _dup:
                    if hasattr(_main_win, '_show_island'):
                        _main_win._show_island(f"名称「{new_name}」已存在，不能重复命名")
                    return
                self.d["name"] = new_name
                self.name_lbl.setText(new_name)
                self.rename_me.emit(self.cat, self.iid)



# ============================================================
# 分类区域 (接受拖放, 管理图标定位)
# ============================================================
class CategoryArea(QFrame):
    file_dropped = Signal(str, str, QPoint)   # cat, path, pos_in_container
    icon_dropped = Signal(str, str, QPoint)    # to_cat, item_id, pos
    collapsed_changed = Signal(str, bool)       # cat_key, is_collapsed

    def __init__(self, cat_key, cat_name, parent=None):
        super().__init__(parent)
        self.cat = cat_key
        self._display_name = cat_name
        self._collapsed = False
        self.setMinimumHeight(36)  # 初始最小高度36px，展开后自动扩展
        self.setSizePolicy(QSizePolicy.Preferred, QSizePolicy.Preferred)  # 大小策略Preferred，可以根据内容自动调整高度

        # 标题 (可点击展开/收起)
        self.title_btn = QPushButton()
        self.title_btn.setFixedHeight(36)
        self.title_btn.setCursor(Qt.PointingHandCursor)
        self.title_btn.clicked.connect(self._toggle_collapse)
        self._update_title_text(cat_name)
        self.title_btn.setStyleSheet("""
            QPushButton { color:rgba(255,51,170,255); font-size:17px; font-weight:bold;
                font-family:'Microsoft YaHei','Consolas'; text-align:left;
                background:transparent; border:none;
                border-bottom:1px solid rgba(255,51,170,100);
                padding-left:12px; }
            QPushButton:hover { background:rgba(255,51,170,20); color:rgba(255,51,170,255); }
        """)

        # 图标容器 (绝对定位) - 拖放由窗口级统一处理
        self.container = QWidget()
        self.container.setStyleSheet("background:transparent;")
        # 容器最小高度初始为一排图标，实际高度由 GameMenu._adjust_all_container_heights 动态计算
        self.container.setMinimumSize(get_container_width_for_12_icons(), 132)

        lay = QVBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(0)
        lay.addWidget(self.title_btn)
        lay.addWidget(self.container, 0)  # stretch=0，不占据额外高度

        self._normal_style()

    def _update_title_text(self, name, count=None):
        arrow = "▶" if self._collapsed else "▼"
        if count is not None:
            self.title_btn.setText(f" {arrow}  {name}  ({count}个)")
        else:
            self.title_btn.setText(f" {arrow}  {name}")

    def update_icon_count(self, count):
        """更新标题栏的软件数量显示"""
        self._update_title_text(self._display_name, count)

    def set_category_name(self, name):
        self._display_name = name
        # 保持当前数量显示
        count = len(self.icon_widgets())
        self._update_title_text(name, count)

    def _toggle_collapse(self):
        self._collapsed = not self._collapsed
        if self._collapsed:
            self.container.hide()
            self.setMinimumHeight(36)
            self.setMaximumHeight(36)
            self.setSizePolicy(QSizePolicy.Preferred, QSizePolicy.Maximum)
        else:
            self.container.show()
            self.setMinimumHeight(120)
            self.setMaximumHeight(16777215)
            self.setSizePolicy(QSizePolicy.Preferred, QSizePolicy.Expanding)
        count = len(self.icon_widgets())
        self._update_title_text(self._display_name, count)
        self.collapsed_changed.emit(self.cat, self._collapsed)

    def _normal_style(self):
        self.setStyleSheet("""
            CategoryArea { background:transparent; border:none; }
        """)

    def _hot_style(self):
        self.setStyleSheet("""
            CategoryArea { background:rgba(255,51,170,20); border:2px solid #ff33aa;
                           border-radius:8px; }
        """)

    def icon_widgets(self):
        return [w for w in self.container.children() if isinstance(w, IconItem)]


