# 背景绘制控件
# ============================================================
class BackgroundWidget(QWidget):
    def __init__(self, parent=None, theme_key=DEFAULT_THEME):
        super().__init__(parent)
        self.bg_pixmap = None
        self.theme_key = theme_key
        self.setAttribute(Qt.WA_StyledBackground)
        # 漂浮粒子特效
        self.particles = None
        self.particle_timer = None
        self.fx_enabled = True
        self.fx_type = "sakura"
        self._ever_shown = False
        # 粒子独立透明层（性能优化：粒子重绘不触发大背景重绘）
        self._fx_overlay = None
        # 二次元内置背景：主题自带图片，无需用户上传
        self._builtin_bg_loaded = False
        # 当前背景是否为内置图（切到非内置图主题时自动清除，避免图片残留到其他主题）
        self._bg_is_builtin = False
        # 启动即主题时：内置图主题自动加载背景（构造参数直达，不经过 set_theme）
        try:
            if THEMES.get(theme_key, {}).get("builtin_bg"):
                self._load_builtin_bg()
        except Exception:
            pass

    def set_theme(self, theme_key):
        self.theme_key = theme_key
        # 内置图主题（二次元/动漫）：自动加载内置背景图（不覆盖用户已上传的自定义背景）
        try:
            _th = THEMES.get(theme_key, {})
            if _th.get("builtin_bg"):
                self._load_builtin_bg()
            elif self._bg_is_builtin:
                # 切到非内置图主题：清除内置图，恢复主题渐变（用户自定义背景保留）
                self._bg_is_builtin = False
                self.set_background(None)
        except Exception:
            pass
        self._bg_layer_dirty = True
        self.update()

    def set_background(self, path):
        # 停止旧的GIF动画
        if hasattr(self, '_bg_movie') and self._bg_movie is not None:
            try:
                self._bg_movie.stop()
            except Exception:
                pass
            self._bg_movie = None

        if path and os.path.exists(path):
            # GIF 动态背景：用 QMovie 播放动画
            if path.lower().endswith(".gif"):
                try:
                    with open(r"D:\游戏菜单\gif_debug.log", "a", encoding="utf-8") as _f:
                        _f.write(f"Loading GIF: {path}\n")
                except Exception:
                    pass
                self._bg_movie = QMovie(path, b"gif", self)
                self._bg_movie.setCacheMode(QMovie.CacheAll)
                # 帧变化时更新背景
                self._bg_movie.frameChanged.connect(self._on_gif_frame)
                self._bg_movie.start()
                # 用第一帧初始化背景
                pm = self._bg_movie.currentPixmap()
                if pm.isNull():
                    pm = QPixmap(path)
                self.bg_pixmap = pm
                try:
                    with open(r"D:\游戏菜单\gif_debug.log", "a", encoding="utf-8") as _f:
                        _f.write(f"GIF started, frameCount={self._bg_movie.frameCount()}, state={self._bg_movie.state()}, pmIsNull={pm.isNull()}\n")
                except Exception:
                    pass
            else:
                pm = QPixmap(path)
                if not pm.isNull():
                    if pm.width() > 1600 or pm.height() > 1600:
                        pm = pm.scaled(1600, 1600, Qt.KeepAspectRatio, Qt.SmoothTransformation)
                    self.bg_pixmap = pm
                else:
                    self.bg_pixmap = None
        else:
            self.bg_pixmap = None
        self._bg_layer_dirty = True
        self.update()

    def _on_gif_frame(self, frame_number):
        """GIF帧变化时更新背景"""
        if hasattr(self, '_bg_movie') and self._bg_movie is not None:
            pm = self._bg_movie.currentPixmap()
            if not pm.isNull():
                self.bg_pixmap = pm
                self._bg_layer_dirty = True
                # 强制立即重绘，不等事件循环
                self.repaint()
                try:
                    with open(r"D:\游戏菜单\gif_debug.log", "a", encoding="utf-8") as _f:
                        _f.write(f"Frame updated: {frame_number}\n")
                except Exception:
                    pass

    def set_floating_effect(self, enabled, fx_type="rain"):
        """开启/关闭漂浮特效，支持粒子、下雨、下雪、飘雪"""
        self.fx_enabled = enabled
        self.fx_type = fx_type
        # 粒子独立透明层：只重绘粒子，避免整块背景重绘卡顿
        if self._fx_overlay is None:
            self._fx_overlay = ParticleOverlayWidget(self, self)
            self._fx_overlay.setGeometry(0, 0, self.width(), self.height())
        if enabled:
            if self.particles is None:
                if fx_type == "fire":
                    self.particles = FloatingParticles(self.width(), self.height(), fx_type, 20)
                else:
                    self.particles = FloatingParticles(self.width(), self.height(), fx_type, 30)
            else:
                self.particles.set_type(fx_type)
            if self.particle_timer is None:
                self.particle_timer = QTimer(self)
                self.particle_timer.timeout.connect(self._update_particles)
                self._fx_interval = 200  # 降低更新频率~5fps，减少CPU占用
                self._fx_last_t = time.time()
                self.particle_timer.start(150)
            if self._fx_overlay:
                self._fx_overlay.show()
        else:
            if self.particle_timer:
                self.particle_timer.stop()
                self.particle_timer = None
            self.particles = None
            if self._fx_overlay:
                self._fx_overlay.hide()
        if self._fx_overlay:
            self._fx_overlay.update()

    def _fx_ensure_effect(self, ov):
        """给粒子透明层挂透明度效果（用于淡入淡出）"""
        eff = ov.graphicsEffect()
        if eff is None:
            from PySide6.QtWidgets import QGraphicsOpacityEffect
            eff = QGraphicsOpacityEffect(ov)
            eff.setOpacity(1.0)
            ov.setGraphicsEffect(eff)
        return eff

    def _fx_stop_fade(self):
        try:
            _a = getattr(self, '_fx_fade_anim', None)
            if _a is not None:
                _a.stop()
        except Exception:
            pass

    def suspend_fx(self):
        """最小化到托盘：暂停粒子定时器并让粒子层淡出，不销毁粒子、保留位置。
        既省后台CPU，又让恢复时位置连续（丝滑）。"""
        try:
            if self.particle_timer:
                self.particle_timer.stop()
            ov = self._fx_overlay
            if ov is not None and self.fx_enabled:
                from PySide6.QtCore import QPropertyAnimation
                eff = self._fx_ensure_effect(ov)
                self._fx_stop_fade()
                _a = QPropertyAnimation(eff, b'opacity', ov)
                _a.setDuration(240)
                _a.setStartValue(float(eff.opacity()))
                _a.setEndValue(0.0)
                _a.start()
                self._fx_fade_anim = _a
        except Exception:
            pass

    def resume_fx(self):
        """从托盘恢复：粒子从原位置继续运动、粒子层淡入（不重建，丝滑）。
        仅当粒子/定时器丢失时才补建，保证稳定。"""
        try:
            if not self.fx_enabled:
                return
            # 粒子对象丢失：补建（兜底，走原有稳定路径）
            if self.particles is None:
                self.set_floating_effect(True, self.fx_type)
                ov = self._fx_overlay
                if ov is not None:
                    eff = self._fx_ensure_effect(ov)
                    eff.setOpacity(1.0)
                return
            ov = self._fx_overlay
            if ov is not None:
                ov.show()
            # 重启定时器（保留原 interval）
            _iv = getattr(self, '_fx_interval', 50)
            if self.particle_timer is None:
                self.particle_timer = QTimer(self)
                self.particle_timer.timeout.connect(self._update_particles)
            self.particle_timer.start(_iv)
            # 粒子层淡入
            if ov is not None:
                from PySide6.QtCore import QPropertyAnimation
                eff = self._fx_ensure_effect(ov)
                self._fx_stop_fade()
                _a = QPropertyAnimation(eff, b'opacity', ov)
                _a.setDuration(460)
                _a.setStartValue(float(eff.opacity()))
                _a.setEndValue(1.0)
                _a.start()
                self._fx_fade_anim = _a
            # 立即刷新一帧
            self._update_particles()
        except Exception:
            pass

    def _update_particles(self):
        try:
            if self.particles:
                # 帧率自适应：主线程卡顿时自动降频(50->75->100->120ms)，流畅时回提
                try:
                    _now = time.time()
                    _dt = (_now - getattr(self, '_fx_last_t', _now)) * 1000.0
                    self._fx_last_t = _now
                    _iv = getattr(self, '_fx_interval', 50)
                    if _dt > 150 and _iv < 130:
                        self._fx_interval = _iv + 25
                        if self.particle_timer:
                            self.particle_timer.setInterval(self._fx_interval)
                    elif _dt < 50 and _iv > 50:
                        self._fx_interval = max(50, _iv - 25)
                        if self.particle_timer:
                            self.particle_timer.setInterval(self._fx_interval)
                except Exception:
                    pass
                self.particles.update()
                # 粒子坐标防御：异常值(NaN/Inf)会导致Qt绘制时native崩溃
                import math as _m
                for _p in self.particles.particles:
                    _x, _y = _p.get('x'), _p.get('y')
                    if _x is None or _y is None:
                        continue
                    if not (_m.isfinite(_x) and _m.isfinite(_y)):
                        _p['x'] = random.uniform(0, self.width())
                        _p['y'] = random.uniform(0, self.height())
                # 只重绘粒子透明层，背景层缓存不动
                if self._fx_overlay is not None:
                    self._fx_overlay.update()
        except Exception:
            pass

    def resizeEvent(self, event):
        """背景控件大小变化时同步粒子叠加层"""
        try:
            if self._fx_overlay is not None:
                self._fx_overlay.setGeometry(0, 0, self.width(), self.height())
        except Exception:
            pass
        super().resizeEvent(event)

    def hideEvent(self, event):
        # 窗口隐藏(最小化到托盘)：暂停粒子定时器 + 粒子层淡出，不销毁粒子、保留位置。
        # 恢复时原位继续（丝滑）；隐藏期间不重绘、省CPU，也避免恢复瞬间绘制异常状态。
        try:
            self.suspend_fx()
        except Exception:
            try:
                if getattr(self, 'particle_timer', None) is not None:
                    self.particle_timer.stop()
            except Exception:
                pass
        super().hideEvent(event)

    def showEvent(self, event):
        # 首次显示：正常启动粒子定时器
        # 从托盘恢复显示：不立即启动粒子，由 _do_show_from_tray 延迟重建粒子系统，
        # 避免窗口恢复瞬间绘制旧粒子状态触发 Qt native 崩溃
        try:
            if not self._ever_shown:
                self._ever_shown = True
                # 保险：如果是内置图主题但背景没加载成功，重新加载一次
                try:
                    _th = THEMES.get(self.theme_key, {})
                    if _th.get("builtin_bg") and not getattr(self, '_builtin_bg_loaded', False):
                        self._load_builtin_bg()
                except Exception:
                    pass
                # 首次显示：若窗口创建期间 hideEvent 已清空粒子（particles=None），
                # 必须重建粒子系统并确保定时器运行，否则漂浮特效永远不显示
                if self.fx_enabled:
                    if self.particles is None:
                        self.particles = FloatingParticles(self.width(), self.height(), self.fx_type, 30)
                    if self.particle_timer is None:
                        self.particle_timer = QTimer(self)
                        self.particle_timer.timeout.connect(self._update_particles)
                        self.particle_timer.start(getattr(self, '_fx_interval', 50))
                    elif not self.particle_timer.isActive():
                        self.particle_timer.start(getattr(self, '_fx_interval', 50))
                    if self._fx_overlay is not None:
                        self._fx_overlay.show()
                        self._fx_overlay.update()
            else:
                # 从托盘恢复：粒子原位继续 + 粒子层淡入（丝滑、位置连续），不销毁重建
                try:
                    self.resume_fx()
                except Exception:
                    QTimer.singleShot(300, self._rebuild_particles)
        except Exception:
            pass
        super().showEvent(event)


    def _rebuild_particles(self):
        # 从托盘/隐藏恢复后延迟重建粒子系统（全新粒子状态）
        try:
            if self.fx_enabled:
                self.particles = None
                self.set_floating_effect(True, self.fx_type)
        except Exception:
            pass
    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)
        # 背景层缓存：背景图/渐变+蒙版+网格线只在尺寸或内容变化时重绘一次
        try:
            if (getattr(self, '_bg_layer', None) is None
                    or getattr(self, '_bg_layer_dirty', True)
                    or getattr(self, '_bg_layer_size', None) != self.size()):
                self._build_bg_layer()
            if getattr(self, '_bg_layer', None) is not None:
                p.drawPixmap(0, 0, self._bg_layer)
        except Exception:
            pass
        p.end()

    def _load_builtin_bg(self):
        """加载内嵌动漫/游戏背景图到资源目录并设为背景（Win7 兼容：纯本地解码）"""
        try:
            import base64 as _b64
            assets = os.path.join(app_dir(), "menu_assets")
            os.makedirs(assets, exist_ok=True)
            _map = {
                "anime_dongman": ("anime_bg.jpg", ANIME_BG_B64),
                "naruto": ("naruto_bg.jpg", ANIME_BG_NARUTO),
                "conan": ("conan_bg.jpg", ANIME_BG_CONAN),
                "cf_theme": ("cf_bg.jpg", ANIME_BG_CF),
                "dnf": ("dnf_bg.jpg", ANIME_BG_DNF),
                "delta": ("delta_bg.jpg", ANIME_BG_DELTA),
                "kfx": ("kfx_bg.jpg", ANIME_BG_KFX),
                "wzry_dsm": ("wzry_bg.jpg", ANIME_BG_WZRY),
                "nz_future": ("nzf_bg.jpg", ANIME_BG_NZF),
                "nz": ("nz_bg.jpg", ANIME_BG_NZ),
                "lol": ("lol_bg.jpg", ANIME_BG_LOL),
                "qqfc": ("qqfc_bg.jpg", ANIME_BG_QQFC),
                "qqxw": ("qqxw_bg.jpg", ANIME_BG_QQXW),
                "romance": ("romance_bg.jpg", ANIME_BG_ROMANCE),
                "douluo": ("douluo_bg.jpg", ANIME_BG_DOULUO),
                "pirate_king": ("pirate_bg.jpg", ANIME_BG_PIRATES),
                "dpcq": ("dpcq_bg.jpg", ANIME_BG_DPCQ),
                "valo": ("valo_bg.jpg", ANIME_BG_VALO),
                "hpjy": ("hpjy_bg.jpg", ANIME_BG_HPJY),
                "pokemon": ("pokemon_bg.jpg", ANIME_BG_POKEMON),
                "digimon": ("digimon_bg.jpg", ANIME_BG_DIGIMON),
                "genshin": ("genshin_bg.jpg", ANIME_BG_GENSHIN),
                "cyberpunk": ("cyberpunk_bg.jpg", ANIME_BG_CYBERPUNK),
                "cs": ("cs_bg.jpg", ANIME_BG_CS),
            }
            _fname, _b64data = _map.get(self.theme_key, ("anime_bg.jpg", ANIME_BG_B64))
            dest = os.path.join(assets, _fname)
            # 始终用内置最新图覆盖旧文件（强制覆盖，不检查大小，避免旧图残留）
            try:
                _new_data = _b64.b64decode(_b64data)
                with open(dest, "wb") as f:
                    f.write(_new_data)
            except Exception as _e:
                # 写入失败时记录日志
                try:
                    with open(os.path.join(app_dir(), "builtin_bg_debug.log"), "a", encoding="utf-8") as _fl:
                        _fl.write(f"[写入失败] theme={self.theme_key}, dest={dest}, error={repr(_e)}\n")
                except Exception:
                    pass
            # 确认文件存在后再设置背景
            if os.path.exists(dest) and os.path.getsize(dest) > 0:
                self._builtin_bg_loaded = True
                self.set_background(dest)
                self._bg_is_builtin = True
            else:
                # 文件不存在或为空，记录日志
                self._builtin_bg_loaded = False
                try:
                    with open(os.path.join(app_dir(), "builtin_bg_debug.log"), "a", encoding="utf-8") as _fl:
                        _fl.write(f"[文件无效] theme={self.theme_key}, dest={dest}, exists={os.path.exists(dest)}, size={os.path.getsize(dest) if os.path.exists(dest) else 0}\n")
                except Exception:
                    pass
        except Exception as e:
            self._builtin_bg_loaded = False
            try:
                with open(os.path.join(app_dir(), "builtin_bg_debug.log"), "a", encoding="utf-8") as _fl:
                    _fl.write(f"[异常] theme={self.theme_key}, error={repr(e)}\n")
            except Exception:
                pass

    def _paint_theme_decor(self, pp, theme):
        """为新主题绘制装饰图案（星星/光斑/爪印等）"""
        import random
        tk = self.theme_key
        ar = theme.get("accent_rgb", (255, 255, 255))
        random.seed(hash(tk) & 0xFFFF)
        if tk.startswith("sci_fi"):
            # 科幻主题：星星+光斑
            for _ in range(80):
                x = random.randint(0, self.width())
                y = random.randint(0, self.height())
                r = random.randint(1, 3)
                a = random.randint(80, 200)
                pp.setBrush(QColor(ar[0], ar[1], ar[2], a))
                pp.setPen(Qt.NoPen)
                pp.drawEllipse(x, y, r, r)
            # 大光斑
            for _ in range(5):
                x = random.randint(0, self.width())
                y = random.randint(0, self.height())
                r = random.randint(60, 120)
                pp.setBrush(QColor(ar[0], ar[1], ar[2], 15))
                pp.drawEllipse(x - r, y - r, r * 2, r * 2)
        elif tk.startswith("cat"):
            # 小猫主题：粉色光斑+小爪印圆点
            for _ in range(40):
                x = random.randint(0, self.width())
                y = random.randint(0, self.height())
                r = random.randint(2, 5)
                a = random.randint(40, 100)
                pp.setBrush(QColor(ar[0], ar[1], ar[2], a))
                pp.setPen(Qt.NoPen)
                pp.drawEllipse(x, y, r, r)
            for _ in range(8):
                x = random.randint(50, self.width() - 50)
                y = random.randint(50, self.height() - 50)
                pp.setBrush(QColor(ar[0], ar[1], ar[2], 25))
                pp.drawEllipse(x - 30, y - 30, 60, 60)

    def _build_bg_layer(self):
        # 构建背景层缓存：背景图或主题渐变 + 蒙版 + 网格线（玻璃主题另有模糊+呼吸高光）
        self._bg_layer = None
        try:
            sz = self.size()
            if sz.width() <= 0 or sz.height() <= 0:
                return
            layer = QPixmap(sz)
            layer.fill(Qt.transparent)
            pp = QPainter(layer)
            pp.setRenderHint(QPainter.Antialiasing)
            # 新主题壁纸：从menu_assets目录加载对应图片
            _new_theme_bg = None
            # 打包后从_MEIPASS找，开发时从源码目录找
            if getattr(sys, 'frozen', False):
                _meipass = getattr(sys, '_MEIPASS', '')
                if _meipass:
                    _p = os.path.join(_meipass, "menu_assets", self.theme_key + ".jpg")
                    if os.path.exists(_p):
                        _new_theme_bg = _p
            if not _new_theme_bg:
                _p = os.path.join(app_dir(), "menu_assets", self.theme_key + ".jpg")
                if os.path.exists(_p):
                    _new_theme_bg = _p
            if (not self.bg_pixmap) and _new_theme_bg and os.path.exists(_new_theme_bg):
                _pm = QPixmap(_new_theme_bg)
                if not _pm.isNull():
                    self.bg_pixmap = _pm
            if self.bg_pixmap and not self.bg_pixmap.isNull():
                # 填满窗口缩放（保持宽高比，裁剪多余部分，无黑边）
                scaled = self.bg_pixmap.scaled(sz, Qt.KeepAspectRatioByExpanding, Qt.SmoothTransformation)
                x = (self.width() - scaled.width()) // 2
                y = (self.height() - scaled.height()) // 2
                pp.drawPixmap(x, y, scaled)
                # 叠加一层暗色蒙版保证文字可读
                pp.fillRect(self.rect(), QColor(0, 0, 0, 80))
            else:
                # 主题渐变背景
                theme = THEMES.get(self.theme_key, THEMES[DEFAULT_THEME])
                bc = theme["bg_center"]
                be = theme["bg_edge"]
                grad = QRadialGradient(self.width() / 2, self.height() / 2, self.width())
                grad.setColorAt(0, QColor(bc[0], bc[1], bc[2]))
                grad.setColorAt(1, QColor(be[0], be[1], be[2]))
                pp.fillRect(self.rect(), grad)
                # 新主题装饰图案（科幻/小猫）
                self._paint_theme_decor(pp, theme)
                # 网格线
                gc = theme["grid"]
                pp.setPen(QColor(gc[0], gc[1], gc[2], gc[3]))
                for x in range(0, self.width(), 40):
                    pp.drawLine(x, 0, x, self.height())
                for y in range(0, self.height(), 40):
                    pp.drawLine(0, y, self.width(), y)
            pp.end()
            self._bg_layer = layer
            self._bg_layer_size = sz
            self._bg_layer_dirty = False
        except Exception as _e:
            try:
                with open(r"D:\游戏菜单\_bg_err.log", "a", encoding="utf-8") as _f:
                    _f.write(repr(_e) + "\n")
            except Exception:
                pass


