class UpdateDialog(QDialog):
    # 跨线程信号：下载完成(bool成功, 错误类型, 保存路径)、下载进度(int)
    download_finished = Signal(bool, str, str)
    download_progress = Signal(int)
    """软件更新对话框：显示版本信息、更新公告，支持下载或打开浏览器"""
    def __init__(self, has_update, latest_version, download_url, notice, release_date="", update_content="", backup_url="", download_password="", parent=None):
        super().__init__(parent)
        self.has_update = has_update
        self.latest_version = latest_version
        self.download_url = download_url
        self.backup_url = backup_url
        self.download_password = download_password
        self.notice = notice
        self.release_date = release_date
        self.update_content = update_content
        self.setWindowTitle("在线更新")
        self.setFixedSize(560, 480)
        self.setStyleSheet("""
            QDialog { background:rgba(20,0,30,255); }
            QLabel { color:#ff33aa; font-family:'Microsoft YaHei'; }
            QPushButton { background:rgba(255,51,170,40); color:#ffffff; border:2px solid #ff33aa;
                          border-radius:6px; padding:10px 20px; font-size:14px; font-weight:bold;
                          font-family:'Microsoft YaHei'; }
            QPushButton:hover { background:rgba(255,51,170,60); }
            QPushButton:disabled { background:rgba(100,100,100,40); color:#888888; border-color:#666666; }
            QScrollArea { background:rgba(0,0,0,100); border:1px solid rgba(255,51,170,100); border-radius:6px; }
            QProgressBar { background:rgba(0,0,0,200); border:1px solid #ff33aa; border-radius:4px; text-align:center; color:#ffffff; }
            QProgressBar::chunk { background:linear-gradient(90deg, #ff33aa, #aa55ff); border-radius:3px; }
        """)
        # 连接跨线程下载信号到主线程槽函数
        self.download_finished.connect(self._download_finished)
        self.download_progress.connect(lambda p: self.progress_bar.setValue(p))
        self._build_ui()

    def _build_ui(self):
        lay = QVBoxLayout(self)
        lay.setContentsMargins(20, 20, 20, 20)
        lay.setSpacing(12)

        # 标题
        title = QLabel("🔄 在线更新")
        title.setStyleSheet("font-size:20px; font-weight:bold; color:#ff33aa;")
        title.setAlignment(Qt.AlignCenter)
        lay.addWidget(title)

        # 版本信息
        if self.has_update:
            version_text = f"发现新版本！\n当前版本：{format_version(APP_VERSION)}  →  最新版本：{format_version(self.latest_version)}"
            if self.release_date:
                version_text += f"\n发布日期：{self.release_date}"
        else:
            version_text = f"当前已是最新版本！\n当前版本：{format_version(APP_VERSION)}"
        version_lbl = QLabel(version_text)
        version_lbl.setStyleSheet("font-size:14px; color:#ffffff;")
        version_lbl.setAlignment(Qt.AlignCenter)
        version_lbl.setWordWrap(True)
        lay.addWidget(version_lbl)

        # 更新内容
        if update_content:
            update_lbl = QLabel(update_content)
            update_lbl.setStyleSheet("font-size:12px; color:rgba(255,255,255,200); padding:8px; background:rgba(255,255,255,15); border-radius:6px;")
            update_lbl.setWordWrap(True)
            update_lbl.setOpenExternalLinks(True)
            update_lbl.setTextFormat(Qt.RichText)
            lay.addWidget(update_lbl)

        # 文件类型提示
        self.file_type_lbl = QLabel("")
        self.file_type_lbl.setStyleSheet("font-size:12px; color:rgba(255,215,0,220);")
        self.file_type_lbl.setAlignment(Qt.AlignCenter)
        lay.addWidget(self.file_type_lbl)
        if self.has_update and self.download_url:
            ext = url_file_ext(self.download_url)
            if ext == 'exe':
                self.file_type_lbl.setText("📦 检测到文件类型：安装程序 (.exe) — 下载完成后自动安装")
            elif ext == 'zip':
                self.file_type_lbl.setText("📦 检测到文件类型：压缩包 (.zip) — 下载完成后打开文件夹")
            else:
                self.file_type_lbl.setText("🔗 检测到网页链接 — 将在浏览器中打开")

        # ===== 游戏菜单网站链接 =====
        link_lbl = QLabel('<a href="http://xgadmin520.3vkj.vip/" style="color:#ff77c9; text-decoration:none;">🌐 游戏菜单网站：http://xgadmin520.3vkj.vip/</a>')
        link_lbl.setOpenExternalLinks(True)
        link_lbl.setStyleSheet("font-size:13px; color:#ff77c9; padding:8px;")
        link_lbl.setAlignment(Qt.AlignCenter)
        link_lbl.setTextFormat(Qt.RichText)
        lay.addWidget(link_lbl)

        # 下载进度条（初始隐藏）
