        self.progress_bar.setVisible(False)
        self.progress_bar.setFormat("下载中... %p%")
        lay.addWidget(self.progress_bar)

        # 访问密码（蓝奏云等网盘）：显示并支持一键复制
        if self.download_password and self.has_update:
            pwd_lay = QHBoxLayout()
            pwd_lbl = QLabel(f"🔑 访问密码：{self.download_password}")
            pwd_lbl.setStyleSheet("font-size:14px; font-weight:bold; color:#ffd700;")
            pwd_lay.addStretch()
            pwd_lay.addWidget(pwd_lbl)
            self.btn_copy_pwd = QPushButton("📋 复制密码")
            self.btn_copy_pwd.setStyleSheet(
                "QPushButton { background:rgba(255,215,0,30); color:#ffd700; border:1px solid #ffd700;"
                " border-radius:6px; padding:6px 16px; font-size:13px; font-weight:bold; }"
                "QPushButton:hover { background:rgba(255,215,0,50); }"
            )
            self.btn_copy_pwd.clicked.connect(self._copy_password)
            pwd_lay.addWidget(self.btn_copy_pwd)
            pwd_lay.addStretch()
            lay.addLayout(pwd_lay)

        # 按钮区域
