    def _download_update(self):
        """下载更新文件（主地址失效自动切换备用地址）"""
        from PySide6.QtWidgets import QFileDialog
        # 选择保存目录
        save_dir = QFileDialog.getExistingDirectory(self, "选择保存目录", os.path.join(os.path.expanduser("~"), "Desktop"))
        if not save_dir:
            return
        # 下载地址列表：主地址 + 备用地址
        urls = [u for u in [self.download_url, self.backup_url] if u]
        if not urls:
            return
        # 文件名（从链接或响应头提取，解码URL编码）
        filename = _guess_filename(self.download_url)
        if not filename:
            ext = url_file_ext(self.download_url) or 'exe'
            # 如果服务器只允许上传 png，实际是 exe 安装包，自动改名为 exe
            if ext == 'png':
                ext = 'exe'
            filename = f"游戏菜单{self.latest_version}.{ext}"
        save_path = os.path.join(save_dir, filename)
        # 显示进度条
        self.progress_bar.setVisible(True)
        self.progress_bar.setValue(0)
        # 禁用按钮
        if hasattr(self, 'btn_download'):
            self.btn_download.setEnabled(False)
        self.btn_close.setEnabled(False)
        # 在后台线程下载（先主地址，失败自动用备用地址）
        import threading
        def do_download():
            ok, err, real_name = download_file(urls[0], save_path, self._update_progress)
            if not ok and len(urls) > 1:
                ok, err, real_name = download_file(urls[1], save_path, self._update_progress)
            if not ok:
                self.download_finished.emit(False, 'all_failed', save_path)
                return
            # 若保存的文件名无扩展名，但响应头有真实文件名 → 重命名
            final_path = save_path
            if real_name and not os.path.splitext(save_path)[1]:
                new_path = os.path.join(os.path.dirname(save_path), real_name)
                try:
                    if os.path.exists(new_path):
                        os.remove(new_path)
                    os.rename(save_path, new_path)
                    final_path = new_path
                except Exception:
                    final_path = save_path
            self.download_finished.emit(True, "", final_path)
        threading.Thread(target=do_download, daemon=True).start()

    def _update_progress(self, progress):
        """更新下载进度（在下载线程中调用）"""
        self.download_progress.emit(progress)

    def _download_finished(self, success, error_type, save_path):
        """下载完成（在主线程调用）"""
        self.btn_close.setEnabled(True)
        if not success and error_type == 'all_failed':
            # 所有下载地址均失效：提示联系作者
            self.progress_bar.setFormat("所有下载地址均失效！")
            self.progress_bar.setVisible(False)
            if hasattr(self, 'btn_download'):
                self.btn_download.setEnabled(True)
            from PySide6.QtWidgets import QMessageBox
            QMessageBox.warning(self, "下载失败",
                                "所有下载地址均不可用（可能已过期或被限制）。\n请联系作者获取最新安装包。")
            return
        if not success and error_type == 'invalid_link':
            # 链接失效：清理，引导浏览器打开
            self.progress_bar.setFormat("下载链接已失效！")
            self.progress_bar.setVisible(False)
            from PySide6.QtWidgets import QMessageBox
            QMessageBox.warning(self, "下载失败",
                                "下载链接已失效（可能已过期或被限制）。\n请点击「在浏览器中打开」获取新的下载页面。")
            if hasattr(self, 'btn_download'):
                self.btn_download.setText("🌐 在浏览器中打开")
                self.btn_download.clicked.disconnect()
                self.btn_download.clicked.connect(self._open_in_browser)
                self.btn_download.setEnabled(True)
            return
        if not success and error_type == 'network':
            self.progress_bar.setFormat("下载失败！")
            self.progress_bar.setVisible(False)
            if hasattr(self, 'btn_download'):
                self.btn_download.setEnabled(True)
            from PySide6.QtWidgets import QMessageBox
            QMessageBox.warning(self, "下载失败", "网络错误，请检查网络连接后重试。")
            return
        if success:
            self.progress_bar.setFormat("下载完成！")
            from PySide6.QtWidgets import QMessageBox
            ext = url_file_ext(self.download_url)
            if ext == 'exe':
                # exe：询问是否立即安装
                _mb = QMessageBox(self)
                _mb.setWindowTitle("下载完成")
                _mb.setText(f"更新文件已下载到：\n{save_path}\n\n是否立即安装？")
                _mb.setIcon(QMessageBox.Question)
                _b_install = _mb.addButton("立即安装", QMessageBox.AcceptRole)
                _b_later = _mb.addButton("暂不安装", QMessageBox.RejectRole)
                _mb.setDefaultButton(_b_later)
                _mb.exec()
                if _mb.clickedButton() == _b_install:
                    import subprocess
                    try:
                        os.startfile(save_path)
                    except Exception as e:
                        QMessageBox.warning(self, "启动失败", f"无法启动安装程序：{e}")
            elif ext == 'zip':
                # zip：提示并打开所在文件夹
                import subprocess
                QMessageBox.information(self, "下载完成",
                                        f"压缩包已下载到：\n{save_path}\n\n点击确定打开所在文件夹。")
                try:
                    subprocess.Popen(['explorer', '/select,', save_path])
                except Exception:
                    pass
            else:
                QMessageBox.information(self, "下载完成", f"文件已下载到：\n{save_path}")
            self.accept()
        else:
            self.progress_bar.setFormat("下载失败！")
            self.progress_bar.setVisible(False)
            if hasattr(self, 'btn_download'):
                self.btn_download.setEnabled(True)
            from PySide6.QtWidgets import QMessageBox
            QMessageBox.warning(self, "下载失败", "更新文件下载失败，请检查网络连接后重试。")

    def _open_in_browser(self):
        """在浏览器中打开下载页面（蓝奏云带密码时自动复制密码并提示）"""
        import webbrowser
        try:
            pwd = getattr(self, 'download_password', '') or ''
            if pwd:
                try:
                    from PySide6.QtWidgets import QApplication
                    QApplication.clipboard().setText(pwd)
                except Exception:
                    pass
                from PySide6.QtWidgets import QMessageBox
                QMessageBox.information(
                    self, "访问密码",
                    f"网盘访问密码：{pwd}\n\n已复制到剪贴板，请在打开的网页中输入该密码。")
            webbrowser.open(self.download_url)
        except Exception as e:
            from PySide6.QtWidgets import QMessageBox
            QMessageBox.warning(self, "打开失败", f"无法打开浏览器：{e}")


