    def _draw_island_demo(self, label):
        """用代码绘制灵动岛示意图（不覆盖notice_pixmaps）"""
        try:
            from PySide6.QtGui import QPixmap, QPainter, QColor, QFont, QBrush, QPen
            from PySide6.QtCore import Qt, QRectF
            pixmap = QPixmap(400, 160)
            pixmap.fill(Qt.transparent)
            painter = QPainter(pixmap)
            painter.setRenderHint(QPainter.Antialiasing)
            # 灵动岛胶囊背景
            bg_rect = QRectF(10, 30, 380, 100)
            painter.setBrush(QBrush(QColor(0, 0, 0, 240)))
            painter.setPen(QPen(QColor(255, 255, 255, 100), 2))
            painter.drawRoundedRect(bg_rect, 50, 50)
            # 左边图标圆形背景
            icon_rect = QRectF(30, 45, 70, 70)
            painter.setBrush(QBrush(QColor(255, 51, 170, 220)))
            painter.setPen(Qt.NoPen)
            painter.drawEllipse(icon_rect)
            # 图标文字
            painter.setPen(QColor(255, 255, 255))
            font = QFont("Microsoft YaHei", 28)
            painter.setFont(font)
            painter.drawText(icon_rect, Qt.AlignCenter, "🎮")
            # 中间文字
            text_rect = QRectF(115, 30, 250, 100)
            painter.setPen(QColor(255, 255, 255))
            font = QFont("Microsoft YaHei", 16, QFont.Bold)
            painter.setFont(font)
            painter.drawText(text_rect, Qt.AlignVCenter | Qt.AlignLeft, "灵动岛提示效果")
            # 右边红色小点
            dot_rect = QRectF(355, 72, 16, 16)
            painter.setBrush(QBrush(QColor(255, 0, 0, 255)))
            painter.setPen(Qt.NoPen)
            painter.drawEllipse(dot_rect)
            painter.end()
            # 缩放显示（保持比例）
            target_h = 140
            if pixmap.height() > 0:
                target_w = int(pixmap.width() * target_h / pixmap.height())
            else:
                target_w = 350
            scaled = pixmap.scaled(target_w, target_h, Qt.KeepAspectRatio, Qt.SmoothTransformation)
            if scaled.isNull():
                scaled = pixmap
            label.setPixmap(scaled)
            # 保存到 notice_pixmaps 的第二个位置（不覆盖第一个）
            if not hasattr(self, 'notice_pixmaps') or self.notice_pixmaps is None:
                self.notice_pixmaps = []
            while len(self.notice_pixmaps) < 2:
                self.notice_pixmaps.append(None)
            self.notice_pixmaps[1] = pixmap
        except Exception as e:
            print(f"[_draw_island_demo error] {e}")

