        # 灵动岛形状选择
        shape_row = QHBoxLayout()
        shape_row_lbl = QLabel("灵动岛图标形状:")
        shape_row_lbl.setFixedWidth(120)
        self.balloon_shape_combo = QComboBox()
        shape_list = [
            ("circle", "● 圆形"),
            ("square", "■ 方形"),
            ("triangle", "▲ 三角形"),
            ("diamond", "◆ 菱形"),
            ("star", "★ 五角星"),
            ("heart", "♥ 心形"),
        ]
        for sk, sn in shape_list:
            pix = QPixmap(20, 20)
            pix.fill(Qt.transparent)
            pp = QPainter(pix)
            pp.setRenderHint(QPainter.Antialiasing)
            pp.setPen(Qt.NoPen)
            pp.setBrush(QBrush(QColor("#ff4444")))
            if sk == "circle":
                pp.drawEllipse(2, 2, 16, 16)
            elif sk == "square":
                pp.drawRoundedRect(2, 2, 16, 16, 2, 2)
            elif sk == "triangle":
                pp.drawPolygon(QPolygonF([QPointF(10, 2), QPointF(2, 18), QPointF(18, 18)]))
            elif sk == "diamond":
                pp.drawPolygon(QPolygonF([QPointF(10, 1), QPointF(19, 10), QPointF(10, 19), QPointF(1, 10)]))
            elif sk == "star":
                poly = QPolygonF()
                for i in range(10):
                    ang = -math.pi/2 + i * math.pi/5
                    r = 9 if i % 2 == 0 else 3.8
                    poly.append(QPointF(10 + r*math.cos(ang), 10 + r*math.sin(ang)))
                pp.drawPolygon(poly)
            elif sk == "heart":
                from PySide6.QtGui import QPainterPath
                k = 2.0
                path = QPainterPath()
                path.moveTo(10, 18)
                path.cubicTo(0, 10, 0, 4, 5, 2.5)
                path.cubicTo(8, 1, 10, 4, 10, 6)
                path.cubicTo(10, 4, 12, 1, 15, 2.5)
                path.cubicTo(20, 4, 20, 10, 10, 18)
                pp.drawPath(path)
            pp.end()
            self.balloon_shape_combo.addItem(QIcon(pix), sn, sk)
        self.balloon_shape_combo.setIconSize(QSize(20, 20))
        _bsh = self.parent().cfg.data.get("balloon_shape", "circle")
