        # 使用QStandardItemModel，每个选项显示主题颜色（背景色+强调色文字）
        from PySide6.QtGui import QStandardItemModel, QStandardItem, QColor, QBrush
        theme_model = QStandardItemModel()
        def _theme_sort_key(kv):
            _n = kv[1].get("name", "")
            if _n.startswith("游戏"):
                return (1, "")
            return (0, _n)
        for key, theme in sorted(THEMES.items(), key=_theme_sort_key):
            item = QStandardItem("  " + theme["name"])
            item.setData(QColor(theme.get("bg", "#1a0010")), Qt.BackgroundRole)
            item.setData(QColor(theme.get("accent", "#ff33aa")), Qt.ForegroundRole)
            item.setData(key, Qt.UserRole)
            theme_model.appendRow(item)
        self.theme_combo.setModel(theme_model)
        self.theme_combo.setStyleSheet("""
            QComboBox { background:rgba(25,0,18,200); color:#ff33aa; border:1px solid #ff33aa;
                        border-radius:4px; padding:6px 10px; font-size:13px; min-height:20px; }
            QComboBox:hover { border-color:#ff66cc; }
            QComboBox::drop-down { border:none; width:24px; }
            QComboBox QAbstractItemView { background:rgba(20,0,15,240); color:#ff33aa;
                                            selection-background-color:rgba(255,51,170,40);
                                            border:1px solid #ff33aa; outline:none;
                                            show-decoration-selected:1; }
            QComboBox QAbstractItemView::item { min-height:28px; padding:4px 8px; }
        """)
        saved_theme = self.current_theme
        # 遍历model找到对应的主题key
        for i in range(self.theme_combo.count()):
            item = self.theme_combo.model().item(i)
            if item and item.data(Qt.UserRole) == saved_theme:
                self.theme_combo.setCurrentIndex(i)
                break
        # 主题下拉框选择改变时发射 theme_changed 信号
        def _on_theme_combo_changed(idx):
            if idx >= 0:
                item = self.theme_combo.model().item(idx)
                if item:
                    theme_key = item.data(Qt.UserRole)
                    if theme_key:
                        self.theme_changed.emit(theme_key)
        self.theme_combo.currentIndexChanged.connect(_on_theme_combo_changed)
        theme_combo_layout.addWidget(self.theme_combo, 1)
