    def _pick_exe(self):
        path, _ = QFileDialog.getOpenFileName(
            self, "选择 EXE 文件", "", "可执行文件 (*.exe);;所有文件 (*.*)"
        )
        if path:
            if not path.lower().endswith('.exe'):
                QMessageBox.warning(self, "格式错误", "只能添加 .exe 可执行文件！\n图片及其他格式不被接受。")
                return
            default_name = display_name(path)
            # 自定义对话框（中文按钮+中文右键菜单）
            from PySide6.QtWidgets import QDialog, QVBoxLayout, QHBoxLayout, QLabel, QPushButton
            _dlg = QDialog(self)
            _dlg.setWindowTitle("设置标题")
            _dlg.setFixedWidth(360)
            _lay = QVBoxLayout(_dlg)
            _lbl = QLabel("请输入软件显示名称：")
            _lay.addWidget(_lbl)
            _edit = CnLineEdit(default_name)
            _edit.selectAll()
            _edit.setFixedHeight(36)
            _lay.addWidget(_edit)
            _btn_lay = QHBoxLayout()
            _btn_lay.addStretch()
            _btn_ok = QPushButton("确定")
            _btn_ok.setFixedWidth(80)
            _btn_ok.clicked.connect(_dlg.accept)
            _btn_lay.addWidget(_btn_ok)
            _btn_cancel = QPushButton("取消")
            _btn_cancel.setFixedWidth(80)
            _btn_cancel.clicked.connect(_dlg.reject)
            _btn_lay.addWidget(_btn_cancel)
            _lay.addLayout(_btn_lay)
            _edit.returnPressed.connect(_dlg.accept)
            if _dlg.exec() == QDialog.Accepted:
                name = _edit.text().strip() if _edit.text().strip() else default_name
                cat_key = self.add_cat_combo.currentData()
                self.add_exe.emit(path, name, cat_key)
                cat_name = self.add_cat_combo.currentText()
                QMessageBox.information(self, "已添加", f"已添加到 [{cat_name}]:\n{name}\n({path})")

