    def _on_upload_search_icon(self):
        """上传自定义搜索框图标图片（自动裁剪80×39，保存到文件）"""
        from PySide6.QtWidgets import QFileDialog
        from PySide6.QtGui import QPixmap
        from PySide6.QtCore import QRect
        import os
        path, _ = QFileDialog.getOpenFileName(self, "选择图标图片", "", "图片文件 (*.png *.jpg *.jpeg *.bmp *.gif)")
        if not path:
            return
        try:
            pix = QPixmap(path)
            if pix.isNull():
                return
            # 裁剪为40×29（保持比例填充，居中裁剪）
            target_w, target_h = 40, 29
            src_w, src_h = pix.width(), pix.height()
            target_ratio = target_w / target_h
            src_ratio = src_w / src_h
            if src_ratio > target_ratio:
                new_w = int(src_h * target_ratio)
                new_h = src_h
                x = (src_w - new_w) // 2
                y = 0
            else:
                new_w = src_w
                new_h = int(src_w / target_ratio)
                x = 0
                y = (src_h - new_h) // 2
            cropped = pix.copy(QRect(x, y, new_w, new_h))
            pix = cropped.scaled(target_w, target_h, Qt.IgnoreAspectRatio, Qt.SmoothTransformation)
            # 保存到文件目录
            import sys
            if getattr(sys, 'frozen', False):
                save_dir = os.path.join(os.path.dirname(sys.executable), "search_icons")
            else:
                save_dir = os.path.dirname(os.path.abspath(__file__))
            os.makedirs(save_dir, exist_ok=True)
            save_path = os.path.join(save_dir, "search_icon.png")
            pix.save(save_path, "PNG")
            # 保存配置
            self.parent().cfg.data["search_icon"] = "custom"
            self.parent().cfg.data["search_icon_path"] = save_path
            self.parent().cfg.save()
            # 立即同步更新搜索框图标（不用重启）
            try:
                if hasattr(self.parent(), 'search_edit'):
                    # 找到搜索框右边的图标QLabel并更新
                    search_widget = self.parent().search_edit.parent()
                    for child in search_widget.findChildren(QLabel):
                        if child != self.parent().search_edit:
                            _new_pix = QPixmap(save_path)
                            if not _new_pix.isNull():
                                child.setPixmap(_new_pix.scaled(40, 29, Qt.IgnoreAspectRatio, Qt.SmoothTransformation))
                            break
            except Exception:
                pass
            # 灵动岛提示
            try:
                self.parent()._show_island("搜索框图标已更新：80×39")
            except Exception:
                pass
        except Exception as e:
            pass

