# ============================================================
# 主窗口
# ============================================================

# ============================================================
# 原生 Win32 托盘实现（替代 QSystemTrayIcon）
# 背景：PySide6 的 QSystemTrayIcon 在部分 Windows 环境（尤其有安全软件
# 注入托盘消息时）点击图标瞬间 native 崩溃，Python 层无法捕获/防护。
# 本实现直接用 Shell_NotifyIconW 添加托盘图标，用 QAbstractNativeEventFilter
# 捕获托盘回调消息，完全绕开 QSystemTrayIcon，兼容 Qt 事件循环。
# ============================================================
try:
    _SHELL32 = ctypes.windll.shell32
    _USER32 = ctypes.windll.user32
    _HAS_WIN32 = True
except Exception:
    _HAS_WIN32 = False

# Shell_NotifyIconW 消息常量（NIM_ADD=0 必须正确，此前误写为1导致托盘图标永远添加失败）
_NIM_ADD = 0x00000000
_NIM_MODIFY = 0x00000001
_NIM_DELETE = 0x00000002
_NIM_SETVERSION = 0x00000004
_NIF_MESSAGE = 0x00000001
_NIF_ICON = 0x00000002
_NIF_TIP = 0x00000004
_NIF_INFO = 0x00000010
_NIIF_INFO = 0x00000001
_WM_LBUTTONUP = 0x0202
_WM_LBUTTONDBLCLK = 0x0203
_WM_RBUTTONUP = 0x0205
_IMAGE_ICON = 1
_LR_LOADFROMFILE = 0x0010
_IDI_APPLICATION = 32512


class _NOTIFYICONIDENTIFIER(ctypes.Structure):
    _fields_ = [
        ("cbSize", wintypes.DWORD),
        ("hWnd", wintypes.HWND),
        ("uID", wintypes.UINT),
        ("guidItem", ctypes.c_byte * 16),
    ]


class _NOTIFYICONDATAW(ctypes.Structure):
    _fields_ = [
        ("cbSize", wintypes.DWORD),
        ("hWnd", wintypes.HWND),
        ("uID", wintypes.UINT),
        ("uFlags", wintypes.UINT),
        ("uCallbackMessage", wintypes.UINT),
        ("hIcon", wintypes.HICON),
        ("szTip", wintypes.WCHAR * 128),
        ("dwState", wintypes.DWORD),
        ("dwStateMask", wintypes.DWORD),
        ("szInfo", wintypes.WCHAR * 256),
        ("uVersion", wintypes.UINT),
        ("szInfoTitle", wintypes.WCHAR * 64),
        ("dwInfoFlags", wintypes.DWORD),
        ("guidItem", ctypes.c_byte * 16),
        ("hBalloonIcon", wintypes.HICON),
    ]


# Shell API 参数类型声明：64位进程下ctypes默认按32位传递指针会截断导致调用失败，
# 必须显式设置argtypes/restype
_SHELL32.Shell_NotifyIconW.argtypes = [wintypes.DWORD, ctypes.POINTER(_NOTIFYICONDATAW)]
_SHELL32.Shell_NotifyIconW.restype = wintypes.BOOL
_SHELL32.Shell_NotifyIconGetRect.argtypes = [ctypes.POINTER(_NOTIFYICONIDENTIFIER), ctypes.POINTER(wintypes.RECT)]
_SHELL32.Shell_NotifyIconGetRect.restype = wintypes.LONG
_USER32.LoadImageW.argtypes = [wintypes.HINSTANCE, wintypes.LPCWSTR, wintypes.UINT, ctypes.c_int, ctypes.c_int, wintypes.UINT]
_USER32.LoadImageW.restype = wintypes.HANDLE
_USER32.RegisterWindowMessageW.argtypes = [wintypes.LPCWSTR]
_USER32.RegisterWindowMessageW.restype = wintypes.UINT
_USER32.DestroyIcon.argtypes = [wintypes.HICON]
_USER32.DestroyIcon.restype = wintypes.BOOL
_USER32.LoadIconW.argtypes = [wintypes.HINSTANCE, wintypes.LPCWSTR]
_USER32.LoadIconW.restype = wintypes.HICON

# Shell API 参数类型声明：64位进程下ctypes默认按32位传递指针会截断导致调用失败，
# 必须显式设置argtypes/restype
_SHELL32.Shell_NotifyIconW.argtypes = [wintypes.DWORD, ctypes.POINTER(_NOTIFYICONDATAW)]
_SHELL32.Shell_NotifyIconW.restype = wintypes.BOOL
_SHELL32.Shell_NotifyIconGetRect.argtypes = [ctypes.POINTER(_NOTIFYICONIDENTIFIER), ctypes.POINTER(wintypes.RECT)]
_SHELL32.Shell_NotifyIconGetRect.restype = wintypes.LONG
_USER32.LoadImageW.argtypes = [wintypes.HINSTANCE, wintypes.LPCWSTR, wintypes.UINT, ctypes.c_int, ctypes.c_int, wintypes.UINT]
_USER32.LoadImageW.restype = wintypes.HANDLE
_USER32.RegisterWindowMessageW.argtypes = [wintypes.LPCWSTR]
_USER32.RegisterWindowMessageW.restype = wintypes.UINT
_USER32.DestroyIcon.argtypes = [wintypes.HICON]
_USER32.DestroyIcon.restype = wintypes.BOOL
_USER32.LoadIconW.argtypes = [wintypes.HINSTANCE, wintypes.LPCWSTR]
_USER32.LoadIconW.restype = wintypes.HICON


class NativeTray:
    """Shell_NotifyIcon 托盘，接口兼容旧 self.tray 调用。"""

    def __init__(self, window, on_activate=None, on_context=None):
        self.window = window
        self.on_activate = on_activate      # 左键单击/双击
        self.on_context = on_context        # 右键
        self._visible = False
        self._icon_handle = None
        self._icon_path = None
        self._tip = ""
        self.uID = 0x5A58
        self.WM_TRAY = 0x0400 + 0x5A58
        self._filter = None
        self._taskbar_msg = 0
        self._show_msg = 0  # 单例唤醒消息（第二实例发来，恢复本窗口）
        self._hwnd = 0  # 窗口句柄缓存：避免消息回调中反复 winId() 触发窗口重建导致递归

    # ---------- 内部 ----------
    def _nid(self, hwnd, delete=False):
        nid = _NOTIFYICONDATAW()
        nid.cbSize = ctypes.sizeof(nid)
        if hwnd:
            nid.hWnd = hwnd
        elif self._hwnd:
            nid.hWnd = self._hwnd
        else:
            nid.hWnd = int(self.window.winId())
        nid.uID = self.uID
        if delete:
            nid.uFlags = 0
            return nid
        nid.uFlags = _NIF_MESSAGE | _NIF_ICON | _NIF_TIP
        nid.uCallbackMessage = self.WM_TRAY
        nid.hIcon = self._get_icon_handle()
        try:
            nid.szTip = self._tip[:127]
        except Exception:
            pass
        return nid

    def _get_icon_handle(self):
        if self._icon_handle:
            return self._icon_handle
        path = self._icon_path
        # 1) 指定图标：.ico/.cur 用 LoadImageW；PNG/JPG/BMP 用 Qt 转 HICON
        if path and os.path.exists(path):
            ext = os.path.splitext(path)[1].lower()
            try:
                if ext in ('.ico', '.cur'):
                    h = _USER32.LoadImageW(0, path, _IMAGE_ICON, 32, 32, _LR_LOADFROMFILE)
                    if h:
                        self._icon_handle = h
                        return h
                else:
                    from PySide6.QtGui import QPixmap
                    _pm = QPixmap(path)
                    if not _pm.isNull():
                        h = _qpixmap_to_hicon(_pm, 32)
                        if h:
                            self._icon_handle = h
                            return h
            except Exception:
                pass
        # 2) 内置 app_icon.ico（打包后在 _MEIPASS，开发时在源码目录）
        try:
            _builtin = resource_path("app_icon.ico")
            if _builtin:
                h = _USER32.LoadImageW(0, _builtin, _IMAGE_ICON, 32, 32, _LR_LOADFROMFILE)
                if h:
                    self._icon_handle = h
                    return h
        except Exception:
            pass
        # 3) 内置 ico 也失败：用 Qt 加载内置图标再转 HICON
        try:
            _builtin = resource_path("app_icon.ico")
            if _builtin:
                from PySide6.QtGui import QPixmap
                _pm = QPixmap(_builtin)
                if not _pm.isNull():
                    h = _qpixmap_to_hicon(_pm, 32)
                    if h:
                        self._icon_handle = h
                        return h
        except Exception:
            pass
        # 4) 系统默认图标兜底（cast 整数资源 ID 为 LPCWSTR）
        try:
            h = _USER32.LoadIconW(0, ctypes.cast(_IDI_APPLICATION, wintypes.LPCWSTR))
            if h:
                self._icon_handle = h
                return h
        except Exception:
            pass
        return 0

    def _free_icon(self):
        try:
            if self._icon_handle:
                _USER32.DestroyIcon(self._icon_handle)
        except Exception:
            pass
        self._icon_handle = None

    # ---------- 接口 ----------
    def show(self):
        if not _HAS_WIN32:
            return
        # 防重复添加：已经显示则直接返回，避免托盘重影
        if getattr(self, '_visible', False):
            return
        try:
            self._hwnd = int(self.window.winId())
            # 幂等：先删除可能残留的同(hwnd,uID)图标，再添加，从根本上杜绝重影
            try:
                nid_del = self._nid(self._hwnd, delete=True)
                _SHELL32.Shell_NotifyIconW(_NIM_DELETE, ctypes.byref(nid_del))
            except Exception:
                pass
            nid = self._nid(self._hwnd)
            _r = _SHELL32.Shell_NotifyIconW(_NIM_ADD, ctypes.byref(nid))
            self._trace(f'show: NIM_ADD={_r}')
            if _r:
                self._visible = True
                self._set_version()
            else:
                # 首次失败：延迟多次重试（资源管理器/托盘服务瞬态不可用，常见于刚开机）
                self._schedule_retry()
        except Exception as _e:
            self._trace(f'show: NIM_ADD异常 {_e}')
            self._schedule_retry()
        try:
            # 事件过滤器必须无条件安装：即使NIM_ADD失败(极端环境/安全软件拦截)，
            # 也要能处理托盘回调消息，保证点击路径可用
            if self._filter is None:
                self._filter = _TrayEventFilter(self)
                app = QApplication.instance()
                if app:
                    app.installNativeEventFilter(self._filter)
                    self._trace('show: 过滤器已安装')
        except Exception as _e:
            self._trace(f'show: 过滤器异常 {_e}')
        try:
            self._taskbar_msg = _USER32.RegisterWindowMessageW("TaskbarCreated")
        except Exception:
            pass
        try:
            self._show_msg = _USER32.RegisterWindowMessageW("XueZhiXiaGameMenuShowMsgV7")
        except Exception:
            pass

    def _set_version(self):
        # 设置通知版本（标准做法，兼容 Win7/8/10/11 托盘回调）
        try:
            _v = _NOTIFYICONDATAW()
            _v.cbSize = ctypes.sizeof(_v)
            _v.hWnd = self._hwnd if self._hwnd else int(self.window.winId())
            _v.uID = self.uID
            _v.uVersion = 4
            _SHELL32.Shell_NotifyIconW(_NIM_SETVERSION, ctypes.byref(_v))
        except Exception:
            pass

    def _schedule_retry(self):
        # 多次延迟重试：刚开机/explorer重启时托盘服务可能未就绪
        try:
            n = getattr(self, '_retry_count', 0)
            if n >= 4:
                return
            self._retry_count = n + 1
            delays = [2000, 5000, 10000, 20000]
            # 用 QTimer 实例（父窗口）替代 singleShot：事件循环内可靠触发
            if getattr(self, '_retry_timer', None) is None:
                from PySide6.QtCore import QTimer
                self._retry_timer = QTimer(self.window)
                self._retry_timer.setSingleShot(True)
                self._retry_timer.timeout.connect(self._retry_show)
            self._retry_timer.start(delays[n])
        except Exception:
            pass

    def _retry_show(self):
        # NIM_ADD 首次失败后的延迟重试：刚开机/资源管理器重启时托盘服务可能瞬态不可用
        try:
            if self._visible:
                return
            self._hwnd = int(self.window.winId())
            # 幂等：重试前先清理可能残留的同 uID 图标
            try:
                nid_del = self._nid(self._hwnd, delete=True)
                _SHELL32.Shell_NotifyIconW(_NIM_DELETE, ctypes.byref(nid_del))
            except Exception:
                pass
            nid = self._nid(self._hwnd)
            _r = _SHELL32.Shell_NotifyIconW(_NIM_ADD, ctypes.byref(nid))
            self._trace(f'show重试: NIM_ADD={_r}')
            if _r:
                self._visible = True
                self._set_version()
                # 重试成功后也弹气泡（首次失败重试成功的情况）
                self.show_balloon()
            else:
                self._schedule_retry()
        except Exception as _e:
            self._trace(f'show重试异常 {_e}')

    def hide(self):
        if not _HAS_WIN32:
            return
        # 无条件尝试删除：即使 _visible=False（状态可能与 explorer 不同步），
        # 也要确保托盘图标被清除，避免关闭后残留僵尸图标（鼠标划过去才消失）。
        # 同时用缓存的 self._hwnd 和当前 winId() 各删一次，
        # 防止关闭瞬间窗口句柄重建导致 NIM_DELETE 打到错误句柄而删不掉。
        _hwnds = []
        if getattr(self, "_hwnd", 0):
            _hwnds.append(self._hwnd)
        try:
            _cur = int(self.window.winId())
            if _cur not in _hwnds:
                _hwnds.append(_cur)
        except Exception:
            pass
        for _h in _hwnds:
            try:
                nid = self._nid(_h, delete=True)
                _SHELL32.Shell_NotifyIconW(_NIM_DELETE, ctypes.byref(nid))
            except Exception:
                pass
        self._visible = False

    def isVisible(self):
        return self._visible

    def setToolTip(self, tip):
        self._tip = str(tip or "")
        self._update()

    def setIcon(self, icon):
        try:
            if isinstance(icon, str) and os.path.exists(icon):
                self._icon_path = icon
            elif icon is not None and hasattr(icon, 'pixmap'):
                pm = icon.pixmap(64, 64)
                if pm and not pm.isNull():
                    import tempfile
                    tmp = os.path.join(tempfile.gettempdir(), "xzc_tray_icon.png")
                    pm.save(tmp, "PNG")
                    self._icon_path = tmp
            self._free_icon()
            self._update()
        except Exception:
            pass

    def _update(self):
        if not _HAS_WIN32 or not self._visible:
            return
        try:
            nid = self._nid(int(self.window.winId()))
            _SHELL32.Shell_NotifyIconW(_NIM_MODIFY, ctypes.byref(nid))
        except Exception:
            pass

    def _refresh(self):
        # explorer 重启(TaskbarCreated)后系统已清空全部托盘图标；
        # 直接更新 hwnd 并走幂等 show（内部先 DELETE 再 ADD），避免 hide/show 交错产生重影。
        try:
            self._hwnd = int(self.window.winId())
            self._visible = False
            self.show()
        except Exception:
            pass

    def _handle_message(self, msg):
        try:
            code = ctypes.c_ushort(msg.lParam).value
            if code == _WM_LBUTTONUP or code == _WM_LBUTTONDBLCLK:
                self._trace("左键")
                if self.on_activate:
                    # 防抖：双击会先后产生 LBUTTONUP 和 LBUTTONDBLCLK 两条消息，
                    # 400ms内只触发一次，避免重复恢复创建两个截图标签导致重影抖动
                    _now_ts = time.time()
                    if _now_ts - getattr(self, '_last_activate_ts', 0) < 0.4:
                        return
                    self._last_activate_ts = _now_ts
                    # 延迟300ms彻底脱离 Shell_NotifyIcon 消息回调栈：
                    # 在托盘消息回调链中直接操作窗口/菜单是 native 崩溃主因（用户环境点击必崩）
                    QTimer.singleShot(300, self.on_activate)
            elif code == _WM_RBUTTONUP:
                self._trace("右键")
                if self.on_context:
                    # 右键菜单同样延迟：回调栈内弹 QMenu 必崩
                    QTimer.singleShot(300, self.on_context)
        except Exception:
            pass

    def _trace(self, tag):
        # 日志限流：同一秒最多写1条，防止托盘鼠标移动事件风暴把UI线程卡死/日志爆炸
        try:
            _now = int(time.time())
            if getattr(self, '_last_trace_ts', 0) == _now:
                return
            self._last_trace_ts = _now
            with open(os.path.join(app_dir(), "tray_log.txt"), "a", encoding="utf-8") as f:
                f.write(f"{time.strftime('%H:%M:%S')}.{int(time.time()*1000)%1000:03d} 原生托盘 {tag}\n")
        except Exception as _e:
            try:
                with open(os.path.join(app_dir(), "tray_log.txt"), "a", encoding="utf-8") as f:
                    f.write(f"_trace异常: {_e}\n")
            except Exception:
                print(f"_trace严重异常: {_e}")

    def get_icon_rect(self):
        """获取托盘图标在屏幕上的精确矩形(left, top, right, bottom)，失败返回None"""
        try:
            if not _HAS_WIN32 or not self._visible:
                return None
            nid = _NOTIFYICONIDENTIFIER()
            nid.cbSize = ctypes.sizeof(nid)
            nid.hWnd = self._hwnd if self._hwnd else int(self.window.winId())
            nid.uID = self.uID
            rect = wintypes.RECT()
            _r = _SHELL32.Shell_NotifyIconGetRect(ctypes.byref(nid), ctypes.byref(rect))
            if _r == 0:
                return (int(rect.left), int(rect.top), int(rect.right), int(rect.bottom))
            return None
        except Exception:
            return None

    def show_balloon(self, text="我在这里！看见我了吗", title="雪之下倾城"):
        """显示托盘气泡通知（NIF_INFO），3秒后自动关闭气泡"""
        if not _HAS_WIN32:
            return
        if getattr(self, '_balloon_shown', False):
            return
        if not self._visible:
            return
        try:
            self._balloon_shown = True
            nid = self._nid(self._hwnd)  # 完整基础NID（含图标/提示/消息）
            nid.uFlags |= _NIF_INFO
            try:
                nid.szInfo = text[:255]
            except Exception:
                pass
            try:
                nid.szInfoTitle = title[:63]
            except Exception:
                pass
            nid.dwInfoFlags = _NIIF_INFO
            nid.uTimeout = 3000
            _r = _SHELL32.Shell_NotifyIconW(_NIM_MODIFY, ctypes.byref(nid))
            self._trace(f'show_balloon: rc={_r}')
            # 3秒后通过重建托盘图标关闭气泡（Windows气泡无法主动关闭，
            # 删除图标会随之关闭气泡，随即重新添加图标，视觉几乎无感）
            from PySide6.QtCore import QTimer
            QTimer.singleShot(3000, self._close_balloon)
        except Exception as _e:
            self._trace(f'show_balloon异常 {_e}')

    def _close_balloon(self):
        """气泡由 Windows 按 uTimeout(3秒) 自动消失。
        严禁 NIM_DELETE→NIM_ADD 重建图标：explorer 繁忙时删除/添加时序交错会留下幽灵图标(重影)。
        这里只发一次不含 NIF_INFO 的 MODIFY 清掉残留气泡，图标本身保持不变。"""
        try:
            if not self._visible:
                return
            nid = self._nid(self._hwnd)
            _SHELL32.Shell_NotifyIconW(_NIM_MODIFY, ctypes.byref(nid))
        except Exception:
            pass

    def destroy(self):
        try:
            self.hide()
            self._free_icon()
        except Exception:
            pass


class _TrayEventFilter(QAbstractNativeEventFilter):
    def __init__(self, tray):
        super().__init__()
        self.tray = tray
        self._in_filter = False  # 重入保护：防止 nativeEventFilter 无限递归导致栈溢出

    def nativeEventFilter(self, eventType, message):
        if self._in_filter:
            return False, 0
        self._in_filter = True
        try:
            # PySide6中eventType是QByteArray，message是VoidPtr(可int()转地址)
            if not eventType or bytes(eventType) != b'windows_generic_MSG':
                return False, 0
            _ptr = int(message)
            if not _ptr:
                return False, 0
            msg = wintypes.MSG.from_address(_ptr)
            hwnd_now = int(self.tray._hwnd)
            # 注意字段名是 hWnd（大写W），不是hwnd
            if msg.message == self.tray.WM_TRAY:
                # 鼠标移动事件(0x200)不写日志，其余事件也经_trace限流，防止事件风暴卡死UI
                if int(msg.lParam) & 0xFFFF != 0x200:
                    self.tray._trace(f'收到WM_TRAY hwnd={int(msg.hWnd)} 期望={hwnd_now} lParam={int(msg.lParam)&0xFFFF:#x}')
            if msg.message == self.tray.WM_TRAY and int(msg.hWnd) == hwnd_now:
                self.tray._handle_message(msg)
            elif self.tray._taskbar_msg and msg.message == self.tray._taskbar_msg:
                self.tray._refresh()
            elif self.tray._show_msg and msg.message == self.tray._show_msg:
                # 第二实例唤醒消息：延迟恢复主窗口（避免消息回调栈内直接操作窗口崩溃）
                try:
                    from PySide6.QtCore import QTimer as _QT2
                    _QT2.singleShot(120, self.tray.window._show_from_tray)
                except Exception:
                    pass
        except Exception:
            pass
        finally:
            self._in_filter = False
        return False, 0


class ClickableLabel(QLabel):
    """可双击放大的图片标签，自动保持比例不拉伸"""
    def __init__(self, parent=None, on_double_click=None):
        super().__init__(parent)
        self._on_double_click = on_double_click
        self._source_pixmap = None
        self.setCursor(Qt.PointingHandCursor)
        self.setMinimumSize(1, 1)

    def setSourcePixmap(self, pixmap):
        """设置原始图片，自动按比例缩放显示"""
        self._source_pixmap = pixmap
        self._update_display()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._update_display()

    def _update_display(self):
        if self._source_pixmap and not self._source_pixmap.isNull():
            scaled = self._source_pixmap.scaled(
                self.width(), self.height(),
                Qt.KeepAspectRatio, Qt.SmoothTransformation
            )
            super().setPixmap(scaled)

    def mouseDoubleClickEvent(self, event):
        if self._on_double_click:
            self._on_double_click()
        event.accept()


# ==================== 粒子星光系统（最小化消散 / 灵动岛光感 / 控件光感） ====================
class _Star:
    __slots__ = ("x","y","vx","vy","size","color","life","max_life","drag","grav","ray","spin","rot")
    def __init__(self, x, y, vx, vy, size, color, life, drag, grav, ray=False):
        self.x=x; self.y=y; self.vx=vx; self.vy=vy; self.size=size
        self.color=color; self.life=life; self.max_life=life
        self.drag=drag; self.grav=grav; self.ray=ray
        self.spin=0.0; self.rot=0.0


class ParticleOverlay(QWidget):
    """透明粒子覆盖层：作为主窗口子控件，不覆盖桌面。"""
    def __init__(self, duration=900, parent=None, geo=None):
        super().__init__(parent)
        self.setAttribute(Qt.WA_TranslucentBackground)
        self.setAttribute(Qt.WA_ShowWithoutActivating)
        self.setAttribute(Qt.WA_TransparentForMouseEvents)
        if geo is not None:
            self.setGeometry(geo)
        else:
            self.setGeometry(0, 0, parent.width() if parent else 800, parent.height() if parent else 600)
        self.particles = []
        self._elapsed = 0
        self._duration = duration
        self._t = QTimer(self)
        self._t.timeout.connect(self._tick)
        self._fps = 16

    def add_burst(self, rect, count=80, colors=None, spd=9.0, rays=0.45):
        """从 rect 区域向外爆开（最小化消散）。rect:屏幕坐标 QRect。"""
        import random
        colors = colors or ["#fff7d6","#ffd76b","#ff9ecb","#ffffff"]
        cx = rect.center().x(); cy = rect.center().y()
        for i in range(count):
            x = random.uniform(rect.left(), rect.right())
            y = random.uniform(rect.top(), rect.bottom())
            dx = x - cx; dy = y - cy
            d = (dx*dx + dy*dy) ** 0.5 or 1.0
            v = random.uniform(spd*0.4, spd)
            vx = dx/d*v + random.uniform(-1.5,1.5)
            vy = dy/d*v + random.uniform(-1.5,1.5)
            size = random.uniform(2.0, 5.0)
            life = random.uniform(0.55, 1.0)
            self.particles.append(_Star(x,y,vx,vy,size,
                random.choice(colors), life, 0.94, 0.03,
                ray=(random.random() < rays)))

    def add_rise(self, rect, count=24, colors=None, spd=2.2, rays=0.3):
        """从 rect 向上缓慢飘（灵动岛/控件光感）。"""
        import random
        colors = colors or ["#ffd76b","#ff9ecb","#9fdcff","#ffffff"]
        for i in range(count):
            x = random.uniform(rect.left(), rect.right())
            y = random.uniform(rect.top(), rect.bottom())
            vx = random.uniform(-0.6, 0.6)
            vy = -random.uniform(0.5, spd)
            size = random.uniform(1.6, 3.6)
            life = random.uniform(0.7, 1.0)
            self.particles.append(_Star(x,y,vx,vy,size,
                random.choice(colors), life, 0.97, -0.01,
                ray=(random.random() < rays)))

    def start(self):
        self._t.start(self._fps)
        self.show()
        self.raise_()

    def _tick(self):
        self._elapsed += self._fps
        alive = []
        for pt in self.particles:
            pt.x += pt.vx; pt.y += pt.vy
            pt.vx *= pt.drag; pt.vy *= pt.drag
            pt.vy += pt.grav
            pt.rot += pt.spin
            pt.life -= self._fps / (pt.max_life * 1000.0)
            if pt.life > 0:
                alive.append(pt)
        self.particles = alive
        self.update()
        if self._elapsed >= self._duration or not self.particles:
            self._t.stop()
            self.close()
            self.deleteLater()

    def paintEvent(self, e):
        from PySide6.QtGui import QRadialGradient, QPen
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)
        p.setPen(Qt.NoPen)
        # 裁剪到窗口范围，粒子不溢出到桌面
        p.setClipRect(self.rect())
        # 把屏幕坐标转换为窗口内坐标
        _ox, _oy = self.geometry().x(), self.geometry().y()
        for pt in self.particles:
            k = max(0.0, min(1.0, pt.life))
            # 出现/消失淡入淡出
            fade = k if k < 0.7 else 1.0
            c = QColor(pt.color)
            sz = pt.size * (0.35 + 0.65*k)
            r = max(sz*2.6, 2.0)
            a = int(255*fade)
            # 转换为窗口内坐标
            wx = pt.x - _ox
            wy = pt.y - _oy
            # 跳过窗口外的粒子
            if wx < -r or wx > self.width()+r or wy < -r or wy > self.height()+r:
                continue
            grad = QRadialGradient(wx, wy, r)
            c1 = QColor(c); c1.setAlpha(a)
            c2 = QColor(c); c2.setAlpha(0)
            grad.setColorAt(0.0, c1)
            grad.setColorAt(0.45, QColor(c.red(),c.green(),c.blue(),int(a*0.5)))
            grad.setColorAt(1.0, c2)
            p.setBrush(grad)
            p.drawEllipse(QPointF(wx, wy), r, r)
            # 十字星芒
            if pt.ray and k > 0.25:
                pen = QPen(QColor(c.red(),c.green(),c.blue(),int(a*0.8)))
                pen.setWidthF(0.8)
                p.setPen(pen)
                L = r*1.7
                p.drawLine(QPointF(wx-L,wy), QPointF(wx+L,wy))
                p.drawLine(QPointF(wx,wy-L), QPointF(wx,wy+L))
                p.setPen(Qt.NoPen)
        p.end()


class DotWidget(QWidget):
    """自绘小点，支持圆形/方形/三角/菱形/五角星/心形，抗锯齿"""
    def __init__(self, color="#ff0000", size=10, shape="circle", parent=None):
        super().__init__(parent)
        self._color = QColor(color)
        self._size = size
        self._shape = shape
        self.setFixedSize(size, size)
        self.setMinimumSize(size, size)
        self.setMaximumSize(size, size)
        self.setAttribute(Qt.WA_TranslucentBackground)

    def set_color(self, color):
        self._color = QColor(color)
        self.update()

    def set_shape(self, shape):
        self._shape = shape
        self.update()

    def paintEvent(self, event):
        import math
        from PySide6.QtGui import QPolygonF, QPainterPath
        from PySide6.QtCore import QPointF, QRectF
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)
        p.setPen(Qt.NoPen)
        p.setBrush(QBrush(self._color))
        sz = self._size
        sh = self._shape
        if sh == "square":
            p.drawRoundedRect(0, 0, sz - 1, sz - 1, 2, 2)
        elif sh == "triangle":
            tri = QPolygonF([QPointF(sz/2, 1), QPointF(1, sz-1), QPointF(sz-1, sz-1)])
            p.drawPolygon(tri)
        elif sh == "diamond":
            dia = QPolygonF([QPointF(sz/2, 0), QPointF(sz-1, sz/2),
                            QPointF(sz/2, sz-1), QPointF(0, sz/2)])
            p.drawPolygon(dia)
        elif sh == "star":
            poly = QPolygonF()
            cx, cy = sz/2, sz/2
            ro = sz/2 - 0.5
            ri = ro * 0.42
            for i in range(10):
                ang = -math.pi/2 + i * math.pi/5
                r = ro if i % 2 == 0 else ri
                poly.append(QPointF(cx + r*math.cos(ang), cy + r*math.sin(ang)))
            p.drawPolygon(poly)
        elif sh == "heart":
            k = sz / 10.0
            path = QPainterPath()
            path.moveTo(5*k, 9.2*k)
            path.cubicTo(0*k, 5.2*k, 0*k, 2.2*k, 2.5*k, 1.2*k)
            path.cubicTo(4*k, 0.5*k, 5*k, 2*k, 5*k, 3*k)
            path.cubicTo(5*k, 2*k, 6*k, 0.5*k, 7.5*k, 1.2*k)
            path.cubicTo(10*k, 2.2*k, 10*k, 5.2*k, 5*k, 9.2*k)
            p.drawPath(path)
        else:
            p.drawEllipse(0, 0, sz - 1, sz - 1)
        p.end()


class BalloonPanel(QFrame):
    """灵动岛背景面板：支持胶囊/圆角矩形/直角矩形/气泡四种形状，自绘抗锯齿"""
    def __init__(self, shape="capsule", parent=None):
        super().__init__(parent)
        self._panel_shape = shape
        self.setObjectName('balloonRoot')
        self.setAttribute(Qt.WA_TranslucentBackground)

    def set_panel_shape(self, shape):
        self._panel_shape = shape
        self.update()

    def paintEvent(self, event):
        try:
            from PySide6.QtGui import QPolygonF, QPainterPath
            from PySide6.QtCore import QPointF, QRectF
            p = QPainter(self)
            p.setRenderHint(QPainter.Antialiasing)
            r = self.rect()
            p.setBrush(QColor(0, 0, 0, 245))
            p.setPen(QPen(QColor(255, 255, 255, 80), 1))
            shp = self._panel_shape
            if shp == "square":
                p.drawRect(r.adjusted(0, 0, -1, -1))
            elif shp == "rounded":
                p.drawRoundedRect(r.adjusted(0, 0, -1, -1), 12, 12)
            elif shp == "bubble":
                th = 8
                tw = 16
                body = QRectF(r.x(), r.y(), r.width() - 1, r.height() - th)
                path = QPainterPath()
                path.addRoundedRect(body, 12, 12)
                cx = r.width() / 2.0
                tri = QPolygonF([
                    QPointF(cx - tw / 2.0, r.height() - th),
                    QPointF(cx + tw / 2.0, r.height() - th),
                    QPointF(cx, r.height() - 1),
                ])
                path.addPolygon(tri)
                p.drawPath(path)
            else:  # capsule 默认
                radius = min(r.height() / 2.0, 25.0)
                p.drawRoundedRect(r.adjusted(0, 0, -1, -1), radius, radius)
            p.end()
        except Exception:
            pass


class BalloonWidget(QWidget):
    """特效灵动岛提示：屏幕顶部中央胶囊，淡入停留后慢慢变小、再慢慢消失"""

    def __init__(self, parent=None):
        from PySide6.QtCore import QPropertyAnimation, QTimer, QEasingCurve
        super().__init__(parent, Qt.FramelessWindowHint | Qt.WindowStaysOnTopHint | Qt.Tool)
        self.setAttribute(Qt.WA_TranslucentBackground)
        self.setAttribute(Qt.WA_ShowWithoutActivating)
        self._build()
        self._timer = QTimer(self)
        self._timer.setSingleShot(True)
        self._timer.timeout.connect(self._fade_out)
        self._anim = QPropertyAnimation(self, b'windowOpacity', self)
        self._anim.setDuration(260)
        self._anim.setEasingCurve(QEasingCurve.InOutCubic)

    def _build(self):
        # 读取用户设置的气泡文字、颜色与字体大小（灵动岛沿用这些设置）
        try:
            _cfg = Config().data
            _text = str(_cfg.get("balloon_text", "我在这里！看见我了吗"))
            _color = str(_cfg.get("balloon_color", "#ff0000"))
            _shape = str(_cfg.get("balloon_shape", "circle"))
            _panel_shape = str(_cfg.get("balloon_panel_shape", "capsule"))
            _fs = int(_cfg.get("balloon_font_size", 14))
        except Exception:
            _text = "我在这里！看见我了吗"
            _color = "#ff33aa"
            _panel_shape = "capsule"
            _fs = 14
        self._balloon_color = _color
        self._balloon_shape = _shape
        self._balloon_panel_shape = _panel_shape
        self._balloon_font = _fs
        root = BalloonPanel(_panel_shape, self)
        # 背景由 BalloonPanel.paintEvent 自绘（支持胶囊/圆角/直角/气泡），这里只设文字样式
        root.setStyleSheet(f'''
            #balloonRoot{{background:transparent;border:none;}}
            #balloonText{{color:#ffffff;font-size:{_fs}px;font-weight:bold;background:transparent;padding:0 6px;}}
        ''')
        lay = QHBoxLayout(root)
        if self._balloon_panel_shape == "bubble":
            lay.setContentsMargins(12, 5, 12, 12)
        else:
            lay.setContentsMargins(12, 5, 12, 5)
        lay.setSpacing(8)
        icon = QLabel(root)
        icon.setObjectName('balloonIcon')
        self._icon = icon
        icon.setFixedSize(32, 32)
        icon.setMinimumSize(32, 32)
        icon.setMaximumSize(32, 32)
        icon.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
        icon.setScaledContents(False)
        icon.setAlignment(Qt.AlignCenter)
        icon.setText('🎮')
        icon.setStyleSheet('font-size:18px;background:transparent;color:#ffffff;')
        try:
            _island_icon = str(Config().data.get("island_icon", ""))
            _p = None
            if _island_icon and os.path.exists(_island_icon):
                _p = QPixmap(_island_icon)
            if _p is None or _p.isNull():
                _icon_path = resource_path('app_icon.ico')
                if _icon_path:
                    _p = QPixmap(_icon_path)
            if _p and not _p.isNull():
                _scaled = _p.scaled(26, 26, Qt.KeepAspectRatio, Qt.SmoothTransformation)
                icon.setPixmap(_scaled)
                icon.setStyleSheet('background:transparent;')
        except Exception as e:
            print(f"[灵动岛图标] {e}")
        lay.addWidget(icon, 0, Qt.AlignVCenter)
        txt = QLabel(_text, root)
        txt.setObjectName('balloonText')
        txt.setMinimumWidth(0)  # 文字自动扩展宽度
        txt.setAlignment(Qt.AlignVCenter | Qt.AlignLeft)
        self._txt = txt
        lay.addWidget(txt, 0, Qt.AlignVCenter)
        dot = DotWidget(_color, 10, _shape, root)
        self._dot = dot
        dot.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
        lay.addWidget(dot, 0, Qt.AlignVCenter)
        self._root = root
        # 沉浸光感：胶囊外柔和彩色光晕
        try:
            _glow = QGraphicsDropShadowEffect(root)
            _glow.setOffset(0, 0)
            _glow.setBlurRadius(32)
            _glow.setColor(QColor(255, 120, 200, 190))
            root.setGraphicsEffect(_glow)
            self._panel_glow = _glow
        except Exception:
            pass
        self._inner = QVBoxLayout(self)
        self._inner.setContentsMargins(0, 0, 0, 0)
        self._inner.addWidget(root)

    def set_text(self, text):
        """动态修改灵动岛显示的文字"""
        try:
            if hasattr(self, '_txt') and self._txt:
                self._txt.setText(str(text))
                self._txt.setMinimumWidth(0)
                self._txt.setMaximumWidth(16777215)
                self._txt.adjustSize()
                self.adjustSize()
        except Exception:
            pass

    def show_balloon(self, anchor=None):
        try:
            scr = QApplication.primaryScreen().availableGeometry()
            # 确保文字标签有足够宽度，不被截断
            if hasattr(self, '_txt') and self._txt:
                self._txt.setMinimumWidth(0)
                self._txt.setMaximumWidth(16777215)
                self._txt.adjustSize()
                # 计算文字实际需要的宽度
                _text_w = self._txt.sizeHint().width()
                _text_h = self._txt.sizeHint().height()
            else:
                _text_w = 200
                _text_h = 20
            self.adjustSize()
            # 灵动岛总宽度 = 图标(26) + 间距(10) + 文字宽度 + 间距(10) + 圆点(8) + 左右边距(28) + 额外余量(20)
            w = 32 + 10 + _text_w + 10 + 8 + 28 + 20
            w = max(w, 200)  # 最小宽度200
            w = min(w, int(scr.width() * 0.8))  # 最大不超过屏幕宽度的80%
            h = 50  # 固定高度50，容纳更大图标和字体
            self.resize(w, h)
            # 特效灵动岛：屏幕顶部水平居中
            x = scr.left() + (scr.width() - w) // 2
            y = scr.top() + 12
            self.move(int(x), int(y))
            # 淡入
            self.setWindowOpacity(0.0)
            self.show()
            self.raise_()
            # 粒子沉浸光感已禁用（避免粒子显示在桌面）
            self._island_ov = None
            self._anim.stop()
            self._anim.setDuration(260)
            self._anim.setStartValue(0.0)
            self._anim.setEndValue(1.0)
            try:
                self._anim.finished.disconnect()
            except Exception:
                pass
            self._anim.start()
            # 停留后开始缩放消失
            self._timer.start(2600)
        except Exception:
            pass

    def mousePressEvent(self, e):
        """鼠标点击灵动岛立即消失"""
        try:
            self._timer.stop()
            self._fade_out()
        except Exception:
            pass

    def _fade_out(self):
        """特效消失：用截图缩放方式，先慢慢变小，再慢慢淡出隐没（图标不变形）"""
        try:
            from PySide6.QtCore import (QSequentialAnimationGroup, QParallelAnimationGroup,
                                        QPropertyAnimation, QEasingCurve, QRect, Qt, QTimer)
            from PySide6.QtGui import QPixmap
            from PySide6.QtWidgets import QLabel, QWidget
            # 截取当前窗口截图（包含完整图标和文字，不会变形）
            _geo = self.geometry()
            _screenshot = self.grab()
            # 创建一个独立的截图显示窗口
            _shot_win = QWidget(None, Qt.FramelessWindowHint | Qt.WindowStaysOnTopHint | Qt.Tool)
            _shot_win.setAttribute(Qt.WA_TranslucentBackground)
            _shot_lbl = QLabel(_shot_win)
            _shot_lbl.setPixmap(_screenshot)
            _shot_lbl.setScaledContents(True)
            _shot_lbl.setGeometry(0, 0, _geo.width(), _geo.height())
            _shot_win.setGeometry(_geo)
            _shot_win.show()
            # 隐藏原窗口
            self.hide()
            # 截图窗口缩小动画
            _cx = _geo.center().x()
            _top = _geo.top()
            _small = QRect(_cx - 40, _top + 10, 80, 32)
            _tiny = QRect(_cx - 10, _top + 22, 20, 8)
            a1 = QPropertyAnimation(_shot_win, b'geometry', _shot_win)
            a1.setDuration(500)
            a1.setStartValue(_geo)
            a1.setEndValue(_small)
            a1.setEasingCurve(QEasingCurve.InOutCubic)
            a2 = QPropertyAnimation(_shot_win, b'geometry', _shot_win)
            a2.setDuration(800)
            a2.setStartValue(_small)
            a2.setEndValue(_tiny)
            a2.setEasingCurve(QEasingCurve.InCubic)
            a3 = QPropertyAnimation(_shot_win, b'windowOpacity', _shot_win)
            a3.setDuration(800)
            a3.setStartValue(1.0)
            a3.setEndValue(0.0)
            _p = QParallelAnimationGroup(_shot_win)
            _p.addAnimation(a2)
            _p.addAnimation(a3)
            _seq = QSequentialAnimationGroup(_shot_win)
            _seq.addAnimation(a1)
            _seq.addAnimation(_p)
            def _on_finished():
                try:
                    _shot_win.close()
                except Exception:
                    pass
                self.close()
            _seq.finished.connect(_on_finished)
            _seq.start()
            self._anim_group = _seq
        except Exception:
            self.close()

class GameMenu(QMainWindow):
    # 跨线程信号：远程数据就绪(str公告, str最新版本)、发现更新(str版本, str下载, str公告, str日期)
    remote_data_ready = Signal(str, str)
    weather_ready = Signal(object)
    update_available = Signal(str, str, str, str, str, str, str)
    def __init__(self):
        super().__init__()
        self.cfg = Config()
        self.icon_widgets = {}  # (cat, iid) -> IconItem
        self.current_title = self.cfg.data.get("app_title", APP_TITLE)
        self.current_icon_path = self.cfg.data.get("app_icon")
        # 加载保存的图标大小
        saved_size = self.cfg.data.get("icon_size", "medium")
        if saved_size in ICON_SIZES:
            global ICON_W, ICON_H, ICON_PX
            ICON_PX = ICON_SIZES[saved_size]["px"]
            ICON_W = ICON_SIZES[saved_size]["w"]
            ICON_H = ICON_SIZES[saved_size]["h"]
        self._apply_app_icon()
        # 连接跨线程信号（后台获取公告/更新 → 主线程更新UI）
        self.remote_data_ready.connect(self._apply_remote_data)
        self.weather_ready.connect(self._apply_weather)
        self.update_available.connect(self._show_auto_update_dialog)
        self._build_ui()
        self._load_items()
        self._apply_background()
        # 应用保存的主题（如果保存的主题不存在，自动切换为默认主题）
        saved_theme = self.cfg.data.get("theme", DEFAULT_THEME)
        if saved_theme not in THEMES:
            saved_theme = DEFAULT_THEME
            self.cfg.data["theme"] = DEFAULT_THEME
            self.cfg.save()
        self._apply_theme(saved_theme)
        # 应用保存的鼠标指针颜色
        saved_cursor = self.cfg.data.get("cursor_color", "default")
        saved_cursor_img = self.cfg.data.get("cursor_image")
        if saved_cursor_img:
            # create_image_cursor 函数会自动处理相对路径和绝对路径
            cursor = create_image_cursor(saved_cursor_img)
            # 检查是否成功创建了自定义指针（通过检查指针形状）
            self.setCursor(cursor)
            self._apply_cursor_to_all(self, cursor)
            if os.path.exists(saved_cursor_img) or os.path.exists(os.path.join(app_dir(), saved_cursor_img)):
                self._set_status(f"✓ 已加载自定义鼠标指针: {os.path.basename(saved_cursor_img)}")
            else:
                print(f"[load cursor] 鼠标指针图片不存在: {saved_cursor_img}")
        elif saved_cursor != "default":
            cursor = create_colored_cursor(saved_cursor)
            self.setCursor(cursor)
            self._apply_cursor_to_all(self, cursor)
        # 应用保存的漂浮特效
        saved_fx = self.cfg.data.get("floating_effect", True)
        saved_fx_type = self.cfg.data.get("floating_type", "fire")
        if saved_fx and hasattr(self, 'bg') and self.bg:
            self.bg.set_floating_effect(True, saved_fx_type)
        # 粒子保险丝：每5秒确保粒子系统运行（降低频率省资源）
        self._fx_guard_timer = QTimer(self)
        self._fx_guard_timer.timeout.connect(self._ensure_particles)
        self._fx_guard_timer.start(5000)
        self._start_clock()
        # 标题栏光感粒子：降低频率到8秒一次
        self._ambient_timer = QTimer(self)
        self._ambient_timer.timeout.connect(self._ambient_particles)
        self._ambient_timer.start(8000)
        QTimer.singleShot(1000, self._ambient_particles)
        # 托盘延迟初始化：窗口显示后2秒再添加托盘图标（hWnd完全有效+explorer托盘服务就绪，
        # 大幅提高 NIM_ADD 成功率；刚开机/explorer重启场景尤其关键）
        QTimer.singleShot(2000, self._setup_tray)
        # 窗口居中显示，确保底部设置按钮可见
        QTimer.singleShot(100, self._center_window)
        # 首次启动欢迎
        if self.cfg.data.get("first_run", True):
            self._show_welcome()
            self.cfg.mark_first_run_done()
        # 启动3秒后自动获取公告+检查更新（不阻塞启动，无按钮检测）
        QTimer.singleShot(3000, self._fetch_notice_and_check_update)
        # 启动滚动公告（先显示本地公告，网页公告获取后替换）
        QTimer.singleShot(500, self._start_notice_scroll)

    def _auto_check_update(self):
        """启动时自动检查更新（后台线程，不阻塞UI）"""
        self._fetch_notice_and_check_update()

    def _show_auto_update_dialog(self, latest_version, download_url, download_url2, download_password, notice, release_date, update_content):
        """显示自动更新对话框（在主线程调用）"""
        dlg = UpdateDialog(True, latest_version, download_url, notice, release_date, update_content, download_url2, download_password, self)
        dlg.exec()

    # ----------------------------------------------------------
    def _build_ui(self):
        self.setWindowTitle(self.current_title)
        # 加载保存的分辨率
        global APP_W, APP_H
        saved_res = self.cfg.data.get("resolution", DEFAULT_RESOLUTION)
        if saved_res in RESOLUTIONS:
            APP_W, APP_H = RESOLUTIONS[saved_res]
        # 窗口固定分辨率，禁用最大化，鼠标不能拉伸窗口
        # 窗口不置顶，其他软件可以覆盖在游戏菜单上面
        self.setWindowFlags(Qt.Window | Qt.WindowMinimizeButtonHint | Qt.WindowCloseButtonHint)
        self.setFixedSize(APP_W, APP_H)
        self.setAcceptDrops(True)

        # 中心背景（如果保存的主题不存在，自动切换为默认主题）
        saved_theme = self.cfg.data.get("theme", DEFAULT_THEME)
        if saved_theme not in THEMES:
            saved_theme = DEFAULT_THEME
        self.bg = BackgroundWidget(self, theme_key=saved_theme)
        self.bg.setAcceptDrops(True)  # 背景控件也接受拖放，确保事件能传递到root
        self.setCentralWidget(self.bg)
        # 注意: 不在此安装bg的事件过滤器, 避免root/fx未创建时处理resize事件导致崩溃
        # 大小同步由GameMenu.resizeEvent和QTimer.singleShot延迟处理

        # 顶层布局容器 (随窗口大小自适应) - 在root上接收拖放事件
        self.root = QWidget(self.bg)
        self.root.setGeometry(0, 0, self.bg.width(), self.bg.height())
        self.root.setAcceptDrops(True)
        self.root.installEventFilter(self)
        root_lay = QVBoxLayout(self.root)
        root_lay.setContentsMargins(20, 16, 20, 16)
        root_lay.setSpacing(12)

        # ---- 标题栏 ----
        title_bar = QFrame()
        title_bar.setFixedHeight(64)
        title_bar.setStyleSheet("""
            QFrame { background:rgba(255,51,170,12); border:1px solid rgba(255,51,170,70);
                     border-radius:10px; }
        """)
        tb_lay = QHBoxLayout(title_bar)
        tb_lay.setContentsMargins(24, 0, 24, 0)

        self.title_lbl = QLabel(self.current_title)
        self.title_lbl.setStyleSheet("""
            color:rgba(255,51,170,255); font-size:30px; font-weight:bold;
            font-family:'Consolas','Microsoft YaHei';
            letter-spacing:4px;
        """)
        # 标题特效：流光文字（粉→金→白循环）+ 发光颜色同步、强度呼吸
        self._title_glow = QGraphicsDropShadowEffect()
        self._title_glow.setBlurRadius(20)
        self._title_glow.setColor(QColor(255, 51, 170))
        self._title_glow.setOffset(0, 0)
        self.title_lbl.setGraphicsEffect(self._title_glow)
        self._start_title_shimmer()

        title_left = QVBoxLayout()
        title_left.setSpacing(2)
        title_left.addWidget(self.title_lbl)

        tb_lay.addLayout(title_left)
        tb_lay.addStretch(1)

        # 版本信息（标题栏正中间：当前版本 + 最新版本，金色圆角标签样式）
        self.version_info_lbl = QLabel(f"当前版本{format_version(APP_VERSION)}  最新版本：--")
        self.version_info_lbl.setAlignment(Qt.AlignCenter)
        self.version_info_lbl.setStyleSheet("""
            color:#ffd700; font-size:13px; font-weight:bold;
            font-family:'Consolas','Microsoft YaHei';
            background:rgba(255,215,0,25); border:1px solid rgba(255,215,0,130);
            border-radius:8px; padding:4px 14px;
        """)
        self.version_info_lbl.setMinimumHeight(26)
        tb_lay.addWidget(self.version_info_lbl, 1)

        tb_lay.addStretch(1)

        # 北京时间移到右边
        self.time_lbl = QLabel()
        self.time_lbl.setAlignment(Qt.AlignRight | Qt.AlignVCenter)
        self.time_lbl.setStyleSheet("""
            color:#ff77c0; font-size:15px; font-weight:bold; font-family:'Consolas','Microsoft YaHei';
            background:rgba(255,51,170,25); border:1px solid rgba(255,51,170,150);
            border-radius:11px; padding:4px 16px;
        """)
