    def _on_search_engine_changed(self, text):
        """搜索引擎切换：保存到配置，重启后保留选择"""
        try:
            self.cfg.data["search_engine"] = text
            self.cfg.save()
        except Exception:
            pass
        try:
            self._show_island(f"搜索引擎切换为：{text}")
        except Exception:
            pass

    def _on_history_picked(self, idx):
        """从历史记录选择时直接搜索"""
        try:
            self._do_search()
        except Exception:
            pass

    def _delete_current_history(self):
        """删除当前选中的搜索记录（不是清空全部）"""
        current = self.search_edit.currentText().strip()
        if not current:
            self._show_island("请先选择要删除的搜索记录")
            return
        history = self.cfg.data.get("search_history", [])
        if current in history:
            history.remove(current)
            self.cfg.data["search_history"] = history
            self.cfg.save()
            # 刷新下拉列表
            self.search_edit.clear()
            self.search_edit.addItems(history)
            self.search_edit.lineEdit().setText("")
            self._show_island(f"已删除记录：{current}")
        else:
            self._show_island("记录不存在")

    def _do_search(self):
        """搜索：根据选择的引擎打开浏览器搜索，支持网址直接访问，保存历史记录"""
        keyword = self.search_edit.currentText().strip()
        if not keyword:
            self._show_island("请输入搜索内容后再搜索")
            return
        # 保存搜索历史（最多20条）
        history = self.cfg.data.get("search_history", [])
        if keyword not in history:
            history.insert(0, keyword)
            self.cfg.data["search_history"] = history[:20]
            self.cfg.save()
            # 刷新下拉列表
            self.search_edit.clear()
            self.search_edit.addItems(history)
        # 灵动岛显示搜索内容
        self._show_island(f"正在搜索：{keyword}")
        # 识别网址：如果输入的是URL，直接打开
        if keyword.startswith(("http://", "https://")) or (
            "." in keyword and " " not in keyword and not keyword.endswith(("。", "，"))
        ):
            url = keyword if keyword.startswith(("http://", "https://")) else "https://" + keyword
        else:
            engine = self.search_engine.currentText()
            if engine == "百度":
                url = f"https://www.baidu.com/s?wd={keyword}"
            else:
                url = f"https://cn.bing.com/search?q={keyword}"
        import webbrowser
        webbrowser.open(url)
        # 清空输入框
        self.search_edit.setCurrentText("")

    def _sync_root_geometry(self):
        """同步root的大小为bg的大小"""
        try:
            if hasattr(self, 'root') and hasattr(self, 'bg'):
                w, h = self.bg.width(), self.bg.height()
                if w > 0 and h > 0:
                    self.root.setGeometry(0, 0, w, h)
        except Exception as e:
            print(f"[_sync_root_geometry error] {e}")

    def _btn_style(self):
        return """
            QPushButton { background:rgba(0,40,10,220); color:#ff33aa; border:1px solid #ff33aa;
                          border-radius:6px; padding:6px 14px; font-family:'Consolas','Microsoft YaHei';
                          font-size:13px; font-weight:bold; }
            QPushButton:hover { background:rgba(0,80,20,240); border:2px solid #ff33aa; }
            QPushButton:pressed { background:rgba(0,120,30,255); }
        """

    # ----------------------------------------------------------
    # 背景
    def _apply_background(self):
        self.bg.set_background(self.cfg.data.get("background"))

    # ----------------------------------------------------------
    # 加载 / 创建图标
    def _load_items(self):
        """加载所有图标，单个失败不影响其他"""
        total = 0
        failed = 0
        for cat in CATEGORIES:
            items = self.cfg.items(cat)
            cat_count = 0
            for d in items:
                try:
                    # 数据校验：确保必要字段存在
                    if not d.get("id"):
                        print(f"[跳过] {cat} - 缺少id: {d}")
                        failed += 1
                        continue
                    if not d.get("path"):
                        print(f"[跳过] {cat} - {d.get('name', '未知')} 缺少path")
                        failed += 1
                        continue
                    if not d.get("name"):
                        d["name"] = display_name(d["path"])
                    self._create_icon(cat, d)
                    total += 1
                    cat_count += 1
                except Exception as e:
                    failed += 1
                    print(f"[加载图标失败] {cat} - {d.get('name', '未知')}: {e}")
                    import traceback
                    traceback.print_exc()
            print(f"[图标加载] {cat}: 配置{len(items)}个, 成功{cat_count}个")
        print(f"[图标加载] 总计: 成功 {total} 个, 失败 {failed} 个")
        # 加载完成后，强制重新排列所有图标（确保所有图标都可见）
        self._rearrange_all_icons()
        # 更新所有分类数量显示
        self._update_all_category_counts()
        # 自动清理重复图标（相同路径或相同名字）
        self._deduplicate_icons()
        # 关键：所有子控件启用 acceptDrops 并安装事件过滤器，拖到任何位置都能添加
        # 注意：跳过 WA_TransparentForMouseEvents 的透明层（粒子层），否则它会吞掉拖放事件
        try:
            from PySide6.QtWidgets import QWidget as _QW
            _cnt = 0
            for _w in self.findChildren(_QW):
                if _w.testAttribute(Qt.WA_TransparentForMouseEvents):
                    _w.setAcceptDrops(False)
                    continue
                _w.setAcceptDrops(True)
                _w.installEventFilter(self)
                _cnt += 1
            try:
                with open(os.path.join(app_dir(), "drop_debug.log"), "a", encoding="utf-8") as _df:
                    _df.write(f"[{time.strftime('%H:%M:%S')}] _load_items 设置 {_cnt} 个控件 acceptDrops（已跳过透明层）\n")
            except Exception:
                pass
        except Exception:
            pass
        # 加载完成后动态调整容器高度，并在布局稳定后再调整一次
        QTimer.singleShot(50, self._adjust_all_container_heights)
        QTimer.singleShot(300, self._adjust_all_container_heights)

    def _adjust_all_container_heights(self):
        """根据各分类图标数量动态调整容器高度，无限制可以放更多图标。"""
        try:
            grid_w, grid_h = get_grid_size()
            margin = 8
            # 根据图标大小决定每行数量：大9 / 中12 / 小10
            size_key = self.cfg.data.get("icon_size", "medium")
            per_row_map = {"large": 9, "medium": 12, "small": 10}
            per_row = per_row_map.get(size_key, 12)
            for cat in CATEGORIES:
                area = self.areas[cat]
                container = area.container
                if getattr(area, "_collapsed", False):
                    # 折叠：固定标题高度
                    area.setMinimumHeight(36)
                    area.setMaximumHeight(36)
                    continue
                n = len(self.cfg.items(cat))
                # 根据图标数量计算行数，无限制
                rows = max(1, (n + per_row - 1) // per_row)
                needed_h = rows * grid_h + margin * 2
                # 同时检查实际图标位置：若有图标落在更靠下的位置，容器也要容纳
                for (c, iid), w in self.icon_widgets.items():
                    if c == cat and w.isVisible():
                        bottom = w.y() + w.height() + margin
                        if bottom > needed_h:
                            needed_h = bottom
                container.setMinimumHeight(needed_h)
                container.setMaximumHeight(16777215)
                area.setMinimumHeight(36 + needed_h)
                area.setMaximumHeight(16777215)
        except Exception as e:
            print(f"[_adjust_all_container_heights] {e}")

    def _create_icon(self, cat, item_data):
        area = self.areas[cat]
        # 数据校验：补全缺失字段
        if "id" not in item_data:
            import uuid
            item_data["id"] = str(uuid.uuid4())[:8]
        if "name" not in item_data or not item_data["name"]:
            item_data["name"] = display_name(item_data.get("path", "未知"))
        if "x" not in item_data:
            item_data["x"] = 20
        if "y" not in item_data:
            item_data["y"] = 20
        w = IconItem(item_data, cat, area.container)
        w.open_app.connect(lambda p, _n=item_data.get("name", ""): self._on_open_app(p, _n))
        w.run_as_admin.connect(lambda p, _n=item_data.get("name", ""): self._on_run_as_admin(p, _n))
        w.open_folder.connect(open_in_folder)
        w.remove_me.connect(self._remove_icon)
        w.rename_me.connect(self._on_rename_icon)
        w.change_icon.connect(self._on_change_icon)
        w.position_changed.connect(self._on_icon_position_changed)
        # 对齐到网格 + 宽度约束 + 碰撞检测，确保图标不越界、不重叠
        grid_w, grid_h = get_grid_size()
        margin = 8
        raw_x = item_data.get("x", 20)
        raw_y = item_data.get("y", 20)
        aligned_x = margin + int(round((raw_x - margin) / grid_w)) * grid_w
        aligned_y = margin + int(round((raw_y - margin) / grid_h)) * grid_h
        # 宽度用稳定宽度约束（容器未布局时也正确）；高度不设上界——
        # 新图标允许排到容器当前高度之外，随后 _adjust_all_container_heights 会扩展容器
        _cw = self._stable_container_width(cat)
        aligned_x = max(margin, min(aligned_x, _cw - w.width() - margin))
        aligned_y = max(margin, aligned_y)
        # 碰撞检测：网格螺旋搜索空位（只约束宽度，高度向下无限扩展）
        def _check_overlap(px, py):
            for (c, iid), other_w in self.icon_widgets.items():
                if c == cat and other_w is not w:
                    if (px < other_w.x() + other_w.width() and px + w.width() > other_w.x() and
                        py < other_w.y() + other_w.height() and py + w.height() > other_w.y()):
                        return True
            return False
        if _check_overlap(aligned_x, aligned_y):
            found = False
            for radius in range(1, 60):
                for dx in range(-radius, radius + 1):
                    for dy in range(0, radius + 1):  # 只向下/左右找空位，不向上遮挡
                        if abs(dx) != radius and dy != radius:
                            continue
                        nx = aligned_x + dx * grid_w
                        ny = aligned_y + dy * grid_h
                        nx = max(margin, min(nx, _cw - w.width() - margin))
                        ny = max(margin, ny)
                        if not _check_overlap(nx, ny):
                            aligned_x, aligned_y = nx, ny
                            found = True
                            break
                    if found:
                        break
                if found:
                    break
        w.move(aligned_x, aligned_y)
        # 保存对齐后的位置
        item_data["x"] = aligned_x
        item_data["y"] = aligned_y
        w.show()
        self.icon_widgets[(cat, item_data["id"])] = w
        # 更新分类数量显示
        self._update_all_category_counts()
        return w

    def _remove_icon(self, cat, iid):
        w = self.icon_widgets.pop((cat, iid), None)
        if w:
            w.setParent(None)
            w.deleteLater()
        self.cfg.remove_item(cat, iid)
        # 更新分类数量显示
        self._update_all_category_counts()
        QTimer.singleShot(0, self._adjust_all_container_heights)
        self._set_status(f"已移除 [{self.cfg.cat_name(cat)}] 中的图标")

    def _on_icon_position_changed(self, cat, iid, x, y):
        """图标位置变化，保存到配置（对齐到网格）"""
        grid_w, grid_h = get_grid_size()
        margin = 8
        aligned_x = margin + int(round((x - margin) / grid_w)) * grid_w
        aligned_y = margin + int(round((y - margin) / grid_h)) * grid_h
        self.cfg.move_item(cat, iid, aligned_x, aligned_y)

    def _deduplicate_icons(self):
        """启动时自动检测重复图标：同分类下相同路径或相同名字的，保留第一个，删除其余，自动保存"""
        try:
            removed = 0
            for cat in CATEGORIES:
                seen_paths = {}
                seen_names = {}
                items = self.cfg.items(cat)
                to_remove = []
                for item in items:
                    iid = item.get("id", "")
                    path = item.get("path", "").strip().lower()
                    name = item.get("name", "").strip()
                    # 路径重复
                    if path and path in seen_paths:
                        to_remove.append(iid)
                        removed += 1
                        continue
                    if path:
                        seen_paths[path] = iid
                    # 名字重复
                    if name and name in seen_names:
                        to_remove.append(iid)
                        removed += 1
                        continue
                    if name:
                        seen_names[name] = iid
                # 删除重复项
                for rid in to_remove:
                    w = self.icon_widgets.pop((cat, rid), None)
                    if w:
                        w.setParent(None)
                        w.deleteLater()
                    self.cfg.remove_item(cat, rid)
            if removed > 0:
                self.cfg.save()
                self._update_all_category_counts()
                QTimer.singleShot(800, lambda: self._show_island(f"已自动清理 {removed} 个重复图标"))
                print(f"[去重] 自动删除 {removed} 个重复图标")
        except Exception as e:
            print(f"[去重] 失败: {e}")

    def _on_open_app(self, path, name=""):
        """双击/右键打开软件：灵动岛提示 + 启动软件"""
        if not name:
            try:
                name = display_name(path)
            except Exception:
                name = "软件"
        try:
            self._show_island(f"正在启动：{name}")
        except Exception:
            pass
        ok = False
        try:
            ok = open_file(path)
        except Exception:
            ok = False
        if ok:
            try:
                self._set_status(f"▶ 已启动：{name}")
            except Exception:
                pass
        else:
            try:
                self._show_island(f"启动失败：{name}")
            except Exception:
                pass
        return ok

