    def _on_rename_icon(self, cat, iid):
        """图标重命名后保存配置 (IconItem已弹对话框并更新显示)"""
        w = self.icon_widgets.get((cat, iid))
        if not w:
            return
        new_name = w.d.get("name", "")
        if new_name:
            self.cfg.rename_item(cat, iid, new_name)
            self._set_status(f"已重命名为: {new_name}")
            self._show_island(f"已重命名为：{new_name}")

    def _on_change_icon(self, cat, iid):
        """右键更换图标"""
        w = self.icon_widgets.get((cat, iid))
        if not w:
            return
        path, _ = QFileDialog.getOpenFileName(
            self, "选择图标图片", "", "图片文件 (*.png *.jpg *.jpeg *.bmp *.ico *.webp);;所有文件 (*.*)"
        )
        if path:
            # 复制到 assets 目录
            import shutil
            fname = f"icon_{iid}_{os.path.basename(path)}"
            dst = os.path.join(self.cfg.assets, fname)
            shutil.copy2(path, dst)
            # 更新配置和显示
            self.cfg.set_item_icon(cat, iid, dst)
            w.d["icon_path"] = dst
            w._apply_icon()
            self._set_status(f"图标已更换: {os.path.basename(path)}")

    # ----------------------------------------------------------
    # 拖放处理
    def _on_file_dropped(self, cat, path, pos):
        self._add_item_with_icon(cat, path)

    def _add_item_with_icon(self, cat, path, custom_name=None):
        """通用添加方法: 解析.lnk, 提取保存图标, 网格排列, 自动保存"""
        # 解析 .lnk 快捷方式 -> 目标 exe 真实路径（先解析，名称/图标都用真实目标）
        try:
            real_path = resolve_shortcut(path)
        except Exception:
            real_path = path
        # 名称: 优先自定义, 其次用 .lnk 文件本身的名字（如果是拖放快捷方式）
        if custom_name:
            item_name = custom_name
        elif path.lower().endswith('.lnk'):
            # 拖放快捷方式时，用快捷方式本身的名字
            item_name = display_name(path)
        else:
            item_name = display_name(real_path)
        # 前置去重：归一化真实路径，检查是否已在任何分类中。
        # 用解析后的真实路径比较，所以同一 exe 的多个快捷方式也能识别为重复。
        try:
            _np = os.path.normpath(real_path).lower()
            for _ec in CATEGORIES:
                _exists = False
                for _ei in self.cfg.items(_ec):
                    if os.path.normpath(_ei.get("path", "")).lower() == _np:
                        _exists = True
                        break
                if _exists:
                    self._show_island(f"软件「{item_name}」已在菜单中，无需重复添加")
                    self._set_status(f"已存在，跳过添加: {item_name}")
                    return None
        except Exception:
            pass
        # 灵动岛提示：只显示软件名，不带 .lnk/.exe 后缀
        self._show_island(f"已添加软件：{item_name}")
        try:
            x, y = self._next_grid_pos(cat)
        except Exception:
            x, y = 10, 10
        # 提取并保存图标到本地 (失败也不影响创建)
        icon_path = ""
        try:
            iid = str(uuid.uuid4())[:8]
            icon_path = self._extract_and_save_icon(path, iid)
        except Exception:
            icon_path = ""
        # 添加到配置
        item = self.cfg.add_item(cat, real_path, x, y, name=item_name, icon_path=icon_path)
        # 创建图标显示
        try:
            self._create_icon(cat, item)
        except Exception as e:
            print(f"[ERROR] 创建图标失败: {e}")
        self._set_status(f"已添加 [{self.cfg.cat_name(cat)}]: {item['name']}")
        QTimer.singleShot(0, self._adjust_all_container_heights)
        return item

    def _extract_and_save_icon(self, path, item_id):
        """从exe/lnk提取高清图标并保存到本地assets目录, 返回本地路径。
        快捷方式先解析出真实 exe，再从真实 exe 提取大图标。"""
        assets_dir = self.cfg.assets
        os.makedirs(assets_dir, exist_ok=True)
        # 用 PNG 保存（Qt 对 PNG 高清缩放支持更好，ICO 只支持到 256）
        icon_path = os.path.join(assets_dir, f"{item_id}.png")

        # 解析 .lnk 快捷方式 -> 真实 exe
        real_path = resolve_shortcut(path) if path.lower().endswith(".lnk") else path
        if not real_path or not os.path.exists(real_path):
            real_path = path

        def _save_pixmap(pm):
            if pm is None or pm.isNull():
                return False
            # 统一缩放到 256x256 高清，保持比例
            if pm.width() < 256 or pm.height() < 256:
                pm = pm.scaled(256, 256, Qt.KeepAspectRatio,
                               Qt.SmoothTransformation)
            try:
                pm.save(icon_path, "PNG")
                return os.path.exists(icon_path) and os.path.getsize(icon_path) > 0
            except Exception:
                return False

        # 1) 优先 QFileIconProvider（Windows 系统 jumbo 高清图标，已验证 256x256）
        try:
            from PySide6.QtWidgets import QFileIconProvider
            from PySide6.QtCore import QFileInfo
            provider = QFileIconProvider()
            icon = provider.icon(QFileInfo(real_path))
            pm = icon.pixmap(256, 256)
            if not pm.isNull() and not _pixmap_is_blank(pm) and _save_pixmap(pm):
                return icon_path
        except Exception:
            pass

        # 2) QIcon 提取（exe 内嵌多尺寸图标）
        try:
            icon = QIcon(real_path)
            if not icon.isNull():
                pm = icon.pixmap(256, 256)
                if not pm.isNull() and not _pixmap_is_blank(pm) and _save_pixmap(pm):
                    return icon_path
        except Exception:
            pass

        # 3) ctypes PrivateExtractIconsW + GDI 转换兜底
        try:
            hicon = _extract_hicon_ctypes(real_path, 256)
            if hicon:
                pm = _hicon_to_qpixmap(hicon)
                _destroy_hicon(hicon)
                if pm and not pm.isNull() and not _pixmap_is_blank(pm) and _save_pixmap(pm):
                    return icon_path
        except Exception:
            pass

        return ""

    def _stable_container_width(self, cat):
        """获取分类容器的稳定宽度（容器尚未布局/刚从托盘恢复时宽度可能为0，用最小宽度兜底）"""
        area = self.areas[cat]
        cw = area.container.width()
        min_w = get_container_width_for_12_icons()
        if cw is None or cw < min_w:
            cw = min_w
        return cw

    def _next_grid_pos(self, cat, exclude_iid=None):
        """从左上角开始, 按网格扫描找到第一个空闲位置 (使用self.icon_widgets字典, 更可靠)"""
        # 使用稳定宽度，避免容器未布局/托盘恢复时宽度为0导致图标全排到一列
        cw = self._stable_container_width(cat)
        # 使用统一的网格大小，确保所有图标对齐
        step_x, step_y = get_grid_size()
        margin = 8

        # 获取该分类所有已存在图标的位置 (使用字典, 不依赖container.children())
        occupied = []
        for (c, iid), w in self.icon_widgets.items():
            if c == cat and (exclude_iid is None or iid != exclude_iid):
                occupied.append(QRect(w.x(), w.y(), ICON_W, ICON_H))

        def collides(px, py):
            rect = QRect(px, py, ICON_W, ICON_H)
            for r in occupied:
                if rect.intersects(r):
                    return True
            return False

        # 网格扫描: 行数不限制, 支持无限添加
        max_cols = max(1, (cw - margin * 2) // step_x)
        for row in range(0, 500):
            for col in range(0, max_cols):
                px = margin + col * step_x
                py = margin + row * step_y
                if not collides(px, py):
                    return px, py
        # 极端兜底
        return margin, margin + 500 * step_y

    def _on_icon_dropped(self, to_cat, iid, pos):
        # 找到来源
        from_cat = None
        for cat in CATEGORIES:
            if (cat, iid) in self.icon_widgets:
                from_cat = cat
                break
        if from_cat is None:
            return

        x, y = self._find_free_pos(to_cat, pos.x(), pos.y(), exclude_iid=iid if from_cat == to_cat else None)

        if from_cat == to_cat:
            # 同分类内移动
            w = self.icon_widgets[(from_cat, iid)]
            w.move(x, y)
            self.cfg.move_item(from_cat, iid, x, y)
        else:
            # 跨分类移动
            w = self.icon_widgets.pop((from_cat, iid))
            w.setParent(None)
            # 重新创建到目标分类
            for d in self.cfg.items(from_cat):
                if d["id"] == iid:
                    d["x"], d["y"] = x, y
                    self.cfg.transfer_item(from_cat, to_cat, iid, x, y)
                    # transfer 已经移动了数据, 重新从目标取
                    for d2 in self.cfg.items(to_cat):
                        if d2["id"] == iid:
                            w2 = IconItem(d2, to_cat, self.areas[to_cat].container)
                            w2.open_app.connect(lambda p, _n=d2.get("name", ""): self._on_open_app(p, _n))
                            w2.run_as_admin.connect(lambda p, _n=d2.get("name", ""): self._on_run_as_admin(p, _n))
                            w2.open_folder.connect(open_in_folder)
                            w2.remove_me.connect(self._remove_icon)
                            w2.move(x, y)
                            w2.show()
                            self.icon_widgets[(to_cat, iid)] = w2
                            break
                    w.deleteLater()
                    break
        self._set_status(f"图标已移动到 [{self.cfg.cat_name(to_cat)}]")

    def _find_free_pos(self, cat, desired_x, desired_y, exclude_iid=None):
        """螺旋搜索找到不重叠的位置 (使用self.icon_widgets字典)"""
        area = self.areas[cat]
        container = area.container
        cw, ch = container.width(), container.height()

        # 获取该分类所有已存在图标的位置
        occupied = []
        for (c, iid), w in self.icon_widgets.items():
            if c == cat and (exclude_iid is None or iid != exclude_iid):
                occupied.append(QRect(w.x(), w.y(), ICON_W, ICON_H))

        def collides(px, py):
            rect = QRect(px, py, ICON_W, ICON_H)
            for r in occupied:
                if rect.intersects(r):
                    return True
            return False

        # 边界修正 (允许超出容器, 支持无限添加)
        desired_x = max(8, desired_x)
        desired_y = max(8, desired_y)

        if not collides(desired_x, desired_y):
            return desired_x, desired_y

        # 螺旋搜索
        spacing = max(6, ICON_W // 8)
        step = max(12, spacing)
        for radius in range(step, 2000, step):
            for angle in range(0, 360, 15):
                rad = math.radians(angle)
                px = int(desired_x + radius * math.cos(rad))
                py = int(desired_y + radius * math.sin(rad))
                px = max(8, px)
                py = max(8, py)
                if not collides(px, py):
                    return px, py
        return desired_x, desired_y

    # ----------------------------------------------------------
    # 设置
    def _open_notice(self):
        """打开公告标签页"""
        try:
            current_names = {k: self.cfg.cat_name(k) for k in CATEGORIES}
            current_theme = self.cfg.data.get("theme", DEFAULT_THEME)
            current_cursor = self.cfg.data.get("cursor_color", "default")
            current_resolution = self.cfg.data.get("resolution", DEFAULT_RESOLUTION)
            dlg = SettingsDialog(self, current_names, self.current_title, current_theme, current_cursor, current_resolution)
            dlg.tabs.setCurrentIndex(4)  # 切换到公告标签页
            dlg.exec()
        except Exception as e:
            print(f"[_open_notice error] {e}")

    def _open_settings(self):
        current_names = {k: self.cfg.cat_name(k) for k in CATEGORIES}
        current_theme = self.cfg.data.get("theme", DEFAULT_THEME)
        current_cursor = self.cfg.data.get("cursor_color", "default")
        current_resolution = self.cfg.data.get("resolution", DEFAULT_RESOLUTION)
        try:
            dlg = SettingsDialog(self, current_names, self.current_title, current_theme, current_cursor, current_resolution)
        except Exception as e:
            import traceback
            QMessageBox.critical(self, "设置打开失败", f"设置对话框打开出错:\n{e}\n\n{traceback.format_exc()}")
            return
        dlg.bg_changed.connect(self._on_bg_changed)
        dlg.autostart_changed.connect(self._on_autostart_changed)
        dlg.add_exe.connect(self._on_add_exe)
        dlg.category_names_changed.connect(self._on_cat_names_changed)
        dlg.app_title_changed.connect(self._on_app_title_changed)
        dlg.app_icon_changed.connect(self._on_app_icon_changed)
        dlg.theme_changed.connect(self._on_theme_changed)
        dlg.cursor_color_changed.connect(self._on_cursor_color_changed)
        dlg.resolution_changed.connect(self._on_resolution_changed)
        dlg.fx_toggled.connect(self._on_fx_toggled)
        dlg.fx_type_changed.connect(self._on_fx_type_changed)
        dlg.cursor_image_changed.connect(self._on_cursor_image_changed)
        dlg.icon_size_changed.connect(self._set_icon_size)
        # 打开设置期间暂停漂浮粒子，避免拖动设置窗口卡顿（关闭后恢复）
        try:
            if hasattr(self, 'bg') and self.bg:
                self.bg.set_floating_effect(False, self.bg.fx_type)
        except Exception:
            pass
        try:
            dlg.exec()
        finally:
            try:
                if hasattr(self, 'bg') and self.bg:
                    self.bg.set_floating_effect(True, self.bg.fx_type)
            except Exception:
                pass

    def _on_app_title_changed(self, new_title):
        self._show_island(f"软件名称已改为：{new_title}")
        self.current_title = new_title
        self.cfg.set_app_title(new_title)
        self.setWindowTitle(new_title)
        self.title_lbl.setText(new_title)
        if hasattr(self, 'tray'):
            self.tray.setToolTip(new_title)
        self._set_status(f"软件标题已更新为: {new_title}")

    def _apply_app_icon(self):
        """设置窗口图标, 优先自定义图标, 否则内置 app_icon.ico, 最后默认"""
        if self.current_icon_path and os.path.exists(self.current_icon_path):
            icon = QIcon(self.current_icon_path)
        else:
            _builtin = resource_path("app_icon.ico")
            if _builtin:
                icon = QIcon(_builtin)
            else:
                icon = create_default_app_icon()
        self.setWindowIcon(icon)

    def _on_app_icon_changed(self, icon_path):
        # 复制到 assets 目录
        import shutil
        fname = f"app_icon_{os.path.basename(icon_path)}"
        dst = os.path.join(self.cfg.assets, fname)
        if os.path.abspath(icon_path) != os.path.abspath(dst):
            shutil.copy2(icon_path, dst)
        self.current_icon_path = dst
        self.cfg.set_app_icon(dst)
        self._apply_app_icon()
        if hasattr(self, 'tray'):
            self.tray.setIcon(QIcon(dst))
        self._set_status(f"软件图标已更换: {os.path.basename(icon_path)}")

    def _on_cat_names_changed(self, names_dict):
        self.cfg.set_cat_names(names_dict)
        for key, name in names_dict.items():
            if key in self.areas:
                self.areas[key].set_category_name(name)
        self._set_status("分类标题已更新")

    def _on_resolution_changed(self, res_key):
        """分辨率切换，自动保存并调整窗口大小"""
        self._show_island(f"分辨率已切换：{res_key}")
        if res_key not in RESOLUTIONS:
            return
        w, h = RESOLUTIONS[res_key]
        self.cfg.data["resolution"] = res_key
        self.cfg.save()
        self.setFixedSize(w, h)
        # 重新居中
        screen = QApplication.primaryScreen().geometry()
        self.move((screen.width() - w) // 2, (screen.height() - h) // 2)
        self._set_status(f"✓ 分辨率已切换为: {res_key} ({w}x{h})")

    def _on_fx_toggled(self, enabled):
        """漂浮特效开关"""
        self.cfg.data["floating_effect"] = enabled
        self.cfg.save()
        if hasattr(self, 'bg') and self.bg:
            fx_type = self.cfg.data.get("floating_type", "fire")
            self.bg.set_floating_effect(enabled, fx_type)
        self._set_status(f"✓ 漂浮特效已{'开启' if enabled else '关闭'}")

    def _on_fx_type_changed(self, fx_type):
        """漂浮特效类型改变"""
        self.cfg.data["floating_type"] = fx_type
        self.cfg.save()
        if hasattr(self, 'bg') and self.bg and self.bg.fx_enabled:
            self.bg.set_floating_effect(True, fx_type)
        _fx_name = FX_TYPES.get(fx_type, fx_type)
        self._set_status(f"✓ 漂浮特效类型已切换为: {_fx_name}")
        try:
            self._show_island(f"漂浮特效已切换：{_fx_name}")
        except Exception:
            pass

    def _on_cursor_image_changed(self, image_path):
        """鼠标指针图片改变"""
        import os as _os
        self._show_island(f"鼠标指针图片已更换")
        if image_path:
            # 复制图片到资源目录，确保文件不会被删除或移动
            import shutil
            assets_dir = self.cfg.assets
            os.makedirs(assets_dir, exist_ok=True)
            ext = os.path.splitext(image_path)[1]
            if not ext:
                ext = '.png'  # 默认png格式
            dest = os.path.join(assets_dir, f"cursor_image{ext}")
            try:
                # 使用绝对路径
                dest = os.path.abspath(dest)
                shutil.copy2(image_path, dest)
                # 保存绝对路径，确保重启后可以找到文件
                self.cfg.data["cursor_image"] = dest
                self.cfg.save()
                # 验证文件是否存在
                if not os.path.exists(dest):
                    raise Exception(f"复制后文件不存在: {dest}")
                cursor = create_image_cursor(dest)
                self.setCursor(cursor)
                self._apply_cursor_to_all(self, cursor)
                self._set_status(f"✓ 鼠标指针图片已应用: {os.path.basename(dest)}")
            except Exception as e:
                print(f"[cursor image error] {e}")
                # 如果复制失败，尝试直接使用原始路径
                try:
                    if os.path.exists(image_path):
                        abs_path = os.path.abspath(image_path)
                        self.cfg.data["cursor_image"] = abs_path
                        self.cfg.save()
                        cursor = create_image_cursor(abs_path)
                        self.setCursor(cursor)
                        self._apply_cursor_to_all(self, cursor)
                        self._set_status(f"✓ 鼠标指针图片已应用（原始路径）: {os.path.basename(image_path)}")
                    else:
                        self._set_status("✗ 鼠标指针图片设置失败：文件不存在")
                except Exception as e2:
                    print(f"[cursor image fallback error] {e2}")
                    self._set_status("✗ 鼠标指针图片设置失败")
        else:
            # 恢复默认
            self.cfg.data["cursor_image"] = None
            self.cfg.save()
            self.setCursor(QCursor(Qt.ArrowCursor))
            self._apply_cursor_to_all(self, QCursor(Qt.ArrowCursor))
            self._set_status("✓ 已恢复默认鼠标指针")

    def _on_autostart_changed(self, enabled):
        """开机启动设置变化"""
        # 实际设置注册表启动项，这是关键！之前只显示消息没有实际设置
        success = set_autostart(bool(enabled))
        if success:
            if enabled:
                self._set_status("✓ 已设置开机自动启动（注册表已更新）")
            else:
                self._set_status("✓ 已取消开机自动启动（注册表已更新）")
        else:
            if enabled:
                self._set_status("✗ 设置开机启动失败，请以管理员身份运行")
            else:
                self._set_status("✗ 取消开机启动失败")

    def _on_bg_changed(self, val):
        if val == "__RESET__":
            self.cfg.set_background(None)
            if hasattr(self, 'bg'):
                self.bg._bg_is_builtin = False
            self._apply_background()
            self._set_status("🔄 已恢复默认主题")
        else:
            self.cfg.set_background(val)
            if hasattr(self, 'bg'):
                self.bg._bg_is_builtin = False
            self._apply_background()
            self._set_status(f"🖼 背景已更换: {os.path.basename(val)}")

    def _on_theme_changed(self, theme_key):
        """主题切换，自动保存并应用"""
        if theme_key not in THEMES:
            return
        self.cfg.set_theme(theme_key)
        self._apply_theme(theme_key)
        self._set_status(f"🎨 主题已切换: {THEMES[theme_key]['name']}")

    def _on_cursor_color_changed(self, color_key):
        """鼠标指针颜色切换，自动保存并应用"""
        cursor_name_map = {
            "default": "默认（系统箭头）",
            "anime1": "动漫·爱心指针",
            "anime2": "动漫·星星指针",
            "anime3": "动漫·猫爪指针",
            "anime4": "动漫·樱花指针",
            "anime5": "动漫·少女指针",
            "anime6": "动漫·彩虹指针",
            "anime7": "动漫·月星指针",
            "anime8": "动漫·猫咪指针",
            "anime9": "动漫·蝴蝶结指针",
            "anime10": "动漫·狐狸指针",
            "anime11": "动漫·柯南灰原哀指针",
            "anime12": "动漫·唐三小舞指针",
        }
        cursor_name = cursor_name_map.get(color_key, color_key)
        self._show_island(f"鼠标指针已切换：{cursor_name}")
        try:
            self.cfg.set_cursor_color(color_key)
            cursor = create_colored_cursor(color_key)
            self.setCursor(cursor)
            # 也设置到所有子控件
            self._apply_cursor_to_all(self, cursor)
            color_name = {"default": "默认",
                           "pink": "粉红", "purple": "魔幻紫", "yellow": "金黄", "cyan": "青色"}.get(color_key, color_key)
            self._set_status(f"🖱 鼠标指针颜色已切换: {color_name}")
        except Exception as e:
            print(f"[_on_cursor_color_changed error] {e}")
            self._set_status("指针颜色切换失败，已恢复默认")

    def _apply_cursor_to_all(self, widget, cursor):
        """递归设置所有子控件的光标 (安全版本)"""
        try:
            widget.setCursor(cursor)
            for child in widget.findChildren(QWidget):
                try:
                    child.setCursor(cursor)
                except Exception:
                    pass
        except Exception:
            pass

    def _restart_app(self):
        """重启应用以应用新配置"""
        import subprocess
        import time
        # 确保配置文件已经完全写入磁盘
        config_path = os.path.join(app_dir(), CONFIG_FILE)
        if os.path.exists(config_path):
            try:
                with open(config_path, 'r', encoding='utf-8') as f:
                    json.load(f)  # 验证JSON格式正确
            except Exception:
                pass
        # 延迟启动新进程，确保当前进程完全退出后再启动
        if getattr(sys, 'frozen', False):
            # 打包后的exe，直接启动新进程，不创建bat文件（避免杀毒误报）
            exe_path = sys.executable
            subprocess.Popen([exe_path])
        else:
            # 开发模式，直接启动
            subprocess.Popen([sys.executable, os.path.abspath(sys.argv[0])])
        QApplication.quit()

    def _export_all_software(self):
        """右键菜单：全部导出软件列表为JSON文件"""
        try:
            self._save_all()
            # 收集所有软件
            software_list = []
            for cat in CATEGORIES:
                for item in self.cfg.items(cat):
                    software_list.append({
                        "category": cat,
                        "name": item.get("name", ""),
                        "path": item.get("path", ""),
                        "icon_path": item.get("icon_path", ""),
                        "x": item.get("x", 10),
                        "y": item.get("y", 10),
                    })
            if not software_list:
                QMessageBox.information(self, "导出失败", "当前没有任何软件可导出！")
                return
            # 选择保存路径
            file_path, _ = QFileDialog.getSaveFileName(
                self, "导出软件列表", "游戏菜单软件列表_备份导出数据.json", "JSON文件 (*.json);;所有文件 (*.*)"
            )
            if not file_path:
                return
            export_data = {
                "export_time": time.strftime("%Y-%m-%d %H:%M:%S"),
                "app_title": self.current_title,
                "icon_size": self.cfg.data.get("icon_size", "medium"),
                "total": len(software_list),
                "software": software_list,
            }
            with open(file_path, 'w', encoding='utf-8') as f:
                json.dump(export_data, f, ensure_ascii=False, indent=2)
            QMessageBox.information(self, "导出成功", f"已导出 {len(software_list)} 个软件到:\n{file_path}")
            self._set_status(f"📤 已导出 {len(software_list)} 个软件")
        except Exception as e:
            QMessageBox.warning(self, "导出失败", f"导出软件列表时出错:\n{str(e)}")

    def _import_software(self):
        """右键菜单：从JSON文件导入软件，自动去重"""
        try:
            file_path, _ = QFileDialog.getOpenFileName(
                self, "导入软件列表", "", "JSON文件 (*.json);;所有文件 (*.*)"
            )
            if not file_path:
                return
            self._do_import_software_list(file_path, show_msg=True)
        except Exception as e:
            QMessageBox.warning(self, "导入失败", f"导入软件列表时出错:\n{str(e)}")

    def _import_software_list_from_file(self, file_path):
        """从指定JSON文件导入软件列表（拖放导入用），返回(导入,跳过,失败)"""
        return self._do_import_software_list(file_path, show_msg=False)

    def _do_import_software_list(self, file_path, show_msg=True):
        """实际的导入逻辑，可被按钮和拖放调用"""
        with open(file_path, 'r', encoding='utf-8-sig') as f:
            data = json.load(f)
        # 识别备份里保存的图标大小（大/中/小），导入前应用，使图标按备份尺寸显示
        _imp_size = data.get("icon_size") if isinstance(data, dict) else None
        if _imp_size in ICON_SIZES and _imp_size != self.cfg.data.get("icon_size"):
            _c = ICON_SIZES[_imp_size]
            globals()['ICON_PX'] = _c["px"]
            globals()['ICON_W'] = _c["w"]
            globals()['ICON_H'] = _c["h"]
            self.cfg.data["icon_size"] = _imp_size
        # 兼容多种格式：直接是软件列表，或包含software字段，或配置文件
        # format_recognized 标记是否识别出了"软件列表容器"（即使列表为空），
        # 用于区分"空备份(格式正确但无软件)"和"完全无法识别的文件"
        software_list = []
        format_recognized = False
        if isinstance(data, list):
            software_list = data
            format_recognized = True
        elif isinstance(data, dict):
            # 优先找 software 字段（标准导出格式）
            for key in ("software", "apps", "list", "data"):
                if key in data and isinstance(data[key], list):
                    software_list = data[key]
                    format_recognized = True
                    break
            # 完整配置格式：items 是 dict，每个分类是一个 list
            if not software_list and isinstance(data.get("items"), dict):
                format_recognized = True
                for cat_key in ("网络游戏", "单机游戏", "聊天娱乐"):
                    cat_items = data["items"].get(cat_key, [])
                    if isinstance(cat_items, list):
                        for item in cat_items:
                            if isinstance(item, dict) and "path" in item:
                                item["category"] = cat_key
                                software_list.append(item)
            # items 直接是 list 的格式
            if not software_list and isinstance(data.get("items"), list):
                software_list = data["items"]
                format_recognized = True
            # 顶层分类字段（旧格式）
            if not software_list:
                for cat_key in ("网络游戏", "单机游戏", "聊天娱乐", "online", "offline", "chat"):
                    if cat_key in data and isinstance(data[cat_key], list):
                        format_recognized = True
                        for item in data[cat_key]:
                            if isinstance(item, dict) and "path" in item:
                                item["category"] = cat_key
                                software_list.append(item)
            # 最后尝试找任何 list 类型的字段
            if not software_list:
                for k, v in data.items():
                    if isinstance(v, list) and v and isinstance(v[0], dict) and "path" in v[0]:
                        software_list = v
                        format_recognized = True
                        break
        if not software_list:
            # 格式正确（是游戏菜单导出的备份/配置）但里面没有软件：返回0，不报错
            if format_recognized:
                return 0, 0, 0
            # 完全无法识别的文件才报错
            raise ValueError("文件格式错误，无法识别软件列表。请选择游戏菜单导出的软件列表JSON文件")
        # 收集已存在的软件路径用于去重
        existing_paths = set()
        for cat in CATEGORIES:
            for item in self.cfg.items(cat):
                p = item.get("path", "").lower()
                if p:
                    existing_paths.add(p)
        # 导入软件
        imported = 0
        skipped = 0
        errors = 0
        for sw in software_list:
            path = sw.get("path", "")
            if not path:
                errors += 1
                continue
            # 去重：路径已存在则跳过
            if path.lower() in existing_paths:
                skipped += 1
                continue
            # 确定分类
            cat = sw.get("category", CATEGORIES[0])
            if cat not in CATEGORIES:
                cat = CATEGORIES[0]
            # 添加软件（自动提取图标），完整保留路径和位置
            try:
                name = sw.get("name", None)
                icon_path = sw.get("icon_path", "")
                new_item = self._add_item_with_icon(cat, path, custom_name=name)
                # 完整保留所有字段
                if new_item is not None:
                    new_item["path"] = path
                    if name:
                        new_item["name"] = name
                    if icon_path:
                        new_item["icon_path"] = icon_path
                    if "x" in sw:
                        new_item["x"] = sw["x"]
                    if "y" in sw:
                        new_item["y"] = sw["y"]
                existing_paths.add(path.lower())
                imported += 1
            except Exception as e:
                errors += 1
                import sys
                print(f"导入失败: {path} -> {e}", file=sys.stderr)
        # 只在没有坐标时才重新排列
        has_coords = any("x" in sw and "y" in sw for sw in software_list)
        if not has_coords:
            self._rearrange_all_icons()
        # 强制保存并刷新界面
        try:
            self._save_all()
            self._reload_all()
            self._deduplicate_icons()
            QTimer.singleShot(0, self._adjust_all_container_heights)
        except Exception:
            pass
        # 显示结果
        if show_msg:
            msg = f"导入完成！\n\n"
            msg += f"✅ 成功导入: {imported} 个\n"
            msg += f"⏭  已存在跳过: {skipped} 个\n"
            if errors > 0:
                msg += f"❌ 导入失败: {errors} 个\n"
            QMessageBox.information(self, "导入完成", msg)
        self._set_status(f"📥 导入 {imported} 个，跳过 {skipped} 个已存在")
        return imported, skipped, errors

    def _clear_all_icons(self):
        """清空所有图标控件（只清除界面显示，不修改配置，不保存）
        重启软件后图标会从配置文件重新加载恢复
        """
        try:
            # 确认对话框
            _mb = QMessageBox(self)
            _mb.setWindowTitle("确认清空")
            _mb.setText("确定要清空所有图标吗？\n\n"
                        "注意：只清除界面显示，不修改配置文件，不保存。\n"
                        "重启软件后图标会自动恢复。")
            _mb.setIcon(QMessageBox.Question)
            _b_clear = _mb.addButton("确定清空", QMessageBox.AcceptRole)
            _b_cancel = _mb.addButton("取消", QMessageBox.RejectRole)
            _mb.setDefaultButton(_b_cancel)
            _mb.exec()
            if _mb.clickedButton() != _b_clear:
                return
            # 清除所有图标控件
            count = 0
            for (cat, iid), w in list(self.icon_widgets.items()):
                w.setParent(None)
                w.deleteLater()
                count += 1
            self.icon_widgets.clear()
            # 更新分类计数显示
            for cat in CATEGORIES:
                area = self.areas.get(cat)
                if area:
                    area.update_icon_count(0)
            QTimer.singleShot(0, self._adjust_all_container_heights)
            self._set_status(f"✓ 已清空 {count} 个图标（未保存，重启后恢复）")
        except Exception as e:
            print(f"[_clear_all_icons error] {e}")
            QMessageBox.warning(self, "清空失败", f"清空图标时出错:\n{str(e)}")

    def _apply_theme(self, theme_key):
        """应用主题到背景和UI"""
        theme = THEMES.get(theme_key, THEMES[DEFAULT_THEME])
        theme_name = theme.get("name", theme_key)
        self._show_island(f"主题已切换：{theme_name}")
        # 更新背景
        if hasattr(self, 'bg'):
            self.bg.set_theme(theme_key)
        # 更新UI强调色 (标题栏、分类标题等)
        accent = theme["accent"]
        ar, ag, ab = theme["accent_rgb"]
        # 同时更新所有图标名称标签的颜色，确保主题切换后文字颜色正确
        font_size = max(10, min(14, ICON_PX // 3 + 2))
        for (cat, iid), w in self.icon_widgets.items():
            if hasattr(w, 'name_lbl'):
                w.name_lbl.setStyleSheet(f"color:rgba({ar},{ag},{ab},255);font-size:{font_size}px;font-weight:bold;font-family:'Microsoft YaHei','Consolas';")
        # 更新标题栏样式
        if hasattr(self, 'title_bar'):
            self.title_bar.setStyleSheet(f"""
                QFrame {{ background:rgba({ar//4},{ag//4},{ab//4},200);
                         border:1px solid rgba({ar},{ag},{ab},120); border-radius:10px; }}
                QLabel {{ color:{accent}; font-family:'Consolas','Microsoft YaHei'; }}
            """)
        # 更新分类区域标题颜色
        if hasattr(self, 'areas'):
            for area in self.areas.values():
                area.title_btn.setStyleSheet(f"""
                    QPushButton {{ color:rgba({ar},{ag},{ab},255); font-size:17px; font-weight:bold;
                        font-family:'Microsoft YaHei','Consolas'; text-align:left;
                        background:transparent; border:none;
                        border-bottom:1px solid rgba({ar},{ag},{ab},100);
                        border-top-left-radius:8px; border-top-right-radius:8px;
                        padding-left:12px; }}
                    QPushButton:hover {{ background:rgba({ar//4},{ag//4},{ab//4},20); color:rgba({ar},{ag},{ab},255); }}
                """)

    def _on_add_exe(self, path, name=None, category=None):
        """通过设置添加的 exe, 可自定义名称和分类, 网格排列"""
        if not is_executable(path):
            QMessageBox.warning(self, "格式错误", "只能添加 .exe 可执行文件！")
            return
        cat = category if category in CATEGORIES else CATEGORIES[0]
        self._add_item_with_icon(cat, path, custom_name=name)

    # ----------------------------------------------------------
    # 保存
    def _save_all(self):
        # 重启时不保存，防止用旧配置覆盖新导入的配置
        if getattr(self, '_restarting', False) or getattr(self.cfg, '_restarting', False):
            return
        # 保存前记录各分类数量
        before_counts = {cat: len(self.cfg.items(cat)) for cat in CATEGORIES}
        # 从 widget 位置回写配置（只更新位置，不删除任何item）
        for (cat, iid), w in self.icon_widgets.items():
            try:
                self.cfg.move_item(cat, iid, w.x(), w.y())
            except Exception as e:
                print(f"[保存位置失败] {cat} - {iid}: {e}")
        # 确保所有分类都存在
        for cat in CATEGORIES:
            if cat not in self.cfg.data.get("items", {}):
                self.cfg.data["items"][cat] = []
        # 保存后记录数量，对比是否丢失
        after_counts = {cat: len(self.cfg.items(cat)) for cat in CATEGORIES}
        for cat in CATEGORIES:
            if after_counts[cat] < before_counts[cat]:
                print(f"[警告] 保存后 {cat} 数量减少: {before_counts[cat]} -> {after_counts[cat]}")
        self.cfg.save()
        self._set_status("💾 配置已保存")

    # ----------------------------------------------------------
    # 滚动公告
    def _start_notice_scroll(self, notice_text=None):
        """启动公告滚动"""
        try:
            if notice_text:
                self.notice_text_lbl.setText(f"  {notice_text}  ")
            # 确保文字不换行，使用实际宽度
            self.notice_text_lbl.adjustSize()
            # 初始位置：从容器右侧进入（绝对定位，布局不会覆盖move）
            wrap_w = self.notice_scroll_wrap.width()
            # 窗口尚未完成布局时（宽度为0），延迟重试
            if wrap_w <= 0:
                retry = getattr(self, '_notice_retry', 0) + 1
                self._notice_retry = retry
                if retry <= 5:
                    QTimer.singleShot(100, lambda: self._start_notice_scroll(notice_text))
                return
            self._notice_retry = 0
            self._notice_scroll_x = wrap_w
            self.notice_text_lbl.move(self._notice_scroll_x, (self.notice_scroll_wrap.height() - self.notice_text_lbl.height()) // 2)
            # 滚动定时器：每30ms移动1px
            self._notice_scroll_timer = QTimer(self)
            self._notice_scroll_timer.timeout.connect(self._tick_notice_scroll)
            self._notice_scroll_timer.start(30)
        except Exception as e:
            print(f"[notice scroll error] {e}")

    def _tick_notice_scroll(self):
        """公告滚动tick"""
        try:
            wrap_w = self.notice_scroll_wrap.width()
            lbl_w = self.notice_text_lbl.width()
            if lbl_w <= 0 or wrap_w <= 0:
                return
            # 左移1px
            self._notice_scroll_x -= 1
            # 文字完全移出左侧后，重置到右侧
            if self._notice_scroll_x < -lbl_w:
                self._notice_scroll_x = wrap_w + 20
            y = (self.notice_scroll_wrap.height() - self.notice_text_lbl.height()) // 2
            self.notice_text_lbl.move(self._notice_scroll_x, y)
        except Exception as e:
            print(f"[notice tick error] {e}")

    def _fetch_notice_and_check_update(self):
        """从HTML网页获取公告+检查更新（后台线程：先显示缓存，再并行刷新）"""
        import threading
        def do_fetch():
            try:
                import time as _t
                # 1. 先应用本地缓存：标题栏版本+滚动公告 立即显示（不等网络）
                cached = load_update_cache()
                if cached:
                    c_notice = cached.get("notice", "") or ""
                    c_version = cached.get("version", "") or ""
                    if c_notice or c_version:
                        try:
                            self.remote_data_ready.emit(c_notice, c_version)
                        except Exception:
                            pass
                # 2. 并行请求主/备用URL，最快结果生效（单次最多等5秒）
                has_update, latest_version, download_url, download_url2, download_password, notice, release_date, update_content, error = check_for_updates()
                try:
                    with open('fetch_log.txt', 'a', encoding='utf-8') as _f:
                        _f.write(f"{_t.strftime('%Y-%m-%d %H:%M:%S')} has_update={has_update} latest={latest_version} url={download_url} url2={download_url2} pwd={download_password} error={error}\n")
                except Exception:
                    pass
                if not error:
                    # 保存缓存，下次启动立即显示
                    save_update_cache({
                        "version": latest_version,
                        "download_url": download_url,
                        "download_url2": download_url2,
                        "download_password": download_password,
                        "notice": notice,
                        "release_date": release_date,
                        "update_content": update_content,
                        "time": _t.strftime('%Y-%m-%d %H:%M:%S'),
                    })
                if notice or latest_version:
                    # 用Signal跨线程投递到主线程（自动QueuedConnection）
                    try:
                        self.remote_data_ready.emit(notice, latest_version)
                    except Exception:
                        pass
                if has_update and not error:
                    try:
                        self.update_available.emit(latest_version, download_url, download_url2, download_password, notice, release_date, update_content)
                    except Exception:
                        pass
            except Exception as e:
                print(f"[fetch notice error] {e}")
        threading.Thread(target=do_fetch, daemon=True).start()

    def _apply_remote_data(self, notice_text, latest_version):
        """应用网页获取的公告到滚动条 + 更新最新版本显示（主线程）"""
        try:
            if hasattr(self, 'notice_text_lbl') and notice_text:
                # 格式化公告：单行显示，换行符替换为分隔符，清理回车残留
                one_line = notice_text.replace('\r\n', '  |  ').replace('\r', '').replace('\n', '  |  ')
                self.notice_text_lbl.setText(f"📢 {one_line}  ")
                self.notice_text_lbl.adjustSize()
                # 重置滚动位置
                self._notice_scroll_x = self.notice_scroll_wrap.width()
                self.notice_text_lbl.move(self._notice_scroll_x, (self.notice_scroll_wrap.height() - self.notice_text_lbl.height()) // 2)
            # 更新标题栏版本信息（当前版本 + 最新版本）
            if hasattr(self, 'version_info_lbl'):
                if latest_version:
                    self.version_info_lbl.setText(f"当前版本{format_version(APP_VERSION)}  最新版本：{format_version(latest_version)}")
                else:
                    self.version_info_lbl.setText(f"当前版本{format_version(APP_VERSION)}  最新版本：--")
        except Exception as e:
            print(f"[apply remote notice error] {e}")

    # ----------------------------------------------------------
    # 北京时间时钟
    def _ensure_particles(self):
        # 粒子保险丝：每3秒检查，若特效已开启但粒子系统未运行（启动/托盘恢复/最小化恢复等
        # 各种路径可能清空粒子），强制重建，确保漂浮特效始终显示
        try:
            if not self.cfg.data.get("floating_effect", True):
                return
            # 最小化或隐藏（托盘）时跳过（应保持特效关闭，由恢复窗口化时重启）
            if self.isMinimized() or not self.isVisible():
                return
            bg = getattr(self, 'bg', None)
            if bg is None:
                return
            if not bg.fx_enabled:
                bg.set_floating_effect(True, self.cfg.data.get("floating_type", "fire"))
            elif bg.particles is None or not bg.particle_timer or not bg.particle_timer.isActive():
                bg.set_floating_effect(True, bg.fx_type)
        except Exception:
            pass

    def _start_title_shimmer(self):
        """标题流光：文字颜色在 粉→浅粉→金→白 间平滑循环，外发光颜色同步、
        强度呼吸（QVariantAnimation 驱动，永久循环）。"""
        try:
            from PySide6.QtCore import QVariantAnimation
            import math
            stops = [(255, 51, 170), (255, 150, 210), (255, 215, 0), (255, 255, 255)]
            n = len(stops) - 1
            base_css = ("; font-size:30px; font-weight:bold;"
                        "font-family:'Consolas','Microsoft YaHei'; letter-spacing:4px;")
            an = QVariantAnimation(self)
            an.setStartValue(0.0)
            an.setEndValue(float(n))
            an.setDuration(3800)
            an.setLoopCount(-1)

            def on(v):
                i = int(math.floor(v))
                t = v - i
                a = stops[i]
                b = stops[min(i + 1, n)]
                c = tuple(int(a[k] + (b[k] - a[k]) * t) for k in range(3))
                self.title_lbl.setStyleSheet(
                    "color:rgb(%d,%d,%d)%s" % (c[0], c[1], c[2], base_css))
                self._title_glow.setColor(QColor(c[0], c[1], c[2]))
                self._title_glow.setBlurRadius(
                    15 + 13 * (0.5 + 0.5 * math.sin(v * math.pi)))

            an.valueChanged.connect(on)
            an.start()
            self._title_shimmer = an
        except Exception:
            pass

    def _ambient_particles(self):
        """标题/版本框/时间框光感粒子：柔和光点向上飘、闪烁。"""
        try:
            if self.isMinimized() or not self.isVisible():
                return
            from PySide6.QtCore import QPoint as _QP
            ov = ParticleOverlay(duration=1500, parent=self, geo=self.geometry())
            def _rect_of(w):
                r = w.rect()
                p0 = w.mapTo(_QP(0, 0))
                return QRect(p0.x(), p0.y(), r.width(), r.height())
            ov.add_rise(_rect_of(self.title_lbl), count=3,
                        colors=["#ff9ecb","#ffd76b","#ffffff"], spd=1.5, rays=0.45)
            ov.add_rise(_rect_of(self.version_info_lbl), count=3,
                        colors=["#ffd76b","#fff7d6"], spd=1.4, rays=0.45)
            ov.add_rise(_rect_of(self.time_lbl), count=3,
                        colors=["#ff9ecb","#bfe6ff"], spd=1.4, rays=0.45)
            ov.start()
            self._ambient_ov = ov
        except Exception:
            pass

    def _add_glow_effect(self, widget, rgb, period=1600, rmin=6, rmax=22, alpha=180):
        """给控件加一个平滑往返的'呼吸发光'边框特效。rgb:(r,g,b)；period:周期(ms)。"""
        try:
            from PySide6.QtWidgets import QGraphicsDropShadowEffect
            from PySide6.QtGui import QColor
            from PySide6.QtCore import QPropertyAnimation, QSequentialAnimationGroup, QEasingCurve
            eff = QGraphicsDropShadowEffect(widget)
            eff.setOffset(0, 0)
            eff.setColor(QColor(rgb[0], rgb[1], rgb[2], alpha))
            eff.setBlurRadius(rmin)
            widget.setGraphicsEffect(eff)
            a1 = QPropertyAnimation(eff, b'blurRadius', eff)
            a1.setDuration(period // 2)
            a1.setStartValue(rmin); a1.setEndValue(rmax)
            a1.setEasingCurve(QEasingCurve.InOutSine)
            a2 = QPropertyAnimation(eff, b'blurRadius', eff)
            a2.setDuration(period // 2)
            a2.setStartValue(rmax); a2.setEndValue(rmin)
            a2.setEasingCurve(QEasingCurve.InOutSine)
            g = QSequentialAnimationGroup(widget)
            g.addAnimation(a1); g.addAnimation(a2)
            g.setLoopCount(-1)
            g.start()
            if not hasattr(self, '_glow_anims'):
                self._glow_anims = []
            self._glow_anims.append(g)
            return eff
        except Exception:
            return None

