    # 天气功能
    def _init_weather_ui(self):
        """标题栏天气胶囊（时间框前），点击查看7日预报"""
        self.weather_lbl = QLabel("  天气加载中…")
        self.weather_lbl.setStyleSheet("""
            color:#7ee7ff; font-size:14px; font-weight:bold;
            font-family:'Microsoft YaHei','Consolas';
            background:rgba(80,180,255,25); border:1px solid rgba(120,220,255,150);
            border-radius:13px; padding:3px 12px;
        """)
        self.weather_lbl.setCursor(Qt.PointingHandCursor)
        self._weather_data = None
        self._weather_click = _WeatherClickFilter(self._show_weather_dialog)
        self.weather_lbl.installEventFilter(self._weather_click)
        # 天气不添加发光特效，避免卡顿
        try:
            pass
        except Exception:
            pass

    def _refresh_weather(self, force=False):
        """后台：缓存有效直接用，否则获取新7日；完成后主线程更新胶囊"""
        import threading
        def work():
            data = None
            if not force:
                c = load_weather_cache()
                if c and weather_cache_fresh(c):
                    data = c
            if data is None:
                try:
                    data = fetch_weather_7d()
                    save_weather_cache(data)
                except Exception:
                    data = load_weather_cache()  # 获取失败用旧缓存兜底
            if data:
                self.weather_ready.emit(data)  # 跨线程 QueuedConnection 到主线程
        threading.Thread(target=work, daemon=True).start()

    def _today_weather(self, data):
        today_s = time.strftime("%Y-%m-%d")
        for x in data.get("days", []):
            if x.get("date") == today_s:
                return x
        ds = data.get("days", [])
        return ds[0] if ds else None

    def _apply_weather(self, data):
        self._weather_data = data
        t = self._today_weather(data)
        if t:
            # 底部显示IP地区（只显示省+市，不显示区）+ 温度和图标
            cur_temp = data.get("cur_temp")
            cur_code = data.get("cur_code")
            region = data.get("region", "")
            # 简单粗暴：只保留省+市，去掉所有区/县部分
            # 找到第二个"市"字（省后面的市），或者直接截断到第一个"市"字后
            # 格式：四川省成都市新都区 → 四川省成都市
            import re as _re
            # 匹配 "XX省XX市" 或 "XX市XX区" 模式
            m = _re.match(r'^(.{2,4}省.{2,6}市)', region)
            if m:
                region = m.group(1)
            else:
                m = _re.match(r'^(.{2,4}市)', region)
                if m:
                    region = m.group(1)
            if cur_temp is not None:
                if cur_code is not None:
                    _cdesc, _cicon = WMO_WEATHER.get(cur_code, (t.get("desc",""), t.get("icon","🌡️")))
                else:
                    _cicon = t.get("icon", "🌡️")
                self.weather_lbl.setText(
                    f"  {_cicon} {region} {cur_temp}° ")
            else:
                self.weather_lbl.setText(
                    f"  {t['icon']} {region} {t['tmin']}~{t['tmax']}° ")
            # 天气胶囊脉动动画（图标呼吸效果）
            try:
                self._weather_pulse = 0
                if not hasattr(self, '_weather_pulse_timer') or self._weather_pulse_timer is None:
                    self._weather_pulse_timer = QTimer(self)
                    self._weather_pulse_timer.timeout.connect(self._weather_pulse_step)
                self._weather_pulse_timer.start(800)
            except Exception:
                pass
            # 天气胶囊周围粒子特效
            try:
                from PySide6.QtCore import QPoint as _QP
                ov = ParticleOverlay(duration=2000, parent=self, geo=self.weather_lbl.geometry())
                def _rect_of(w):
                    r = w.rect()
                    p0 = w.mapTo(_QP(0, 0))
                    return QRect(p0.x(), p0.y(), r.width(), r.height())
                ov.add_rise(_rect_of(self.weather_lbl), count=10,
                            colors=["#ffd76b","#ff9ecb","#bfe6ff","#ffffff"], spd=1.2, rays=0.4)
                ov.start()
                self._weather_ov = ov
            except Exception:
                pass
            # 根据今天天气自动切换漂浮粒子特效
            try:
                wcode = cur_code if cur_code is not None else t.get("code", 0)
                is_rain = wcode in (51,53,55,56,57,61,63,65,66,67,80,81,82,95,96,99)
                is_snow = wcode in (71,73,75,77,85,86)
                is_sunny = wcode in (0, 1, 2, 3)
                if is_rain:
                    fx_type = "rain"
                elif is_snow:
                    fx_type = "snow"
                elif is_sunny:
                    fx_type = "glow"
                else:
                    fx_type = None
                if fx_type is not None and hasattr(self, 'bg') and self.bg:
                    if self.cfg.data.get("floating_effect", True):
                        self.bg.set_floating_effect(True, fx_type)
                        self.bg._rebuild_particles()
            except Exception as _e:
                print(f"[weather fx] {_e}")
        else:
            self.weather_lbl.setText("  天气暂无 ")

    def _weather_pulse_step(self):
        """天气胶囊图标脉动动画：在蓝色发光和正常之间切换"""
        try:
            self._weather_pulse = (self._weather_pulse + 1) % 2
            if self._weather_pulse == 0:
                self.weather_lbl.setStyleSheet("""
                    color:#7ee7ff; font-size:14px; font-weight:bold;
                    font-family:'Microsoft YaHei','Consolas';
                    background:rgba(80,180,255,45); border:2px solid rgba(150,230,255,220);
                    border-radius:13px; padding:3px 12px;
                """)
            else:
                self.weather_lbl.setStyleSheet("""
                    color:#7ee7ff; font-size:14px; font-weight:bold;
                    font-family:'Microsoft YaHei','Consolas';
                    background:rgba(80,180,255,20); border:1px solid rgba(120,220,255,120);
                    border-radius:13px; padding:3px 12px;
                """)
        except Exception:
            pass

    def _show_weather_dialog(self):
        try:
            self._show_island("打开天气预报")
        except Exception:
            pass
        data = getattr(self, "_weather_data", None)
        if not data:
            try: self._set_status("天气数据加载中，请稍后再点")
            except Exception: pass
            self._refresh_weather()
            return
        from datetime import datetime as _dt
        dlg = QDialog(self)
        dlg.setWindowTitle(f"{data.get('region','本地')} · 7日天气预报")
        dlg.setFixedSize(460, 560)
