            temp_lbl.setStyleSheet("color:#ffd27f; font-size:13px; font-weight:bold;")
            pop_lbl = QLabel(f"💧{x['pop']}%")
            pop_lbl.setStyleSheet("color:#8fd0ff; font-size:12px;")
